window.__D("text/zohar-hebrew-translation/c005",{"p":[[9522011233,"<p>וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (ישעיה יג) הִנֵּה יוֹם ה' בָּא אַכְזָרִי וְגוֹ'. הִנֵּה יוֹם ה' בָּא - זֶה בֵּית דִּין שֶׁלְּמַטָּה. בָּא - כְּמוֹ שֶׁנֶּאֱמַר הַבָּאָה אֵלַי עָשׂוּ. מִשּׁוּם שֶׁלֹּא עוֹשֶׂה דִין עַד שֶׁנִּכְנָס וְנוֹטֵל רְשׁוּת. כְּמוֹ זֶה קֵץ כָּל בָּשָׂר בָּא לְפָנַי.</p>\n<p>דָּבָר אַחֵר הִנֵּה יוֹם ה' בָּא - זֶהוּ הַמַּשְׁחִית שֶׁלְּמַטָּה כְּשֶׁנּוֹטֵל אֶת הַנְּשָׁמָה, מִשּׁוּם כָּךְ אַכְזָרִי וְעֶבְרָה. לָשׂוּם הָאָרֶץ לְשַׁמָּה - זוֹ סְדם וַעֲמֹרָה. וְחַטָּאֶיהָ יַשְׁמִיד מִמֶּנָּה - אֵלּוּ יוֹשְׁבֵי הָאָרֶץ.</p>\n<p>מַה כָּתוּב אַחֲרָיו? כִּי כוֹכְבֵי הַשָּׁמַיִם וּכְסִילֵיהֶם וְגוֹ'. שֶׁהֲרֵי מֵהַשָּׁמַיִם הִמְטִיר עֲלֵיהֶם אֵשׁ וְהֶעֱבִירָם מֵהָעוֹלָם. אַחַר כָּךְ מַה כָּתוּב? אוֹקִיר אֱנוֹשׁ מִפָּז וְגוֹ'. זֶה אַבְרָהָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱלָה אוֹתוֹ עַל כָּל בְּנֵי הָעוֹלָם.</p>\n<p>רַבִּי יְהוּדָה הֵקִים אֶת הַפְּסוּקִים הַלָּלוּ בַּיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, שֶׁבְּאוֹתוֹ הַיּוֹם חָשְׁכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְחָשְׁכוּ שָׁמַיִם וְכוֹכָבִים. רַבִּי אֶלְעָזָר מְבָאֵר אֶת הַפְּסוּקִים הַלָּלוּ בַּיּוֹם שֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כְּנֶסֶת יִשְׂרָאֵל מֵהֶעָפָר, וְאוֹתוֹ יוֹם נוֹדָע לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה'. וְאוֹתוֹ הַיּוֹם הוּא יוֹם נְקָמָה, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִנְקֹם מִשְּׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא יַעֲשֶׂה נְקָמוֹת בִּשְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, אָז אוֹקִיר אֱנוֹשׁ מִפָּז - זֶה מֶלֶךְ הַמָּשִׁיחַ שֶׁיִּתְעַלֶּה וְיִתְכַּבֵּד עַל כָּל בְּנֵי הָעוֹלָם, וְכָל בְּנֵי הָעוֹלָם יַעַבְדוּ וְיִשְׁתַּחֲווּ לְפָנָיו, שֶׁכָּתוּב (תהלים עב) לְפָנָיו יִכְרְעוּ צִיִּים וְגוֹ' מַלְכֵי תַרְשִׁישׁ וְגוֹ'.</p>\n<p>בּא רְאֵה, אַף עַל גַּב שֶׁנְּבוּאָה זוֹ נֶאֶמְרָה עַל בָּבֶל - בַּכֹּל זֶה נֶאֱמַר. שֶׁהֲרֵי רָאִינוּ בְּפָרָשָׁה זוֹ שֶׁכָּתוּב כִּי יְרַחֵם ה' אֶת יַעֲקֹב, וְכָתוּב וּלְקָחוּם עַמִּים וֶהֱבִיאוּם אֶל מְקוֹמָם.</p>\n<p>וַה' הִמְטִיר עַל סְדם - זוֹ הַדַּרְגָּה שֶׁל בֵּית דִּין שֶׁלְּמַטָּה שֶׁנּוֹטֵל רְשׁוּת מִלְמַעְלָה. רַבִּי יִצְחָק אָמַר, שֶׁעוֹשֶׂה הַדִּין בְּרַחֲמִים, שֶׁכָּתוּב מֵאֵת ה' מִן הַשָּׁמָיִם, כְּדֵי לְהִמָּצֵא דִין עִם רַחֲמִים. וְאִם תֹּאמַר מָה הָרַחֲמִים כָּאן? שֶׁכָּתוּב וַיְהִי בְּשַׁחֵת אֱלֹהִים אֶת עָרֵי הַכִּכָּר וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וְגוֹ'. וְאַחַר כָּךְ יָצְאוּ מִמֶּנּוּ שְׁתֵּי אֻמּוֹת שְׁלֵמוֹת וְזָכָה שֶׁיֵּצֵא מִמֶּנּוּ דָּוִד וּשְׁלֹמֹה הַמֶּלֶךְ.</p>\n<p>רְאֵה מַה כָּתוּב? וַיְהִי כְהוֹצִיאָם אֹתָם הַחוּצָה וַיֹּאמֶר בֹּא רְאֵה, בְּשָׁעָה שֶׁהַדִּין שׁוֹרֶה בָעוֹלָם, הֲרֵי לָמַדְנוּ שֶׁלֹּא צָרִיךְ לִבְנֵי אָדָם לְהִמָּצֵא בַשּׁוּק, בִּגְלַל שֶׁמִּכֵּיוָן שֶׁשּׁוֹרֶה דִין, לֹא מַבְחִין בֵּין זַכַּאי לְחַיָּב, וְלֹא צָרִיךְ לְהִמָּצֵא שָׁם. וַהֲרֵי לָמַדְנוּ שֶׁבְּסִבַּת זֶה נִסְגַּר נֹחַ בַּתֵּבָה וְלֹא נִמְצָא בָעוֹלָם בְּשָׁעָה שֶׁהַדִּין נַעֲשָׂה, וְכָתוּב (שמות יב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר, עַד שֶׁיֵּעָשֶׂה הַדִּין. וּמִפְּנֵי כָּךְ, וַיֹּאמֶר הִמָּלֵט עַל נַפְשֶׁךְ אַל תַּבִּיט אַחֲרֶיךְ וְגוֹ'.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יִצְחָק, הַדִּין שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמַּבּוּל וְהַדִּין שֶׁל סְדם, שְׁנֵיהֶם דִּינֵי הַגֵּיהִנֹּם הָיוּ, כִּי רִשְׁעֵי הַגֵּיהִנֹּם נִדּוֹנִים בָּאֵשׁ וּבַמַּיִם.</p>\n<p>אָמַר רַבִּי יִצְחָק, סְדם נִדּוֹנָה בְּדִין הַגֵּיהִנֹּם, שֶׁכָּתוּב וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מֵאֵת ה' מִן הַשָּׁמָיִם. זֶה מִצַּד שֶׁל מַיִם וְזֶה מִצַּד שֶׁל אֵשׁ. זֶה וְזֶה הוּא דִּין הַגֵּיהִנֹּם, וְרִשְׁעֵי הַגֵּיהִנֹּם נִדּוֹנִים בִּשְׁנֵי הַדִּינִים הַלָּלוּ.</p>\n<p>אָמַר לוֹ, הַדִּין שֶׁל רִשְׁעֵי הַגֵּיהִנֹּם שְׁנֵים עָשָׂר חֳדָשִׁים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלֶה אוֹתָם מֵהַגֵּיהִנֹּם, וְשָׁם מִתְלַבְּנִים וְיוֹשְׁבִים לְשַׁעַר הַגֵּיהִנֹּם, וְרוֹאִים אוֹתָם רְשָׁעִים שֶׁנִּכְנְסוּ וְדָנִים אוֹתָם שָׁם, וְהֵם מְבַקְשִׁים עֲלֵיהֶם רַחֲמִים, וְאַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם וּמַכְנִיס אוֹתָם בַּמָּקוֹם שֶׁצָּרִיךְ לָהֶם. מֵאוֹתוֹ יוֹם וָהָלְאָה הַגּוּף שׁוֹכֵךְ בֶּעָפָר וְהַנְּשָׁמָה יוֹרֶשֶׁת מְקוֹמָהּ כָּרָאוּי לָהּ.</p>\n<p>בֹּא רְאֵה, שֶׁהֲרֵי נֶאֱמַר שֶׁאֲפִלּוּ אוֹתָם בְּנֵי הַמַּבּוּל לֹא נִדּוֹנוּ אֶלָּא בְּאֵשׁ וּמַיִם. מַיִם קְרִירִים יָרְדוּ מִלְמַעְלָה, וּמַיִם רוֹתְחִים עָלוּ מִלְּמַטָּה כְּאֵשׁ. וְנִדּוֹנוּ בִּשְׁנֵי דִינִים, מִשּׁוּם שֶׁדִּין שֶׁל מַעְלָה כָּךְ הוּא, וְלָכֵן בִּסְדם גָּפְרִית וָאֵשׁ.</p>\n<p>אָמַר לוֹ, הַאִם יָקוּמוּ לְיוֹם הַדִּין? אָמַר לוֹ, הֲרֵי נִתְבָּאֵר, אֲבָל אֵלּוּ שֶׁל סְדם וַעֲמֹרָה לֹא יָקוּמוּ, וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב (דברים כט) גָּפְרִית וָמֶלַח שְׂרֵפָה כָל אַרְצָהּ לֹא תִזָּרַע וְלֹא תַצְמִחַ וְגוֹ', אֲשֶׁר הָפַךְ ה' בְּאַפּוֹ וּבַחֲמָתוֹ. אֲשֶׁר הָפַךְ ה' - בָּעוֹלָם הַזֶּה. בְּאַפּוֹ - בָּעוֹלָם הַבָּא. וּבַחֲמָתוֹ - בִּזְמַן שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים. אָמַר לוֹ, בּא רְאֵה, כְּמוֹ שֶׁאַרְצָם אָבְדָה לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, גַּם כָּךְ הֵם אָבְדוּ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>וּבֹא רְאֵה שֶׁדִּין הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין כְּנֶגֶד דִּין. הֵם לֹא הֵשִׁיבוּ אֶת נֶפֶשׁ הֶעָנִי בְּמַאֲכָל וּמַשְׁקֶה - גַּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הֵשִׁיב נַפְשָׁם לָעוֹלָם הַבָּא.</p>\n<p>וּבֹא רְאֵה, הֵם נִמְנְעוּ מִצְּדָקָה שֶׁנִּקְרֵאת חַיִּים - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא מָנַע מֵהֶם חַיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וּכְמוֹ שֶׁהֵם מָנְעוּ דְּרָכִים וּשְׁבִילִים מִבְּנֵי הָעוֹלָם - כָּךְ גַּם הַקָּדוֹשׁ בָּרוּךְ הוּא מָנַע מֵהֶם דְּרָכִים וּשְׁבִילִים שֶׁל רַחֲמִים לְרַחֵם עֲלֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>רַבִּי אַבָּא אָמַר, כָּל בְּנֵי הָעוֹלָם יַעַמְדוּ וְיָקוּמוּ לַדִּין, וַעֲלֵיהֶם כָּתוּב (דניאל יב) וְאֵלֶּה לַחֲרָפוֹת לְדִרְאוֹן עוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בַּעַל הָרַחֲמִים, כֵּיוָן שֶׁדָּן אוֹתָם בָּעוֹלָם הַזֶּה וְקִבְּלוּ דִין, לֹא נִדּוֹנוּ בְּכָל הַדִּינִים.</p>\n<p>אָמַר רַבִּי חִיָּיא, כָּתוּב וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגוֹ'. מַהוּ בַּהֲפֹךְ אֶת הֶעָרִים אֲשֶׁר יָשַׁב בָּהֵן לוֹט? אֶלָּא בַּכֹּל עָשָׂה דִיּוּרוֹ לוֹט, שֶׁכָּתוּב וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדם. (וכתוב אשר ישב בהן לוט, אלא ודאי שבכלם עשה את דיורו) וְלֹא קִבְּלוּ אוֹתוֹ, חוּץ מִמֶּלֶךְ סְדם שֶׁקִּבֵּל אוֹתוֹ בִּסְדם מִשּׁוּם אַבְרָהָם.</p>\n<p>קְשָׁרִים רָמִים, שָׂרִים הַמְפַזְּרִים (נ\"א: המבררים, ונ\"א המנפצים), חֲכָמִים בַּשֵּׂכֶל, יִסְתַּכְּלוּ לָדַעַת, בְּשָׁעָה שֶׁהָרֹאשׁ הַלָּבָן תִּקֵּן כִּסֵּא עַל גַּבֵּי הָעַמּוּדִים עַל אֲבָנִים שֶׁל מַרְגָּלִיּוֹת טוֹבוֹת.</p>\n<p>בֵּין אוֹתָם הָאֲבָנִים יֵשׁ מַרְגָּלִית אַחַת בְּמַרְאֶה יָפֶה וּבְתֹאַר כִּסּוּי הַכְּלִי (של העשן) שֶׁלּוֹהֵט בְּשִׁבְעִים גְּוָנִים. אוֹתָם שִׁבְעִים גְּוָנִים לוֹהֲטִים לְכָל צַד.</p>\n<p>אֵלֶּה הַשִּׁבְעִים נִפְרָדִים מִתּוֹךְ שְׁלֹשָׁה גְוָנִים. אֵלֶּה רוּחוֹת בְּרוּחוֹת שֶׁנּוֹצְצוֹת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. כָּאן יֵשׁ רוּחַ חֲזָקָה שֶׁל צַד שְׂמֹאל שֶׁנֶּאֱחָז בַּשָּׁמַיִם. אוֹתָם שִׁבְעִים גְּוָנִים הַדִּין יוֹשֵׁב וְהַסְּפָרִים נִפְתָּחִים.</p>\n<p>מִכָּאן יוֹצְאִים חִצִּים וַחֲרָבוֹת וּרְמָחִים וְאֵשׁ שֶׁל הַמִּגְדָּל. וְנֶאֱחֶזֶת אֵשׁ חֲזָקָה שֶׁיּוֹצֵאת מֵהַשָּׁמַיִם בּוֹ. וּכְשֶׁנֶּאֱחֶזֶת הָאֵשׁ הָעֶלְיוֹנָה בְּאֵלּוּ שֶׁלְּמַטָּה, אֵין מִי שֶׁיָּכוֹל לִשְׁבֹּר אֶת הָרֹגֶז וְהַדִּין.</p>\n<p>עֵינַיִם לוֹהֲטוֹת כְּמוֹ שַׁלְהָבוֹת שֶׁל אֵשׁ יוֹרֵד בָּהֶם לָעוֹלָם. אוֹי לְמִי שֶׁפּוֹגֵשׁ אוֹתוֹ, חֲגוּר מָתְנַיִם (חרבות) הוּא, וְחֶרֶב שְׁנוּנָה בְּיָדוֹ. לֹא מְרַחֵם עַל טוֹב וְלֹא עַל רַע. שֶׁהֲרֵי (הפסק) הַפֶּתֶק, שֶׁהֵם שִׁבְעִים בִּרְשׁוּת שֶׁנֶּאֱחָז אוֹתוֹ צַד שֶׁל הַשָּׁמַיִם, יוֹרֵד בְּיַד שְׂמֹאל בְּכַמָּה דִינִים.</p>\n<p>מִתְהַפֵּךְ בְּכַמָּה גְוָנִים, הוֹפֵךְ בְּכָל יוֹם. הוּא נִקְרָא כְּרֻם זֻלֻּת שֶׁמְּתֻקָּן לִבְנֵי אָדָם. כָּל הַגְּוָנִים שֶׁל כְּלֵי הַזַּעַם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִרְאִים בּוֹ. וְהֵם יוֹשְׁבִים בְּרוּם הָעוֹלָם, וּבְנֵי אָדָם בְּסִכְלוּתָם לֹא מַשְׁגִּיחִים בָּהֶם.</p>\n<p>גָּפְרִית וָאֵשׁ - הִתּוּךְ שֶׁל מַיִם וְאֵשׁ שֶׁנִּתָּכִים מֵהַשָּׁמַיִם נֶאֶחְזוּ זֶה בָּזֶה וְיָרְדוּ עַל סְדם. אוֹי לָרְשָׁעִים שֶׁאֵינָם מַשְׁגִּיחִים עַל כְּבוֹד רִבּוֹנָם.</p>\n<p>א, עֲשָׂרָה שֵׁמוֹת חֲקוּקִים בִּרְצוֹן הַמֶּלֶךְ. ב: עֲשָׂרָה הֵם וְעוֹלִים לְחֶשְׁבּוֹן גָּדוֹל. ג: שִׁבְעִים גְּוָנִים לוֹהֲטִים לְכָל צַד. יוֹצְאִים מִתּוֹךְ שֵׁמוֹת שֶׁחֲקוּקִים סוֹד שֶׁל שִׁבְעִים שְׁמוֹת מַלְאָכִים שֶׁהֵם בְּסוֹד הַשָּׁמַיִם.</p>\n<p>וְהֵם, ' מִיכָאֵל, גַּבְרִיאֵל, רְפָאֵל, נוֹרִיאֵל. קָמַ\"ץ - \"קדומיאל \"מלכיאל \"צדקיאל. פַּתָּ\"ח - \"פדאל \"תומיאל \"חשדיאל. צֵרֵ\"י - \"צדקיאל \"רזיאל \"יופיאל. סֶגּוֹ\"ל - \"סטוטריה \"גזריאל \"ותריאל (נ\"א: ו\"רדיאל) \"למואל. חִרֵ\"ק - \"חזקיאל \"רהטיאל \"קדשיאל. שְׁבָ\"א - \"שמעאל \"ברכיאל (נ\"א: ש\"כניאל ונ\"א ב\"רקיאל) \"אהיאל.</p>\n<p>חֹלָ\"ם - \"חניאל \"להדיאל \"מחניאל (נ\"א: ח\"ניאל ל\"עדיאל מ\"לכיאל). \"עניאל ענאל אהניאל רחמיאל עזריאל (נ\"א ש\"בנאל ר\"ומיאל ק\"דומיאל שר\"ק, ח\"כמיאל ר\"מיאל ק\"רשיאל חר\"ק)</p>\n<p>סנניה ודרגזיה רסיסיאל דומיאל \"חוניאל \"זכריאל \"ואריאל \"ה\"ינאל ד\"נדאל ג\"דיאל ב\"דאל א\"נפיאל ועדי\"אל אדנ\"י עַל כֻּלָּם. ד (פירוש, כשע\"ב מלאכים מתחברים במלכות, אז נקרא מלכות הוא ובית דינו בלשון וה',)</p>\n<p>כְּשֶׁכֻּלָּם מִתְחַבְּרִים כְּאֶחָד בְּסוֹד אֶחָד בְּכֹחַ עֶלְיוֹן אָז נִקְרָא ויהוה, הַכֹּל בִּכְלַל אֶחָד. מֵאֵת ה' מִן הַשָּׁמָיִם - שֵׁם קָדוֹשׁ שֶׁנֶּחְקָק בְּשִׁבְעִים שֵׁמוֹת אֲחֵרִים, סוֹד שֶׁל שָׁמַיִם. וְאֵלֶּה הֵם שִׁבְעִים שֶׁשּׁוֹלְטִים עַל אֵלּוּ שִׁבְעִים דִּינִים, סוֹד שֶׁל יהו\"ה, וְשִׁבְעִים הַשֵּׁמוֹת הַלָּלוּ בִּקְדֻשָּׁה, יהו\"ה שָׁמַיִם. ה (פירוש, שם של ע\"ב גשרים היוצא מפסוק ויסע ויבא ויט, אלו הם נקראים שמים, ואותם ע\"ב מלאכים של מטה במלכו\"ת מקבלים מע\"ב של מעלה ונוטלין מהם,)</p>\n<p>אֵלּוּ נוֹטְלִים (נוסעים) מֵאֵלֶּה, וְיהו\"ה ו (פירוש, מלכות מתפארת) נוֹטֵל מֵאֵת יהוה זֶה מִזֶה. ז (פירוש, סוד של אותן ע\"ב שמות הוא שם יהוה, והוא הרוכב עליהן כנשמה לגוף,) וְאֵלּוּ תְּלוּיִים בְּאֵלּוּ, תַּחְתּוֹנִים בָּעֶלְיוֹנִים, וְהַכֹּל קֶשֶׁר אֶחָד. וּבָזֶה נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ. ח (פירוש, ע\"ב מלאכים של מטה מתחברים בע\"ב שמות של מעלה הנקראים שמים,) שָׁמַיִם שֶׁהֵם שִׁבְעִים סוֹד יהוה, זֶהוּ בְּסוֹד שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וְאֵלּוּ הֵם שֶׁיּוֹצְאִים מִן וַיִּסַּע וַיָּבא וַיֵּט.</p>\n<p>וה\"ו יל\"י סי\"ט על\"ם מה\"ש לל\"ה אכ\"א כה\"ת הז\"י אל\"ד לא\"ו הה\"ע. חֵלֶק רִאשׁוֹן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. יז\"ל מב\"ה הר\"י הק\"ם לא\"ו כל\"י לו\"ו פה\"ל נל\"ךָּ יי\"י מל\"ה חה\"ו. חֵלֶק שֵׁנִי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. נת\"ה הא\"א יר\"ת שא\"ה רי\"י או\"ם לכ\"ב וש\"ר יח\"ו לה\"ח כו\"ק מנ\"ד. חֵלֶק שְׁלִישִׁי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. אנ\"י חע\"ם רה\"ע יי\"ז הה\"ה מי\"ךָּ וו\"ל יל\"ה סא\"ל ער\"י עש\"ל מי\"ה. חֵלֶק רְבִיעִי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וה\"ו דנ\"י הח\"ש עמ\"ם ננ\"א ני\"ת מב\"ה פו\"י נמ\"מ יי\"ל הר\"ח מצ\"ר. חֵלֶק חֲמִישִׁי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. ומ\"ב יה\"ה ענ\"ו מח\"י דמ\"ב מנ\"ק אי\"ע חב\"ו רא\"ה יב\"מ הי\"י מו\"ם. חֵלֶק שִׁשִּׁי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>\n<p>וְאֵלּוּ הֵם שִׁבְעִים שֵׁמוֹת שֶׁשּׁוֹלְטִים עַל שִׁבְעִים דְּרָגוֹת תַּחְתּוֹנוֹת סוֹד ויהו\"ה. אֵלּוּ שִׁבְעִים שֵׁמוֹת יהו\"ה, סוֹד שֶׁנִּקְרָא שָׁמַיִם. שִׁבְעָה רְקִיעִים הֵם שֶׁעוֹלִים לְשִׁבְעִים שֵׁמוֹת שֵׁם קָדוֹשׁ. וְזֶהוּ וַיהוה הִמְטִיר. מֵאֵת יהוה מִן הַשָּׁמָיִם.</p>\n<p>סֵתֶר הַסְּתָרִים לַחֲכָמִים נִמְסָר. שֵׁם זֶה שֶׁנִּקְרָא שָׁמַיִם, מִמֶּנּוּ נִבְרָא סֵתֶר שֶׁנִּקְרָא אָדָם. חֶשְׁבּוֹן אֵיבְרֵי הַגּוּף שֶׁהֵם חֶשְׁבּוֹן מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים.</p>\n<p>חֶשְׁבּוֹן אוֹתִיּוֹתָיו מָאתַיִם וְשֵׁשׁ עֶשְׂרֵה. שֵׁם זֶה שֶׁהוּא סוֹד וְסֵתֶר כְּלָל שֶׁל כָּל הַתּוֹרָה בְּכ\"ב אוֹתִיּוֹת וְעֶשֶׂר אֲמִירוֹת, מִשּׁוּם שֶׁהֲרֵי שֵׁם זֶה מָאתַיִם וְשֵׁשׁ עֶשְׂרֵה אוֹתִיּוֹת וּשְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים שֶׁכְּלוּלִים בָּהּ. הֲרֵי מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבְרֵי הַגּוּף.</p>\n<p>סוֹד שֶׁנִּקְרָא אָדָם הַשּׁוֹלֵט עַל הַכִּסֵּא, סוֹד שֶׁל שִׁבְעִים שֶׁלְּמַטָּה, וְסֵתֶר זֶה שֶׁכָּתוּב (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה, וְזֶה הוּא סֵתֶר שֶׁכָּתוּב וַה' הִמְטִיר עַל סְדם וְגוֹ' מֵאֵת ה' מִן הַשָּׁמָיִם. וְהַכֹּל אֶחָד וְדָבָר אֶחָד, וְסֵתֶר אֶחָד לְחַכְמֵי הַלֵּב נִמְסָר. אַשְׁרֵי (הוא) חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>סְדֹם נֶחְתַּם גְּזַר דִּין שֶׁלָּהֶם עַל שֶׁמָּנְעוּ צְדָקָה מֵהֶם, כְּמוֹ שֶׁנֶּאֱמַר (שם יו) וְיַד עָנִי וְאֶבְיוֹן לֹא הֶחֱזִיקָה, וְלָכֵן הַדִּין לֹא הָיָה אֶלָּא מִן הַשָּׁמַיִם. צְדָקָה וְשָׁמַיִם הַכֹּל אֶחָד, וְכָתוּב (תהלים קח) כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךְ, מִשּׁוּם שֶׁצְּדָקָה תְלוּיָה בִּשְׁמוֹ (בשמים), דִּין הוּא מִשָּׁמַיִם, שֶׁכָּתוּב מֵאֵת ה' מִן הַשָּׁמָיִם.</p>\n<p>הַדִּין שֶׁל יִשְׂרָאֵל מִמָּקוֹם זֶה, שֶׁכָּתוּב (איכה ד) וַיִּגְדַּל עֲון בַּת עַמִּי מֵחַטַּאת סְדם. וִירוּשָׁלַיִם נִקְרֵאת אָחוֹת לִסְדם, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל יט) הנה זה היה עון סדם אחותך, ודינם היה מן השמים דין אחד כִּסְדם עַל שֶׁמָּנְעוּ צְדָקָה מֵהֶם, פְּרָט לָזֶה שֶׁזֶּה הִתְהַפֵּךְ וְזֶה נֶחֱרַב. לָזוֹ יֵשׁ תְּקוּמָה, וְלָזוֹ אֵין תְּקוּמָה. ע\"כ סתרי תורה.</p>"],[9522011234,"<p>וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו, הָיָה צָרִיךְ לִכְתֹּב מֵאַחֲרֶיהָ? אֶלָּא מֵאַחַר הַשְּׁכִינָה. רַבִּי יוֹסֵי אָמַר, מֵאֲחוֹרָיו שֶׁל לוֹט, שֶׁהַמַּשְׁחִית הָיָה הוֹלֵךְ אַחֲרָיו. וְכִי אַחֲרָיו הָלַךְ, הֲרֵי הוּא שָׁלַח אוֹתוֹ? אֶלָּא כָּל מָקוֹם שֶׁהָלַךְ לוֹט, הִתְעַכֵּב הַמַּשְׁחִית לְהַשְׁחִית, וְכָל מָקוֹם שֶׁהָלַךְ כְּבָר וְהִשְׁאִיר לַאֲחוֹרָיו, הָיָה הוֹפֵךְ אוֹתוֹ הַמַּשְׁחִית.</p>\n<p>וְלָכֵן אָמַר לוֹ אַל תַּבֵּט אַחֲרֶיךְ, שֶׁהֲרֵי אֲנִי מְחַבֵּל אַחֲרֶיךְ. וְעַל זֶה כָּתוּב וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו, וְרָאֲתָה אֶת הַמַּשְׁחִית, אָז וַתְּהִי נְצִיב מֶלַח. שֶׁהֲרֵי כָּל זְמַן שֶׁהַמַּשְׁחִית אֵינוֹ רוֹאֶה אֶת פְּנֵי הָאִישׁ (מראה פניו לאיש), הוּא אֵינוֹ מַשְׁחִית אוֹתוֹ. כֵּיוָן שֶׁאִשְׁתּוֹ הֶחֱזִירָה פָנֶיהָ לְהִסְתַּכֵּל אַחֲרָיו, מִיָּד וַתְּהִי נְצִיב מֶלַח.</p>"],[9522011235,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ עוֹמְדִים יוֹם אֶחָד וְעוֹסְקִים בַּפָּסוּק הַזֶּה. אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (דברים ח) אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם לֹא תֶחְסַר כֹּל בָּהּ. לְשֵׁם מָה פַּעֲמַיִם בָּהּ בָּהּ? אֶלָּא הֲרֵי נֶאֱמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חִלֵּק אֶת כָּל הָעַמִּים וְהָאֲרָצוֹת לִשְׁלוּחִים מְמֻנִּים, וּבְאֶרֶץ יִשְׂרָאֵל לֹא שׁוֹלֵט מַלְאָךְ וְלֹא מְמֻנֶּה אַחֵר, אֶלָּא הוּא לְבַדּוֹ, לָכֵן הִכְנִיס אֶת הָעָם שֶׁלֹּא שׁוֹלֵט בָּהֶם אַחֵר לְאֶרֶץ שֶׁלֹּא שׁוֹלֵט בָּהּ אַחֵר.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן מָזוֹן שָׁם בַּתְּחִלָּה, וְאַחַר כָּךְ לְכָל הָעוֹלָם. כָּל שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת בְּעֹנִי, וְאֶרֶץ יִשְׂרָאֵל לֹא כָּךְ, אֶלָּא אֶרֶץ יִשְׂרָאֵל נִזּוֹנֵית בַּתְּחִלָּה וְאַחַר כָּךְ כָּל הָעוֹלָם.</p>\n<p>וְלָכֵן אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם, אֶלָּא בְּעֹשֶׁר, בַּסִּפּוּק שֶׁל הַכֹּל תֹּאכַל בָּהּ וְלֹא בְּמָקוֹם אַחֵר. בָּהּ בִּקְדֻשַּׁת הָאָרֶץ, בָּהּ שׁוֹרָה הָאֱמוּנָה הָעֶלְיוֹנָה, בָּהּ שׁוֹרָה הַבְּרָכָה שֶׁלְּמַעְלָה, וְלֹא בְּמָקוֹם אַחֵר.</p>\n<p>בֹּא רְאֵה, כָּתוּב כְּגַן ה' כְּאֶרֶץ מִצְרַיִם. עַד כָּאן לֹא נוֹדַע גַּן ה' אִם הוּא אֶרֶץ מִצְרַיִם וְאִם הוּא אֶרֶץ סְדם וְאִם הוּא גַּן ה' שֶׁנִּקְרָא גַן עֵדֶן. אֶלָּא כְּגַן ה' שֶׁיֵּשׁ בּוֹ סִפּוּק וְעִדּוּן שֶׁל הַכֹּל, כָּךְ גַּם הָיְתָה סְדם וְכָךְ גַּם מִצְרַיִם. מַה גַּן ה' לֹא צָרִיךְ אָדָם לְהַשְׁקוֹתוֹ, אַף מִצְרַיִם לֹא צָרִיךְ אַחֵר לְהַשְׁקוֹתָהּ, מִשּׁוּם שֶׁהַנִּילוּס עוֹלֶה וּמַשְׁקֶה אֶת כָּל אֶרֶץ מִצְרַיִם.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, (זכריה יד) וְהָיָה אֲשֶׁר לֹא יַעֲלֶה מֵאֵת מִשְׁפְּחוֹת הָאָרֶץ אֶל יְרוּשָׁלם וְגוֹ'. זֶהוּ עֹנֶשׁ שֶׁלָּהֶם שֶׁנִּמְנָע מֵהֶם מָטָר. מַה כָּתוּב וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה וְלֹא בָאָה וְגוֹ'? רְאֵה שֶׁלֹּא כָתוּב וְלֹא עֲלֵיהֶם יִהְיֶה הַגָּשֶׁם, כִּי לֹא יוֹרֵד מָטָר בְּמִצְרַיִם וְלֹא צְרִיכִים אוֹתוֹ. אֶלָּא עָנְשָׁם מַהוּ שֶׁכָּתוּב? (שם) וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף ה' אֶת כָּל הַגּוֹיִם וְגוֹ'. מִשּׁוּם שֶׁמִּצְרַיִם לֹא צְרִיכִים מָטָר. אַף סְדם מַה כָּתוּב בָּהּ? כִּי כֻלָּהּ מַשְׁקֶה. כָּל עִדּוּנֵי הָעוֹלָם הָיוּ בָּהּ, וְעַל זֶה לֹא רָצוּ שֶׁבְּנֵי אָדָם אֲחֵרִים יִתְעַדְּנוּ בָּהּ.</p>\n<p>רַבִּי חִיָּיא אָמַר, הֵם הָיוּ רְשָׁעִים מֵעַצְמָם וּמָמוֹנָם, שֶׁכָּל בֶּן אָדָם שֶׁהוּא צַר עַיִן לְעָנִי, רָאוּי הוּא שֶׁלֹּא יַעֲמֹד בָּעוֹלָם, וְלֹא עוֹד, אֶלָּא שֶׁאֵין לוֹ חַיִּים לָעוֹלָם הַבָּא. וְכָל מִי שֶׁהוּא וַתְּרָן לְעָנִי, רָאוּי הוּא שֶׁיִּתְקַיֵּם בָּעוֹלָם וְיִתְקַיֵּם הָעוֹלָם בִּשְׁבִילוֹ, וְיֵשׁ לוֹ חַיִּים וְאֹרֶךְ שֶׁל חַיִּים לָעוֹלָם הַבָּא.</p>"],[9522011236,"<p>וַיַּעַל לוֹט מִצּוֹעַר וַיֵּשֶׁב בָּהָר הוּא וּשְׁתֵּי בְנֹתָיו עִמּוֹ וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאָה שֶׁהָיָה קָרוֹב לִסְדם וְעָלָה מִשָּׁם.</p>\n<p>רַבִּי יִצְחָק פָּתַח, (איוב לז) וְהוּא מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלֹתָו לְפָעֳלָם וְגוֹ'. הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִים בָּעוֹלָם וּמֵבִיא גַּחֲלֵי אֵשׁ צַחִים לַעֲשׂוֹת מַעֲשָׂיו, וְאַחַר כָּךְ הוֹפֵךְ אוֹתָם וְעוֹשֶׂה אוֹתָם בְּגָוֶן אַחֵר.</p>\n<p>וּבַמֶּה,? בְּתַחְבּוּלֹתָו. עוֹשֶׂה תַחְבּוּלוֹת וּמְסַבֵּב סִבּוּבִים כְּדֵי לַהֲפֹךְ אוֹתָם, וְלֹא כְּמוֹ אוֹתָם הָרִאשׁוֹנִים. לְפָעֳלָם - מִשּׁוּם פָּעֳלָם שֶׁל בְּנֵי אֱנוֹשׁ. כְּמוֹ שֶׁהֵם עוֹשִׂים מַעֲשִׂים, כָּךְ הוּא מְהַפֵּךְ אוֹתָם. כֹּל אֲשֶׁר יְצַוֵּם עַל פְּנֵי תֵבֵל אָרְצָה - מִשּׁוּם מַעֲשֵׂי בְּנֵי אָדָם הוּא מְהַפֵּךְ אוֹתָם מְסִבּוֹת בְּכָל מַה שֶּׁהוּא מְצַוֶּה אוֹתָם עַל פְּנֵי תֵבֵל וְגוֹ'.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, וְהוּא מְסִבּוֹת מִתְהַפֵּךְ - הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִים וּמֵבִיא מַעֲשִׂים בָּעוֹלָם לְהִתְקַיֵּם, וְאַחַר שֶׁחוֹשְׁבִים בְּנֵי אָדָם שֶׁיִּתְקַיְּמוּ אוֹתָם מַעֲשִׂים, הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹפֵךְ אוֹתָם אֶת אוֹתָם מַעֲשִׂים מִכְּמוֹ שֶׁהָיוּ בַּהַתְחָלָה.</p>\n<p>בְּתַחְבּוּלֹתָו, בְּתַחְבּוּלָתוֹ כָּתוּב, כְּמוֹ הָאֻמָּן הַזֶּה שֶׁעוֹשֶׂה כְּלִי חֶרֶס, בְּעוֹד שֶׁאוֹתוֹ הַגַּלְגַּל מִסְתּוֹבֵב לְפָנָיו, חוֹשֵׁב לַעֲשׂוֹת כְּגוֹן זֶה - עוֹשֶׂה, חוֹשֵׁב לַעֲשׂוֹת כְּגוֹן אַחֵר - עוֹשֶׂה. מְהַפֵּךְ כְּלי זֶה לִכְלִי אַחֵר מִשּׁוּם שֶׁאוֹתוֹ הַגַּלְגַּל סוֹבֵב לְפָנָיו. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְהַפֵּךְ אֶת מַעֲשָׂיו שֶׁהוּא עוֹשֶׂה.</p>\n<p>בְּתַחְבּוּלֹתָו חָסֵר יוֹ\"ד, וּמַהוּ? זֶה בֵּית דִּין לְמַטָּה שֶׁהוּא גַלְגַּל הַסּוֹבֵב לְפָנָיו, וְעַל זֶה הוּא מְהַפֵּךְ כֵּלִים מִכְּלִי זֶה לִכְלִי אַחֵר,</p>\n<p>וְכָל זֶה כְּפִי פָעֳלָם שֶׁל בְּנֵי אָדָם. אִם בְּנֵי אָדָם מְטִיבִים מַעֲשֵׂיהֶם - אוֹתוֹ הַגַּלְגַּל הַסּוֹבֵב מְסוֹבֵב אוֹתָם יָמִינָה, וְאָז נַעֲשִׂים מַעֲשִׂים בָּעוֹלָם לְהֵיטִיב לָהֶם כָּרָאוּי, וְהַגַּלְגַּל סוֹבֵב תָּמִיד וְלֹא שׁוֹקֵט בְּאוֹתוֹ צַד הַיָּמִין, וְהָעוֹלָם מִתְגַּלְגֵּל בּוֹ.</p>\n<p>בָּאוּ בְּנֵי אָדָם לְהָרַע - תַּחְבּוּלָתוֹ שֶׁסּוֹבֶבֶת תָּמִיד וְהָיְתָה עוֹמֶדֶת בַּסִּבּוּב שֶׁל הַיָּמִין, הַקָּדוֹשׁ בָּרוּךְ הוּא מְסוֹבֵב אוֹתָהּ לְצַד שְׂמֹאל וּמְהַפֵּךְ מְסִבּוֹת וְכֵלִים שֶׁהָיוּ צַד שְׂמֹאל.</p>\n<p>וְאָז הַגַּלְגַּל סוֹבֵב וְנַעֲשִׂים מַעֲשִׂים בָּעוֹלָם לְהָרַע לִבְנֵי אָדָם. וְהַגַּלְגַּל סוֹבֵב לְאוֹתוֹ צַד עַד שֶׁבְּנֵי אָדָם שָׁבִים לְהֵיטִיב מַעֲשֵׂיהֶם, וְהַגַּלְגַּל עוֹמֵד בְּמַעֲשֵׂי בְּנֵי הָאָדָם. וְעַל כָּךְ בְּתַחְבּוּלֹתָו לְפָעֳלָם, וְלֹא עוֹמֵד תָּמִיד.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹרֵם סִבּוּבִים וּמַעֲשִׂים בָּעוֹלָם כְּדֵי לַעֲשׂוֹת הַכֹּל כָּרָאוּי, וְהַכֹּל יוֹצֵא מֵהָעִקָּר וְהַשֹּׁרֶשׁ שֶׁלְּמַעְלָה. קֵרַב אֶת אַבְרָהָם אֵלָיו - יָצָא מִמֶּנּוּ יִשְׁמָעֵאל, כְּשֶׁלֹּא הָיָה אַבְרָהָם מָהוּל כְּשֶׁיָּצָא מִמֶּנּוּ, מִשּׁוּם שֶׁהוּא לְמַטָּה וְלֹא נִשְׁלַם בְּאוֹת בְּרִית קֹדֶשׁ.</p>\n<p>אַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא סִבֵּב סִבּוּבִים בְּתַחְבּוּלוֹתָיו וְנִמּוֹל אַבְרָהָם, וְנִכְנַס בִּבְרִית וְנִשְׁלַם בִּשְׁמוֹ וְנִקְרָא אַבְרָהָם, וְה' עֶלְיוֹנָה עִטְּרָה אוֹתוֹ בְּסוֹד שֶׁל מַיִם מֵרוּחַ.</p>\n<p>כֵּיוָן שֶׁהַסּוֹד (של ה\"א) נִשְׁלַם וְהוּא נִמּוֹל, יָצָא מִמֶּנּוּ יִצְחָק וְהָיָה זֶרַע קֹדֶשׁ, וְנִקְשַׁר לְמַעְלָה בְּסוֹד שֶׁל אֵשׁ מִמַּיִם, וְעַל זֶה כָּתוּב (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת, וְלֹא נִקְשַׁר בְּאוֹתוֹ הַצַּד הָאַחֵר.</p>\n<p>בֹּא רְאֵה, מִלּוֹט יָצְאוּ מִמֶּנּוּ וּמִבְּנוֹתָיו שְׁתֵּי אֻמּוֹת נִפְרָדוֹת וְנִקְשְׁרוּ בְּאוֹתוֹ צַד שֶׁרָאוּי לָהֶם, וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא מְסוֹבֵב סִבּוּבִים וּמְגַלְגֵּל גִּלְגּוּלִים בָּעוֹלָם שֶׁהַכֹּל יֵעָשֶׂה כָּרָאוּי וְיִתְקַשֵּׁר הַכֹּל בִּמְקוֹמוֹ.</p>\n<p>בֹּא רְאֵה, נָאֶה הָיָה לְלוֹט שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹצִיא מִמֶּנּוּ (ומבנותיו) וּמֵאִשְׁתּוֹ שְׁתֵּי הָאֻמּוֹת הַלָּלוּ, אֶלָּא בִּשְׁבִיל לְהִתְקַשֵּׁר בִּמְקוֹמָם הָרָאוּי לָהֶם, וְנַעֲשׂוּ מִתּוֹךְ יַיִן, וְאוֹתוֹ הַיַּיִן הִזְדַּמֵּן לָהֶם בַּמְּעָרָה בְּאוֹתוֹ לַיְלָה, וְזֶהוּ הַסּוֹד שֶׁנַּעֲשׂוּ, כְּמוֹ שֶׁנֶּאֱמַר וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר, וַהֲרֵי נִתְבָּאֵר וּבֵאֲרוּהָ.</p>\n<p>בֹּא רְאֵה, מוֹאָב וְעַמּוֹן הֵן קָרְאוּ לָהֶם שֵׁמוֹת. מוֹאָב - מֵאָב. רַבִּי יוֹסֵי אָמַר, הַבְּכִירָה אָמְרָה בְּחֻצְפָּה, אָמְרָה מוֹאָב, מֵאַבָּא הוּא. וְהַצְּעִירָה גַּם הִיא יָלְדָה בֵּן וַתִּקְרָא שְׁמוֹ בֶּן עַמִּי. בִּצְנִיעוּת אָמְרָה בֶּן עַמִּי. בֶּן עַמִּי, וְלֹא אָמְרָה מִמִּי הוּא.</p>\n<p>בֹּא רְאֵה, בַּהַתְחָלָה כָּתוּב וְלֹא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ, בְּוָא\"ו, וְנָקוּד עַל וָא\"ו, מִשּׁוּם שֶׁסִּיּוּעַ מִלְמַעְלָה הָיָה נִמְצָא בְּאוֹתוֹ מַעֲשֶׂה שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לָצֵאת מִמֶּנּוּ, וְלָכֵן נִשְׁלַם כָּאן בְּוָא\"ו. וּבָאַחֶרֶת כָּתוּב וּבְקֻמָהּ, חָס וָי\"ו, מִשּׁוּם שֶׁלֹּא יָצָא מִמֶּנָּה חֵלֶק לַקָּבָּ\"ה כְּמוֹ הָאַחֶרֶת הַזּוֹ, וְעַל זֶה כָּתוּב בָּאַחֶרֶת הַזּוֹ הַגְּדוֹלָה וּבְקוּמָהּ בְּוָא\"ו מָלֵא וְנִקּוּד עָלָיו.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, לֹא יָדַע שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲמִיד מִמֶּנָּה דָּוִד הַמֶּלֶךְ וּשְׁלֹמֹה וְכָל שְׁאָר הַמְּלָכִים וּמֶלֶךְ הַמָּשִׁיחַ. עוֹד וּבְקוּמָהּ, כְּמוֹ שֶׁכָּתוּב בְּרוּת (רות ג) וַתָּקָם בְּטֶרֶם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגוֹ'. וּבְאוֹתוֹ הַיּוֹם הָיְתָה לָהּ קִימָה וַדַּאי, הִתְחַבֵּר עִמָּהּ בֹּעַז לְהָקִים שֵׁם הַמֵּת עַל נַחֲלָתוֹ, וְהוּקְמוּ מִמֶּנָּה כָּל הַמְּלָכִים הַלָּלוּ וְכָל הָעִלּוּי שֶׁל יִשְׂרָאֵל. וְלֹא יָדַע בְּשִׁכְבָהּ, שֶׁכָּתוּב וַתִּשְׁכַּב מַרְגְּלוֹתָו עַד הַבֹּקֶר. וּבְקוּמָהּ, שֶׁכָּתוּב בְּטֶרֶם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגוֹ'. מִשּׁוּם כָּךְ וּבְקוּמָהּ נָקוּד וָא\"ו.</p>\n<p>בֹּא רְאֵה אֶת עַנְוְתָנוּתוֹ שֶׁל אַבְרָהָם, שֶׁהֲרֵי אֲפִלּוּ בַּתְּחִלָּה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת דִּין בִּסְדם, לֹא בִקֵּשׁ מִמֶּנּוּ רַחֲמִים עַל לוֹט. (שהרי) אַחַר שֶׁכָּתוּב וַיַּרְא וְהִנֵּה עָלָה קִיטֹר הָאָרֶץ כְּקִיטֹר הַכִּבְשָׁן, לֹא בִקֵּשׁ עַל לוֹט וְלֹא אָמַר עָלָיו לַקָּבָּ\"ה כְּלוּם. אַף כָּךְ לֹא אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר, כְּדֵי שֶׁלֹּא יַחְשֹׁב אַבְרָהָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גָּרַע מִזְּכוּתוֹ כְּלוּם.</p>\n<p>וְאִם תֹּאמַר שֶׁאַבְרָהָם לֹא הֶחְשִׁיב בְּלִבּוֹ אֶת לוֹט לִכְלוּם - הֲרֵי מָסַר נַפְשׁוֹ לָלֶכֶת לְהִלָּחֵם בַּקְּרָב עִם חֲמִשָּׁה מְלָכִים חֲזָקִים, כְּמוֹ שֶׁנֶּאֱמַר וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו, וְכָתוּב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה, וְכָתוּב וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ וְגַם אֶת לוֹט אָחִיו וּרְכֻשׁוֹ הֵשִׁיב וְגוֹ'. אֲבָל בָּאַהֲבָה שֶׁאָהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְרָאָה שֶׁמַּעֲשָׂיו שֶׁל לוֹט אֵינָם כְּשֵׁרִים כָּרָאוּי, לֹא רָצָה אַבְרָהָם שֶׁבִּגְלָלוֹ יַעֲזֹב הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלוּם מִשֶּׁלּוֹ, וְלָכֵן לֹא בִקֵּשׁ עָלָיו רַחֲמִים לֹא בַּתְּחִלָּה וְלֹא בַּסּוֹף.</p>\n<p>וַיַּעַל לוֹט מִצּוֹעַר וְגוֹ'. אָמַר רַבִּי אַבָּהוּ, בּא רְאֵה מַה כָּתוּב בַּיֵּצֶר הָרָע, תֵּדַע לְךְ שֶׁאֵינוֹ מִתְבַּטֵּל לְעוֹלָם מִבְּנֵי אָדָם עַד אוֹתוֹ זְמַן, שֶׁכָּתוּב (יחזקאל לו) וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן וְגוֹ'. שֶׁאַף עַל פִּי שֶׁרוֹאֶה בְּנֵי אָדָם נִדּוֹנִין בַּגֵּיהִנֹּם, הוּא בָּא וְחוֹזֵר לוֹ אֵצֶל בְּנֵי אָדָם. זֶהוּ שֶׁכָּתוּב וַיַּעַל לוֹט מִצּוֹעַר, מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם, מִשָּׁם עוֹלֶה לְפַתּוֹת בְּנֵי אָדָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, שָׁלֹשׁ הַנְהָגוֹת יֵשׁ בָּאָדָם: הַנְהָגַת הַשֵּׂכֶל וְהַחָכְמָה, וְזוֹ הִיא כֹּחַ הַנְּשָׁמָה הַקְּדוֹשָׁה. וְהַנְהָגַת הַתַּאֲוָה, שֶׁהִיא מִתְאַוָּה בְּכָל תַּאֲווֹת רָעוֹת, וְזֶהוּ כֹּחַ הַתַּאֲוָה. וְהַהַנְהָגָה הַמַּנְהֶגֶת לִבְנֵי אָדָם וּמְחַזֶּקֶת הַגּוּף, וְהִיא נִקְרֵאת נֶפֶשׁ הַגּוּף. אָמַר רַבִּי דִּימִי, זֶהוּ כֹּחַ הַמַּחֲזִיק.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בּא רְאֵה, לְעוֹלָם אֵין יֵצֶר הָרָע שׁוֹלֵט אֶלָּא בְּאֵלּוּ שְׁנֵי כֹּחוֹת אֵלּוּ שֶׁאָמַרְנוּ, נֶפֶשׁ הַמִּתְאַוָּה הִיא הָרוֹדֶפֶת אַחַר יֵצֶר הָרָע לְעוֹלָם, מַשְׁמָע שֶׁכָּתוּב וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן. נֶפֶשׁ הַמִּתְאַוָּה הִיא מְעוֹרֶרֶת אֶת הָאַחֶרֶת וּמְפַתָּה אוֹתָהּ עִם הַגּוּף לְהִדָּבֵק בַּיֵּצֶר הָרָע, וְהִיא אוֹמֶרֶת לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן וְנִשְׁכְּבָה עִמּוֹ. מַה יֵּשׁ לָנוּ בָּעוֹלָם הַבָּא, נֵלֵךְ וְנִרְדֹּף אַחַר יֵצֶר הָרָע וְאַחַר תְּשׁוּקַת חֶמְדַּת הָעוֹלָם הַזֶּה. וּמָה עוֹשׂוֹת? שְׁתֵּיהֶן מַסְכִּימוֹת לְהִדָּבֵק בּוֹ. מַה כָּתוּב? וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. מִתְפַּטְּמוֹת לְהִתְעוֹרֵר לַיֵּצֶר הָרָע בַּאֲכִילָה וּבִשְׁתִיָּה.</p>\n<p>וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. כְּשֶׁאָדָם שׁוֹכֵב עַל מִטָּתוֹ בַּלַּיְלָה, נֶפֶשׁ הַמִּתְאַוָּה הִיא הַמְּעוֹרֶרֶת לַיֵּצֶר הָרָע וּמְהַרְהֶרֶת בּוֹ, וְהוּא דָּבֵק בְּכָל הִרְהוּר רָע עַד שֶׁמִּתְעַבֶּרֶת מְעַט (ממנו) (ד\"א על) (נ\"א עד) שֶׁמֵּבִיא בְּלֵב הָאָדָם אוֹתָהּ הַמַּחֲשָׁבָה הָרָעָה וּדְבֵקָה בּוֹ, וַעֲדַיִן יֵשׁ בְּלִבּוֹ וְלֹא נִגְמָר לַעֲשׂוֹתָהּ עַד שֶׁ את הַתַּאֲוָה מְעוֹרֶרֶת לְכֹחַ הַגּוּף כְּמִתְּחִלָּה לְהִדָּבֵק בַּיֵּצֶר הָרָע, וְאָז הוּא תַּשְׁלוּם הָרָעָה. זֶהוּ שֶׁכָּתוּב וַתַּהֲרֶיןָ שְׁתֵּי בְּנוֹת לוֹט מֵאֲבִיהֶן.</p>\n<p>אָמַר רַבִּי יִצְחָק, מֵעוֹלָם אֵין יֵצֶר הָרָע מִתְפַּתֶּה אֶלָּא בַּאֲכִילָה וּשְׁתִיָּה, וּמִתּוֹךְ שִׂמְחַת הַיַּיִן אָז שׁוֹלֵט בָּאָדָם. בַּצַּדִּיק מַה כָּתוּב בּוֹ? (משלי יג) צַדִּיק אֹכֵל לְשֹׁבַע נַפְשׁוֹ, וְאֵינוֹ מִשְׁתַּכֵּר לְעוֹלָם. שֶׁאָמַר רַבִּי יְהוּדָה, אוֹתוֹ תַּלְמִיד חָכָם שֶׁשּׁוֹתֶה, קוֹרְאִים עָלָיו (שם יא) נֶזֶם זָהָב בְּאַף חֲזִיר. וְלֹא עוֹד, אֶלָּא שֶׁמְּחַלֵּל שֵׁם שָׁמַיִם. מִנְהַג הָרְשָׁעִים מַהוּ? (ישעיה כב) הִנֵּה שָׂשׂוֹן וְשִׂמְחָה. הַיַּיִן אָז שׁוֹלֵט בָּאָדָם, הָרוֹג בָּקָר וְשָׁחוֹט צֹאן וְגוֹ'. עֲלֵיהֶם אָמַר הַכָּתוּב (שם ה) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדּפוּ וְגוֹ'. כְּדֵי לְעוֹרֵר לַיֵּצֶר הָרָע, שֶׁאֵין יֵצֶר הָרָע מִתְעוֹרֵר אֶלָּא מִתּוֹךְ הַיַּיִן. זֶהוּ שֶׁכָּתוּב וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן.</p>\n<p>אָמַר רַבִּי אַבָּהוּ, מַה כָּתוּב? וְלֹא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ. כְּלוֹמַר, יֵצֶר הָרָע אֵינוֹ מַשְׁגִּיחַ בָּהּ בְּשִׁכְבָהּ בָּעוֹלָם הַזֶּה וּבְקוּמָהּ לָעוֹלָם הַבָּא, אֶלָּא מִתְעוֹרֵר עִם כֹּחַ הַגּוּף לַעֲבֹד תַּאֲוָתוֹ בָּעוֹלָם הַזֶּה. שֶׁאָמַר רַבִּי אַבָּהוּ, בְּשָׁעָה שֶׁנִּכְנסִים הָרְשָׁעִים בַּגֵּיהִנֹּם, מַכְנִיסִים לַיֵּצֶר הָרָע לִרְאוֹת בָּהֶן, זֶהוּ שֶׁכָּתוּב וְלוֹט בָּא צֹעֲרָה, לְצַעֲרָהּ שֶׁל גֵּיהִנֹּם. וְיָצָא לוֹ מִשָּׁם לְנַסּוֹת אֶת הַבְּרִיּוֹת, כְּמוֹ שֶׁאָמַרְנוּ. זֶהוּ שֶׁכָּתוּב וַיַּעַל לוֹט מִצּוֹעַר - מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם.</p>\n<p>וַיִּשֱׁב בָּהָר - אָמַר רַבִּי יִצְחָק, מַשְׁמָע שֶׁכָּתוּב בָּהָר, מְלַמֵּד שֶׁהוּא שָׂם מוֹשָׁבוֹ בִּמְקוֹם הַר. גּוּף שֶׁהוּא חָרֵב כְּמוֹ הַר שֶׁאֵין בּוֹ טוֹבָה. וּשְׁתֵּי בְנֹתָיו עִמּוֹ - אֵלּוּ שְׁתֵּי הַכֹּחוֹת שֶׁאָמַרְנוּ. כִּי יָרֵא לָשֶׁבֶת בְּצוֹעַר - יִרְאָה וַחֲרָדָה נוֹפֶלֶת עָלָיו בְּשָׁעָה שֶׁרוֹאֶה צַעַר גֵּיהִנֹּם שֶׁמְּצַעֲרִין לָרְשָׁעִים וְחוֹשֵׁב שֶׁשָּׁם יִדּוֹן. כֵּיוָן שֶׁרוֹאֶה שֶׁאֵינוֹ נִדּוֹן שָׁם, יוֹצֵא וְהוֹלֵךְ לְפַתּוֹת בְּנֵי אָדָם אַחֲרָיו.</p>\n<p>רַב הוּנָא כְּשֶׁהָיָה דוֹרֵשׁ לְהַזְהִיר אֶת בְּנֵי הָאָדָם, הָיָה אוֹמֵר לָהֶם: בָּנַי, הִשָּׁמְרוּ מִשָּׁלִיחַ שֶׁל גֵּיהִנֹּם, וּמִיהוּ? זֶה יֵצֶר הָרָע, שֶׁהוּא שָׁלִיחַ שֶׁל גֵּיהִנֹּם.</p>\n<p>רַבִּי אַבָּא אָמַר, מַה זֶּה שֶׁכָּתוּב (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב? אֵלּוּ שְׁתֵּי בְּנוֹת לוֹט שֶׁאָמַרְנוּ, שֶׁהִיא נֶפֶשׁ הַמִּתְאַוָּה, וְנֶפֶשׁ הַמִּשְׁתַּתֶּפֶת בַּגּוּף הָרוֹדֶפֶת אַחַר יֵצֶר הָרָע לְעוֹלָם. אָמַר רַבִּי יְהוֹשֻׁעַ, כָּתוּב כָּאן בְּלוֹט כִּי יָרֵא לָשֶׁבֶת בְּצוֹעַר, וְכָתוּב שָׁם לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. יָרֵ\"א בְּגִימַטְרִיָּא הוּא עֲלוּקָ\"ה. אָמַר רַבִּי יִצְחָק, אִם יָרֵא הוּא, אָז לָמָּה הוּא בָּא לְהַטְעוֹת אֶת הַבְּרִיּוֹת? אֶלָּא כָּךְ דֶּרֶךְ כָּל עוֹשֵׂה עַוְלָה - כְּשֶׁרוֹאֶה הָרָע, מִתְיָרֵא לְפִי שָׁעָה, וּמִיָּד חוֹזֵר לְרִשְׁעָתוֹ וְאֵינוֹ חוֹשֵׁשׁ לִכְלוּם. כָּךְ יֵצֶר הָרָע, בְּשָׁעָה שֶׁרוֹאֶה דִין בָּרְשָׁעִים, יָרֵא. כֵּיוָן שֶׁיּוֹצֵא לַחוּץ (לעשות), אֵינוֹ חוֹשֵׁשׁ כְּלוּם.</p>\n<p>רַבִּי אַבָּא אָמַר, מַה זֶּה שֶׁאָמְרוּ וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן? מַה זֶּה אָבִינוּ זָקֵן? זֶהוּ יֵצֶר הָרָע שֶׁנִּקְרָא זָקֵן, שֶׁנֶּאֱמַר (קהלת ד) מֶלֶךְ זָקֵן וּכְסִיל. שֶׁהוּא זָקֵן, שֶׁנּוֹלַד עִם הָאָדָם. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יוֹסֵי, אוֹתָהּ נֶפֶשׁ הַמִּתְאַוָּה אוֹמֶרֶת לָאַחֶרֶת: אָבִינוּ זָקֵן, נִרְדֹּף אַחֲרָיו וְנִדְבַּק בּוֹ כִּשְׁאָר כָּל הָרְשָׁעִים שֶׁבָּעוֹלָם. וְאִישׁ אֵין בָּאָרֶץ לָבֹא עָלֵינוּ - אֵין אִישׁ צַדִּיק בָּאָרֶץ וְאֵין אִישׁ שַׁלִּיט עַל יִצְרוֹ. הַרְבֵּה רְשָׁעִים בָּאָרֶץ, אֵין אֲנַחְנוּ בִּלְבַדֵּנוּ רְשָׁעִים, נַעֲשֶׂה כְּדֶרֶךְ כָּל הָאָרֶץ שֶׁהֵם רְשָׁעִים, שֶׁעַד הַיּוֹם דֶּרֶךְ כָּל הָאָרֶץ הוּא. לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן - נִשְׂמַח בָּעוֹלָם הַזֶּה, נֹאכַל וְנִשְׁתֶּה וְנִרְוֶה יַיִן וְנִדְבַּק בְּאָבִינוּ, בַּיֵּצֶר הָרָע, וְנִשְׁכְּבָה עִמּוֹ. וְרוּחַ הַקֹּדֶשׁ צוֹוַחַת וְאוֹמֶרֶת: (ישעיה כח) גַּם אֵלֶּה בַּיַּיִן שָׁגוּ וּבַשֵּׁכָר תָּעוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בּא רְאֵה מַה כָּתוּב? וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. דֶּרֶךְ הָרְשָׁעִים לִטְעוֹת אַחֲרֵי הַיַּיִן, לְפַנֵּק לַיֵּצֶר הָרָע וּלְעוֹרְרוֹ. וְעַד שֶׁהוּא שָׂמֵחַ בְּשִׁכְרוּתוֹ שׁוֹכֵב עַל מִטָּתוֹ, מִיָּד - וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. הִיא מְזֻמֶּנֶת עִמּוֹ וּמִתְאַוָּה וּמְהַרְהֶרֶת בְּכָל הִרְהוּרִים רָעִים, וְיֵצֶר הָרָע מִתְחַבֵּר עִמָּהּ וְנִדְבָּק בָּהּ וְאֵינוֹ מַשְׁגִּיחַ בָּהּ (באותו זמן) מַה הוּא מִמֶּנָּה. בְּשִׁכְבָהּ וּבְקוּמָהּ - בְּשִׁכְבָהּ בָּעוֹלָם הַזֶּה, וּבְקוּמָהּ לֶעָתִיד לָבֹא. בְּשִׁכְבָהּ - בָּעוֹלָם הַבָּא כְּשֶׁתִּתֵּן דִּין וְחֶשְׁבּוֹן, וּבְקוּמָהּ - לְיוֹם הַדִּין, שֶׁכָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹ'. בְּשׁוּם עִנְיָן מֵאֵלּוּ אֵין מַשְׁגִּיחַ בּוֹ יֵצֶר הָרָע, אֶלָּא דָּבֵק בָּהּ וְהִיא נִדְבֶּקֶת בּוֹ, וּלְאַחַר כֵּן מְעוֹרֶרֶת לָאַחֶרֶת. לְאַחַר שֶׁהַהִרְהוּר גָּדוֹל נִדְבַּק בַּיֵּצֶר הָרָע, בָּאָה הָאַחֶרֶת וְנִדְבֶּקֶת בּוֹ,</p>\n<p>וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. כְּמוֹ כֵן לְעוֹרֵר לַיֵּצֶר הָרָע וְנִדְבֶּקֶת בּוֹ, וַאֲזַי תַּשְׁלוּם הָרָעוֹת לַעֲשׂוֹת, וּמִתְעַבְּרוֹת שְׁתֵּיהֶן מִיֵּצֶר הָרָע. זֶהוּ שֶׁכָּתוּב וַתַּהֲרֶיןָ שְׁתֵּי בְנוֹת לוֹט מֵאֲבִיהֶן. עַד שֶׁיָּצָא לַפֹּעַל מַעֲשֵׂיהֶן - זוֹ יוֹלֶדֶת רִשְׁעָתָהּ, וְזוֹ יוֹלֶדֶת רִשְׁעָתָהּ. וְכֵן דַּרְכָּם שֶׁל רְשָׁעִים בְּעִנְיָן זֶה עִם יֵצֶר הָרָע, עַד שֶׁהוֹרֵג לָאָדָם וּמוֹלִיכוֹ לַגֵּיהִנֹּם וּמַכְנִיסוֹ שָׁם, וְאַחַר כָּךְ עוֹלֶה מִשָּׁם לְפַתּוֹת לִבְנֵי אָדָם כְּמוֹ כֵן. וּמִי שֶׁמַּכִּיר בּוֹ, נִצּוֹל מִמֶּנּוּ וְאֵינוֹ מִתְחַבֵּר עִמּוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְכַת לִסְטִים שֶׁהָיוּ אוֹרְבִים בַּדְּרָכִים לִגְזל וְלַהֲרֹג לִבְנֵי אָדָם, וּמַפְרִישִׁים מֵהֶם אֶחָד שֶׁיּוֹדֵעַ לְהָסִית לִבְנֵי אָדָם וּלְשׁוֹנוֹ רַךְ. מָה עוֹשֶׂה? מַקְדִּים וְהוֹלֵךְ לְקַבְּלָם וְנַעֲשֶׂה כְּעֶבֶד לִפְנֵיהֶם, עַד שֶׁמַּאֲמִינִים הַטִּפְּשִׁים בּוֹ וּבוֹטְחִים בְּאַהֲבָתוֹ וּבְשִׂיחָתוֹ וּשְׂמֵחִים עִמּוֹ, וּמוֹלִיכָם בְּחֵלֶק דְּבָרָיו בְּאוֹתוֹ הַדֶּרֶךְ שֶׁהַלִּסְטִים שָׁם. כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג בָּם לְאַחַר שֶׁנּוֹתְנָם בְּיַד הַלִּסְטִים לְהָרְגָם וְלָקַחַת מָמוֹנָם. וְהֵם צוֹוְחִים וְאוֹמְרִים: אוֹי שֶׁהִקְשַׁבְנוּ לוֹ וּלְרֹךְ לְשׁוֹנוֹ. לְאַחַר שֶׁהָרְגוּ אֵלֶּה, עוֹלֶה מִשָּׁם וְיוֹצֵא לְפַתּוֹת בְּנֵי אָדָם כְּמִתְּחִלָּה. הַפִּקְחִים מַה הֵם עוֹשִׂים כְּשֶׁרוֹאִים לָזֶה יוֹצֵא לִקְרָאתָם וּמְפַתֶּה לָהֶם? מַכִּירִין בּוֹ שֶׁהוּא צוֹדֶה אֶת נַפְשָׁם, וְהוֹרְגִים אוֹתוֹ, והוֹלְכִים בְּדֶרֶךְ אַחֶרֶת. כָּךָ הוּא יֵצֶר הָרָע, יוֹצֵא מִכַּת הַלִּסְטִים, עוֹלֶה מִגֵּיהִנֹּם כְּנֶגֶד בְּנֵי אָדָם וּלְפַתּוֹת לָהֶם בְּחֵלֶק מֶתֶק דְּבָרָיו. זֶהוּ שֶׁכָּתוּב וַיַּעַל לוֹט מִצּוֹעַר וַיֵּשֶׁב בָּהָר וְגוֹ'. כְּמוֹ לִסְטִים לֶאֱרֹב לִבְנֵי אָדָם. מָה עוֹשֶׂה? עוֹבֵר לִפְנֵיהֶם, וְהַטִּפְּשִׁים מַאֲמִינִים בּוֹ וּבְאַהֲבָתוֹ שֶׁהוּא הוֹלֵךְ לְפַתּוֹתָם וְעוֹבֵד לָהֶם כְּעֶבֶד, שֶׁנּוֹתֵן לָהֶם נָשִׁים יָפוֹת אֲסוּרוֹת, נוֹתֵן לָהֶם בְּנֵי אָדָם לְהָרַע, מְפָרֵק מֵהֶם עֹל תוֹרָה וְעֹל מַלְכוּת שָׁמַיִם. הַטִּפְּשִׁים רוֹאִים כָּךְ, בּוֹטְחִים בְּאַהֲבָתוֹ, עַד שֶׁהוֹלֵךְ עִמָּהֶם וּמוֹלִיכָם בְּאוֹתוֹ דֶרֶךְ שֶׁהַלִּסְטִים שָׁם, בְּדֶרֶךְ גֵּיהִנֹּם אֲשֶׁר אֵין דֶּרֶךְ לִנְטוֹת יָמִין וּשְׂמֹאל. כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג לָהֶם, וְנַעֲשֶׂה לָהֶם מַלְאַךְ הַמָּוֶת וּמַכְנִיסָן לַגֵּיהִנֹּם, וּמוֹרִידִים לָהֶם מַלְאֲכֵי חַבָּלָה, וְהֵם צוֹוְחִים וְאוֹמְרִים: אוֹי שֶׁהִקְשַׁבְנוּ לָזֶה. וְלֹא מוֹעִיל לָהֶם. לְאַחַר כֵּן עוֹלֶה מִשָּׁם וְיוֹצֵא לְפַתּוֹת לִבְנֵי אָדָם. הַפִּקְחִים כְּשֶׁרוֹאִים אוֹתוֹ, מַכִּירִים אוֹתוֹ, וּמִתְגַּבְּרִים עָלָיו עַד שֶׁשּׁוֹלְטִים עָלָיו, וְסוֹטִים מִזֶּה הַדֶּרֶךְ וְלוֹקְחִים דֶּרֶךְ אַחֶרֶת לְהִנָּצֵל מִמֶּנּוּ.</p>\n<p>רַב יוֹסֵף כְּשֶׁהָיָה יוֹרֵד לְבָבֶל, רָאָה אֶת אוֹתָם רַוָּקִים שֶׁהָיוּ נִכְנָסִים וְיוֹצְאִים בֵּין נָשִׁים יָפוֹת וְלֹא חוֹטְאִים. אָמַר לָהֶם: הַאִם אֵלֶּה לֹא פוֹחֲדִים מִיֵּצֶר הָרָע? אָמְרוּ לוֹ: לֹא מִקּוֹנְדִיטוֹן רַע בָּאנוּ. אָנוּ נִגְזַרְנוּ מִקְּדֻשַּׁת הַקֹּדֶשׁ. שֶׁאָמַר רַב יְהוּדָה אָמַר רַב, צָרִיךְ אָדָם לְקַדֵּשׁ עַצְמוֹ בִּשְׁעַת תַּשְׁמִישׁ, וְיֵצְאוּ מִמֶּנּוּ בָּנִים קְדוֹשִׁים בָּנִים מְעֻלִּים שֶׁלֹּא פוֹחֲדִים מִיֵּצֶר הָרָע, שֶׁנֶּאֱמַר (ויקרא כ) והתקדשתם והייתם קדשים.</p>\n<p>רַבִּי אַבָּא אָמַר, מַה זֶּה שֶׁכָּתוּב (יחזקאל כ) וְאֶת שַׁבְּתוֹתַי קַדֵּשׁוּ? אֶלָּא אֵין עוֹנָתָם שֶׁל תַּלְמִידֵי חֲכָמִים אֶלָּא מִשַּׁבָּת לְשַׁבָּת. וּמַזְהִיר אוֹתָם, שֶׁהוֹאִיל וְתַשְׁמִישׁ הַמִּטָּה הִיא מִצְוָה - קַדֵּשׁוּ, כְּלוֹמַר קַדְּשׁוּ עַצְמְכֶם בְּשַׁבְּתוֹתַי בְּאוֹתוֹ תַשְׁמִישׁ שֶׁל מִצְוָה. אָמַר רַב יְהוּדָה אָמַר רַב, מִי שֶׁנִּכְנָס לָעִיר וְרוֹאִים נשִׁים יָפוֹת, יַרְכִּין עֵינָיו וְיֹאמַר כָּךְ: בְּךְ (ראה) מֵחֲשׁוּבִים חָצוֹב נֶחְצַבְתִּי (חזק) דְּפוּס הַתְּקָלָה, צֵא צֵא, שֶׁאָבִי הַקָּדוֹשׁ שֶׁל שַׁבָּת הוּא. מָה הַטַּעַם? מִשּׁוּם שֶׁחֲמִימוּת הַדֶּרֶךְ שׁוֹלֵט בּוֹ, וְיָכוֹל יֵצֶר הָרָע לִשְׁלֹט עָלָיו. עד כאן מדרש הנעלם</p>"],[9522011237,"<p>וַיַּעַל לוֹט מִצּוֹעַר וְגוֹ', מִתּוֹךְ רְצוֹן הַמֶּלֶךְ, נִפְרַד מִצַּד הַיָּמִין הִתּוּךְ אֶחָד שֶׁל קֶשֶׁר שֶׁהַחֲקִיקָה דְּבוּקָה בְּתוֹךְ הִתּוּךְ הַזָּהָב מִצַּד הַשְּׂמֹאל בְּתוֹךְ טֻמְאָה (של יצרו) (נ\"א ומקומו) וְנַעֲשָׂה שֶׁל קֶשֶׁר אֶחָד שֶׁל הָאִילָן.</p>\n<p>כְּשֶׁרָצָה יִצְחָק לְהִתְעוֹרֵר בָּעוֹלָם, בַּחֹזֶק שֶׁל הַדִּין הַקָּשֶׁה הִתְחַזֵּק וְהִפְרִיד דְּרָגוֹת מִקִּיּוּמָם, וְהִתְחַזֵּק אַבְרָהָם וְהִפְרִיד אוֹתוֹ קֶשֶׁר אֶחָד שֶׁל הָאִילָן מִתּוֹךְ אוֹתָהּ טֻמְאָה.</p>\n<p>אוֹתוֹ נָחָשׁ הַקַּדְמוֹנִי נִכְנַס בְּשָׁרְשׁוֹ שֶׁל אוֹתוֹ הָעֵץ, וְהוּא הַיַּיִן שֶׁשָּׁתָה וְהוֹלִיד שְׁתֵּי דְרָגוֹת קְשׁוּרוֹת זוֹ בָּזוֹ. וְהֵן הַדְּרָגוֹת שֶׁסּוֹבְבוֹת בְּצַד הַטֻּמְאָה, אֶחָד נִקְרָא מִלְכּוֹ\"ם וְאֶחָד נִקְרָא פְּעוֹ\"ר.</p>\n<p>זוֹ עֵצָה בְּנִכְסֶה, וְזוֹ עֵצָה בְּגִלּוּי. פְּעוֹ\"ר, שֶׁהִתְגַּלָּה הוּא וְכָל מַעֲשָׂיו בְּגִלּוּי. מִלְכּוֹ\"ם, שֶׁהוּא בְּכִסּוּי. הוּא וְכָל מַעֲשָׂיו מְכֻסִּים. מִשְּׁנֵי אֵלֶּה נִפְרָדִים מִינִים רַבִּים לְמִינֵיהֶם וְסוֹבְבִים אֶת הַיָּם הַגָּדוֹל וְאֶת כָּל הַצְּדָדִים הַטְּמֵאִים הַלָּלוּ, וְכָל אֶחָד וְאֶחָד קוֹפֵץ (נ\"א נזף) לִמְקוֹמוֹ.</p>\n<p>כְּמוֹ כֵן הוּא לְמַטָּה. לוֹט נִפְרַד מֵאַבְרָהָם וְשָׂם דִּיּוּרוֹ עִם אַנְשֵׁי סְדם, כְּשֶׁהִתְעוֹרֵר עֲלֵיהֶם הַדִּין נִזְכַּר בְּאַבְרָהָם, וְשָׁלַח לוֹ מִשָּׁם וְנִפְרַד מֵהֶם.</p>\n<p>בְּנוֹתָיו הִשְׁקוּהוּ יַיִן וְהוֹלִידוּ מִמֶּנּוּ שְׁתֵּי אֻמּוֹת. אַחַת נִקְרֵאת מוֹאָב וְאַחַת נִקְרֵאת עַמּוֹן. אַחַת בְּגִלּוּי וְאַחַת בְּכִסּוּי. עַמּוֹן דַּרְגָּתוֹ מִלְכּוֹ\"ם, עֵצָה בְּכִסּוּי. מוֹאָב דַּרְגָּתוֹ פְּעוֹ\"ר, הַכֹּל בְּגִלּוּי.</p>\n<p>כְּמוֹ זֶה בְּנוֹתָיו. אַחַת אָמְרָה בֶּן עַמִּי, בֵּן יֵשׁ לִי מֵעַמִּי וְלֹא אָמְרָה מִמִּי הוּא, מִשּׁוּם כָּךְ הוּא הָיָה בְּכִסּוּי. זוֹ אָמְרָה מוֹאָב, מֵאָב הוּא זֶה, מֵאַבָּא הוֹלַדְתִּיהוּ, דַּרְגָּתוֹ פְּעוֹ\"ר, הַדָּבָר בְּגִלּוּי.</p>\n<p>וּבִשְׁנֵי אֵלֶּה אָחַז דָּוִד הַמֶּלֶךְ, לְאַחַר מִכֵּן מִמּוֹאָב בָּאָה רוּת וְיָצָא מִמֶּנָּה דָּוִד הַמֶּלֶךְ, וּמֵעַמּוֹן הִתְעַטֵּר דָּוִד הַמֶּלֶךְ בָּעֲטָרָה הַזּוֹ שֶׁהִיא עֵדוּת לְזַרְעוֹ שֶׁל דָּוִד, שֶׁכָּתוּב (מלכים ב יא) וַיִּתֵּן עָלָיו אֶת הַנֵּזֶר וְאֶת הָעֵדוּת. וְזוֹ הָיְתָה מִמִּלְכּוֹ\"ם דַּרְגַּת בְּנֵי עַמּוֹן, שֶׁכָּתוּב (שמואל ב יב) וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם.</p>\n<p>מִלְכֹּם דַּרְגַּת בְּנֵי עַמּוֹן הוּא, שֶׁכָּתוּב וַתְּהִי עַל רֹאשׁ דָּוִד, וּמִשָּׁם הָיְתָה עֵדוּת לְבָנָיו לְעוֹלָמִים, וּבָהּ נוֹדַע מִי הוּא מִן בְּנֵי דָוִד הַמֶּלֶךְ שֶׁרָאוּי לִמְלֹךְ וַדַּאי שֶׁאוֹמְרִים מִן דָּוִד הוּא (הגוף). שֶׁאֲפִלּוּ שֶׁנּוֹלַד בְּאוֹתוֹ הַיּוֹם, יָכוֹל הָיָה לִסְבֹּל בָּעֲטָרָה הַהִיא עַל רֹאשׁוֹ (שהרי הוא) שֶׁהָיָה מִשְׁקַל כִּכַּר זָהָב וְאֶבֶן יְקָרָה הָיְתָה, וּבֶן אָדָם אַחֵר לֹא יָכוֹל לִסְבֹּל אוֹתָהּ. וְזֶהוּ שֶׁכָּתוּב בְּיוֹאָשׁ, וַיִּתֵּן עָלָיו אֶת הַנֵּזֶר וְאֶת הָעֵדוּת.</p>\n<p>וּבִשְׁתֵּי דְרָגוֹת נֶאֱחַז דָּוִד הַמֶּלֶךְ, וְהֵם תֹּקֶף מַלְכוּתוֹ לְהִתְחַזֵּק עַל שְׁאָר הָעַמִּים, שֶׁאִם לֹא נִכְלָל בַּצַּד שֶׁלָּהֶם, לֹא יָכוֹל לְהִתְגַּבֵּר עֲלֵיהֶם כָּל (הגונים) הַדְּרָגוֹת שֶׁל שְׁאָר הָעַמִּים כְּלוּלִים בְּדָוִד לְהִתְגַּבֵּר וּלְהִתְחַזֵּק עֲלֵיהֶם.</p>\n<p>וַיַּעַל לוֹט מִצּוֹעַר וַיֵּשֶׁב בָּהָר. כָּתוּב (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. אֵלּוּ שְׁתֵּי בָנוֹת שֶׁל יֵצֶר הָרָע מְעוֹרְרוֹת אוֹתוֹ (כדי) לִשְׁלֹט עַל הַגּוּף. אַחַת הִיא נֶפֶשׁ שֶׁמִּתְרַבָּה תָּמִיד בַּגּוּף, וְאַחַת הִיא נֶפֶשׁ שֶׁכּוֹסֶפֶת לְתַאֲווֹת רָעוֹת (ד\"א של העולם הזה) וּבְכָל הַכִּסּוּפִים הָרָעִים שֶׁל הָעוֹלָם הַזֶּה. זוֹהִי הַבְּכִירָ\"ה, וְזוֹ (ואחרת) הַצְּעִירָ\"ה.</p>\n<p>וְיֵצֶר הָרָע לֹא מִתְחַבֵּר תָּמִיד אֶלָּא בִּשְׁתֵּי אֵלֶּה כְּדֵי לְפַתּוֹת בְּנֵי אָדָם, וּכְדֵי שֶׁיַּאֲמִינוּ לוֹ (להוביל) לְהַאֲבִיד אוֹתָם לִמְקוֹם חִצֵּי הַמָּוֶת וְיַעַבְדוּ אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שם ז) עַד יְפַלַּח חֵץ כְּבֵדוֹ.</p>\n<p>לְלִסְטִים שֶׁמְּקַפְּחִים בֶּהָרִים, וּמַסְתִּירִים עַצְמָם בְּמָקוֹם מַפְחִיד בֶּהָרִים, וְיוֹדְעִים שֶׁהֲרֵי בְּנֵי אָדָם שׁוֹמְרִים עַצְמָם מִלָּלֶכֶת לַמְּקוֹמוֹת הַלָּלוּ, מָה עוֹשִׂים? בּוֹחֲרִים מֵהֶם אוֹתוֹ שֶׁלְּשׁוֹנוֹ חַדָּה מִכֻּלָּם, אוֹתוֹ שֶׁיּוֹדֵעַ לְפַתּוֹת בְּנֵי אָדָם, וְיוֹצֵא מִבֵּינֵיהֶם וְיוֹשֵׁב בְּדֶרֶךְ יְשָׁרָה שֶׁכָּל בְּנֵי הָעוֹלָם עוֹבְרִים שָׁם. כֵּיוָן שֶׁמַּגִּיעַ אֲלֵיהֶם, מַתְחִיל לְהִתְחַבֵּר עִמָּם (ולפתותם). (עד כאן סתרי תורה).</p>"],[9522011238,"<p>וַיִּסַּע מִשָּׁם אַבְרָהָם אַרְצָה הַנֶּגֶב. כָּל מַסְעוֹתָיו הָיוּ לְצַד דָּרוֹם יוֹתֵר מִלְּצַד אַחֵר, מִשּׁוּם שֶׁהֲרֵי בְּחָכְמָה עָשָׂה לְהִדָּבֵק בַּדָּרוֹם.</p>\n<p>וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחֹתִי הִוא. שָׁנִינוּ, (כיון) לֹא צָרִיךְ אָדָם לִסְמֹךְ עַל הַנֵּס, וְאִם הַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִישׁ נֵס לְבֶן אָדָם, אֵין לוֹ לִסְמֹךְ תָּמִיד עַל נֵס בְּפַעַם אַחֶרֶת, כִּי לֹא בְכָל שָׁעָה וְשָׁעָה מִתְרַחֵשׁ נֵס.</p>\n<p>וְאִם יַכְנִיס אָדָם אֶת עַצְמוֹ לְמָקוֹם שֶׁהַנֵּזֶק מָצוּי לָעַיִן, הֲרֵי פָּקְעָה כָּל זְכוּתוֹ שֶׁעָשָׂה בַּתְּחִלָּה וּבֵאֲרוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לב) קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת וְגוֹ'. וְאַבְרָהָם, כֵּיוָן שֶׁעָלָה מִמִּצְרַיִם וְנִצּוֹל פַּעַם אַחַת, כָּעֵת לָמָּה הִכְנִיס אֶת עַצְמוֹ בְּצַעַר כְּבַתְּחִלָּה וְאָמַר אֲחֹתִי הִוא?</p>\n<p>אֶלָּא אַבְרָהָם לֹא סָמַךְ עַל עַצְמוֹ כְּלוּם, שֶׁרָאָה אֶת הַשְּׁכִינָה תָּמִיד בִּמְדוֹרָהּ שֶׁל שָׂרָה וְלֹא זָזָה מִשָּׁם, וּמִשּׁוּם שֶׁהָיְתָה שָׁם, סָמַךְ אַבְרָהָם וְאָמַר אֲחֹתִי הִוא, כְּמוֹ שֶׁכָּתוּב (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ, וְלָכֵן אָמַר אֲחֹתִי הִוא.</p>\n<p>וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ וְגוֹ'. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא אֶל רְשָׁעִים? כְּמוֹ שֶׁכָּתוּב (במדבר כב) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם, (בראשית לא) וַיָּבֹא אֱלֹהִים אֶל לָבָן? אֶלָּא אוֹתוֹ מְמֻנֶּה הַשָּׁלִיחַ שֶׁמֻּפְקָד עֲלֵיהֶם הָיָה מִשּׁוּם שֶׁכֻּלָּם, כְּשֶׁעוֹשִׂים שְׁלִיחוּת, נוֹטְלִים הַשֵּׁם הַזֶּה, מִצַּד הַדִּין הֵם בָּאִים. וְעַל זֶה וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלָּיְלָה וַיֹּאמֶר לוֹ הִנְּךְ מֵת עַל הָאִשָּׁה אֲשֶׁר לָקַחְתָּ וְגוֹ'.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי יב) שְׂפַת אֱמֶת וְגוֹ'. שְׂפַת אֱמֶת תִּכּוֹן לָעַד - זֶה אַבְרָהָם, שֶׁכָּל דְּבָרָיו בַּהַתְחָלָה וּבַסּוֹף הָיוּ בֶּאֱמֶת. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר - זֶה אֲבִימֶלֶךְ.</p>\n<p>בְּאַבְרָהָם נֶאֱמַר, וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחֹתִי הִוא. זֶה בַּהַתְחָלָה שֶׁאָמַר מִשּׁוּם הַשְּׁכִינָה שֶׁהָיְתָה עִמָּהּ שֶׁל שָׂרָה אֲחֹתִי הִיא, וְאַבְרָהָם עָשָׂה בְּחָכְמָה.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאַבְרָהָם הוּא מִצַּד הַיָּמִין, אָמַר אֲחֹתִי הִוא, וְסוֹד כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) אֲחֹתִי רַעְיָתִי יוֹנָתִי תַמָּתִי. וְעַל זֶה אַבְרָהָם קָרָא לָהּ תָּמִיד אֲחוֹתִי, מִשּׁוּם שֶׁנִּדְבָּק עִמָּהּ, וְלא יָזוּזוּ זֶה מִזֶּה לְעוֹלָמִים.</p>\n<p>לְבַסּוֹף מַה כָּתוּב? וְגַם אָמְנָה אֲחֹתִי בַת אָבִי הִוא אַךְ לֹא בַת אִמִּי. וְכִי כָּךְ הָיָה? אֶלָּא הַכֹּל מִשּׁוּם הַשְּׁכִינָה אָמַר אֲחֹתִי הִוא בַּהַתְחָלָה, שֶׁכָּתוּב אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. אַחַר כָּךְ וְגַם אָמְנָה. מַה זֶּה וְגַם? לְהוֹסִיף עַל מַה שֶּׁאָמַר בַּתְּחִלָּה. אֲחֹתִי בַת אָבִי הִוא, הַבַּת שֶׁל הַחָכְמָה הָעֶלְיוֹנָה, וְלָכֵן נִקְרֵאת אֲחוֹתִי וְנִקְרֵאת חָכְמָה, אַךְ לֹא בַּת אִמִּי, מֵהַמָּקוֹם שֶׁל רֵאשִׁית הַכֹּל הַנִּסְתָּר הָעֶלְיוֹן. וְעַל זֶה וַתְּהִי לִי לְאִשָּׁה, בְּאַחֲוָה וַחֲבִיבוּת, שֶׁכָּתוּב (שם ב) וִימִינוֹ תְחַבְּקֵנִי, וְהַכֹּל סוֹד שֶׁל חָכְמָה.</p>\n<p>בֹּא רְאֵה, בַּהַתְחָלָה כְּשֶׁיָּרְדוּ לְמִצְרַיִם כָּךְ אָמַר בִּשְׁבִיל לְהִדָּבֵק בְּתוֹךְ הָאֱמוּנָה, וְקָרָא לָהּ אֲחֹתִי כְּדֵי שֶׁלֹּא יִטְעוּ לְתוֹךְ אוֹתָם הַדְּרָגוֹת שֶׁבַּחוּץ. אַף כָּאן אֲחֹתִי, כְּדֵי שֶׁלֹּא תָזוּז מִתּוֹךְ הָאֱמוּנָה כָּרָאוּי.</p>\n<p>שֶׁהֲרֵי אֲבִימֶלֶךְ וְכָל אוֹתָם יוֹשְׁבֵי הָאָרֶץ הָיוּ הוֹלְכִים אַחַר עֲבוֹדָה זָרָה, וְהוּא נִדְבַּק בְּתוֹךְ הָאֱמוּנָה וּמִשּׁוּם כָּךְ נִכְנַס לְשָׁם וְאָמַר אֲחֹתִי. מָה הָאָחוֹת לֹא נִפְרֶדֶת מִן הָאָח לְעוֹלָמִים - אַף כָּאן. שֶׁהֲרֵי אִשָּׁה יְכוֹלָה לְהִפָּרֵד, אֲבָל אָחוֹת לֹא נִפְרֶדֶת, שֶׁהֲרֵי שְׁנֵי אַחִים לֹא יְכוֹלִים לְהִפָּרֵד לְעוֹלָמִים וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>וְלָכֵן אָמַר אַבְרָהָם אֲחֹתִי הִוא, שֶׁהֲרֵי כֻּלָּם הָיוּ לְהוּטִים בְּתוֹךְ קִשְׁרֵי הַכּוֹכָבִים וּמַזָּלוֹת וְעוֹבְדִים אוֹתָם, וְאַבְרָהָם הָיָה דָבֵק בְּתוֹךְ הָאֱמוּנָה, וְאָמַר אֲחוֹתִי, שֶׁלֹּא נִפְרָד לְעוֹלָמִים. וְסִימָן לַדָּבָר - (ויקרא כא) וְלַאֲחֹתוֹ הַבְּתוּלָה, שֶׁנֶּאֱמַר לַכֹּהֵן הַמָּקוֹם שֶׁאַבְרָהָם שָׁרוּי בּוֹ.</p>\n<p>כָּתוּב (דברים י) אֶת ה' אֱלֹהֶיךְ תִּירָא אֹתוֹ תַעֲבֹד וּבוֹ תִדְבָּק וּבִשְׁמוֹ תִשָּׁבֵעַ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה, לַה' אֱלֹהֶיךְ תִּירָא לֹא כָתוּב, אֶלָּא כָּתוּב אֶת ה'. מַה זֶּה אֶת? זוֹ הַדַּרְגָּה הָרִאשׁוֹנָה, הַמָּקוֹם שֶׁל יִרְאת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן כָּתוּב תִּירָא, שֶׁשָּׁם אָדָם צָרִיךְ לִירָא לִפְנֵי רִבּוֹנוֹ (הקדוש ברוך הוא), מִשּׁוּם שֶׁהוּא (בית) דִּין.</p>\n<p>וְאֹתוֹ תַעֲבֹד - זוֹ הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁעוֹמֶדֶת עַל הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ, וְלֹא נִפְרָדִים לְעוֹלָמִים. אֶת וְאֹתוֹ זֶה עִם זֶה דְּבֵקִים וְלֹא נִפְרָדִים. מַה זֶּה וְאֹתוֹ? זֶה מְקוֹם בְּרִית הַקֹּדֶשׁ, אוֹת לְעוֹלָמִים. שֶׁהֲרֵי עֲבוֹדָה לֹא שׁוֹרָה בְּאוֹת וְאֵינוֹ לַעֲבֹד אֶלָּא לִירָא, אֲבָל הָעֲבוֹדָה הִיא לְמַעְלָה, וְלָכֵן וְאֹתוֹ תַעֲבֹד.</p>\n<p>וּבוֹ תִדְבָּק - בְּמָקוֹם שֶׁהוּא דְּבֵקוּת לְהִדָּבֵק שֶׁהוּא גוּף שֶׁשּׁוֹרֶה בָּאֶמְצַע. וּבִשְׁמוֹ תִשָּׁבֵעַ - הַמָּקוֹם הַשְּׁבִיעִי שֶׁל הַדְּרָגוֹת, וְסִימָן לַדָּבָר - (ירמיה ל) וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם.</p>\n<p>מִשּׁוּם כָּךְ נִדְבַּק אַבְרָהָם בָּאֱמוּנָה כְּשֶׁיָּרַד לְמִצְרַיִם וּכְשֶׁהָלַךְ לְאֶרֶץ פְּלִשְׁתִּים. לְאָדָם שֶׁרָצָה לָרֶדֶת לְבוֹר עָמֹק, פָּחַד שֶׁלֹּא יוּכַל לַעֲלוֹת מִתּוֹךְ הַבּוֹר, מֶה עָשָׂה? קָשַׁר קֶשֶׁר אֶחָד שֶׁל חֶבֶל לְמַעְלָה מֵהַבּוֹר. אָמַר, הוֹאִיל וְקָשַׁרְתִּי קֶשֶׁר זֶה, מִכָּאן וָהָלְאָה אֶכָּנֵס לְשָׁם. כָּךְ אַבְרָהָם, בְּשָׁעָה שֶׁרָצָה לָרֶדֶת לְמִצְרַיִם, עַד שֶׁלֹּא יָרַד לְשָׁם קָשַׁר בַּתְּחִלָּה אֶת קֶשֶׁר הָאֱמוּנָה לְהִתְחַזֵּק בּוֹ, וְאַחַר כָּךְ יָרַד.</p>\n<p>אַף כָּךְ גַּם כְּשֶׁנִּכְנַס לְאֶרֶץ פְּלִשְׁתִּים. מִשּׁוּם כָּךְ (משלי יב) שְׂפַת אֱמֶת תִּכּוֹן לָעַד. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר - זֶה אֲבִימֶלֶךְ שֶׁאָמַר בְּתָם לְבָבִי וּבְנִקְיֹן כַּפַּי. וּכְשֶׁהֶחֱזִירוּ לוֹ מַה כָּתוּב? גַּם אָנֹכִי יָדַעְתִּי כִּי בְתָם לְבָבְךְ עָשִׂיתָ את, וְלֹא כָתוּב נִקְיוֹן כַּפַּיִם.</p>\n<p>וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שמואל א ב) רַגְלֵי חֲסִידָו יִשְׁמֹר וְגוֹ'. חֲסִידוֹ כָּתוּב אֶחָד, וְזֶה אַבְרָהָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתוֹ תָּמִיד וְלֹא מֵסִיר מִמֶּנּוּ אֶת שְׁמִירָתוֹ לְעוֹלָמִים. וּמַה שֶּׁאָמַר רַגְלֵי - זוֹ אִשְׁתּוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח שְׁכִינָתוֹ עִמָּהּ וְשׁוֹמֵר אוֹתָהּ תָּמִיד.</p>\n<p>דָּבָר אַחֵר רַגְלֵי חֲסִידָו יִשְׁמֹר - אֶחָד, זֶה אַבְרָהָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָלַךְ עִמּוֹ תָּמִיד כְּדֵי שֶׁלֹּא יוּכְלוּ לְהַזִּיק לוֹ. וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ - אֵלּוּ אוֹתָם מְלָכִים שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ לַיְלָה שֶׁרָדַף אַחֲרֵיהֶם.</p>\n<p>זְהִוּ שֶׁכָּתוּב בַּחֹשֶׁךְ יִדָּמּוּ, זֶה הַלַּיְלָה שֶׁנִּקְשַׁר בַּחֹשֶׁךְ וְהָרַג אוֹתָם, וְאַבְרָהָם רָדַף וְהַלַּיְלָה הָרַג אוֹתָם. זֶהוּ שֶׁכָּתוּב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה הוּא וַעֲבָדָיו וַיַּכֵּם. וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁחִלֵּק רַחֲמִים מִן הַדִּין כְּדֵי לַעֲשׂוֹת נְקָמוֹת לְאַבְרָהָם, וּמִשּׁוּם כָּךְ וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ. וַיַּכֵּם? הָיָה צָרִיךְ לִכְתֹּב וַיַּכּוּם! אֶלָּא זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ, שֶׁהוּא וֶאֱלִיעֶזֶר הָיוּ לְבַדָּם.</p>\n<p>רַבִּי יִצְחָק אָמַר, וַהֲרֵי שָׁנִינוּ שֶׁבְּמָקוֹם שֶׁנֵּזֶק מָצוּי שֶׁלֹּא יִסְמֹךְ בֶּן אָדָם עַל הַנֵּס, וְלֹא הָיָה מָקוֹם שֶׁהַנֵּזֶק מָצוּי כְּמוֹ זֶה שֶׁאַבְרָהָם הוֹלֵךְ אַחַר חֲמִשָּׁה מְלָכִים לִרְדֹּף אַחֲרֵיהֶם וְלַעֲרֹךְ קְרָב. אָמַר רַבִּי יְהוּדָה, כְּשֶׁהָלַךְ אַבְרָהָם עַל זֶה, לֹא הָלַךְ לַעֲרֹךְ קְרָב וְלֹא סָמַךְ עַל הַנֵּס, אֶלָּא צַעֲרוֹ שֶׁל לוֹט הוֹצִיא אוֹתוֹ מִבֵּיתוֹ, וְלָקַח מָמוֹן לִפְדּוֹת אוֹתוֹ, וְאִם לֹא - שֶׁיָּמוּת יַחַד אִתּוֹ בְּתוֹךְ שִׁבְיוֹ. כֵּיוָן שֶׁיָּצָא רָאָה שְׁכִינָה שֶׁמְּאִירָה לְפָנָיו וְכַמָּה צְבָאוֹת סְבִיבָהּ, וּבְאוֹתָהּ שָׁעָה רָדַף אַחֲרֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָרַג אוֹתָם. זֶהוּ שֶׁכָּתוּב וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, סוֹד הוּא, רַגְלֵי חֲסִידָו יִשְׁמֹר - זֶה אַבְרָהָם, וּכְשֶׁיָּצָא, הִשְׁתַּתֵּף עִמּוֹ יִצְחָק וְנָפְלוּ לְפָנָיו, וְאִם לֹא שֶׁהִשְׁתַּתֵּף יִצְחָק יַחַד עִם אַבְרָהָם, לֹא הֻשְׁמְדוּ. זֶהוּ שֶׁכָּתוּב וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ. כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ. אַף עַל גַּב שֶׁהַכֹּחַ נִמְצָא תָמִיד בַּיָּמִין, אִם לֹא הָיָה בְּצַד הַשְּׂמֹאל לֹא הָיוּ נִדְחִים לְפָנָיו.</p>\n<p>דָּבָר אַחֵר רַגְלֵי חֲסִידָו יִשְׁמֹר - בְּשָׁעָה שֶׁבֶּן אָדָם אוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתוֹ בְּכָל מַה שֶּׁהוּא עוֹשֶׂה וְשׁוֹמֵר דְּרָכָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכא) ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם</p>\n<p>בֹּא רְאֵה כַּמָּה חֲבִיבוּתוֹ שֶׁל אַבְרָהָם לַקָּבָּ\"ה, שֶׁבְּכָל מָקוֹם שֶׁהָיָה הוֹלֵךְ, לֹא הָיָה חָס עַל שֶׁלּוֹ כְּלוּם, אֶלָּא רַק כְּדֵי לְהִדָּבֵק בַּקָּבָּ\"ה, וּמִשּׁוּם כָּךְ רַגְלֵי חֲסִידָו יִשְׁמֹר, וְזוֹהִי אִשְׁתּוֹ, שֶׁכָּתוּב וַאֲבִימֶלֶךְ לֹא קָרַב אֵלֶיהָ, וְכָתוּב כִּי עַל כֵּן לֹא נְתַתִּיךְ לִנְגֹּעַ אֵלֶיהָ.</p>\n<p>בְּפַרְעֹה מַה כָּתוּב? (בראשית יב) וַיְנַגַּע ה' אֶת פַּרְעֹה וְגוֹ' עַל דְּבַר שָׂרַי. הִיא אָמְרָה - וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מַכֶּה, וּמִשּׁוּם כָּךְ רַגְלֵי חֲסִידָו יִשְׁמֹר. וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ - אֵלּוּ פַּרְעֹה וַאֲבִימֶלֶךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה בָהֶם דִּינִים בַּלַּיְלָה. כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ, מִי זֶה אִישׁ? זֶה אַבְרָהָם, שֶׁכָּתוּב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ וְגוֹ'.</p>"],[9522011239,"<p>וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עֹמֵד לִפְנֵי מַלְאַךְ ה' וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל בּוֹ. וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל - זֶה יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק. עֹמֵד לִפְנֵי מַלְאַךְ ה', מִי זֶה מַלְאַךְ ה'? זֶהוּ הַמָּקוֹם (שנשמות הצדיקים צרורות) צְרוֹר שֶׁל נִשְׁמַת הַצַּדִּיק צְרוּרָה בּוֹ, וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים עוֹמְדוֹת שָׁם, וְזֶהוּ מַלְאַךְ ה'.</p>\n<p>וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ - זֶהוּ יֵצֶר הָרָע שֶׁהוּא מְשׁוֹטֵט וְהוֹלֵךְ בָּעוֹלָם לִטֹּל נְשָׁמוֹת וּלְהוֹצִיא רוּחוֹת וּלְהַסְטוֹת אֶת הַבְּרִיּוֹת לְמַעְלָה וּלְמַטָּה. וְזֶהוּ בְּשָׁעָה שֶׁהִטִּיל אוֹתוֹ נְבוּכַדְנֶצַּר לָאֵשׁ עִם אוֹתָם נְבִיאֵי הַשֶּׁקֶר, וְזֶה הָיָה מַסְטִין לְמַעְלָה כְּדֵי שֶׁיִּשָּׂרֵף עִמָּם.</p>\n<p>שֶׁכָּךָ הִיא דַּרְכּוֹ - שֶׁאֵינוֹ מְקַטְרֵג אֶלָּא בִּזְמַן שֶׁל סַכָּנָה וּבִזְמַן שֶׁהַצַּעַר שׁוֹרֶה בָּעוֹלָם, וְיֵשׁ לוֹ רְשׁוּת לְהַסְטוֹת וְלַעֲשׂוֹת דִּין אֲפִלּוּ בְּלִי דִין, כְּמוֹ שֶׁנֶּאֱמַר (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. מַה זֶּה לְשִׂטְנוֹ? שֶׁהָיָה אוֹמֵר, אוֹ שֶׁכֻּלָּם יִנָּצְלוּ אוֹ שֶׁכֻּלָּם יִשָּׂרְפוּ. שֶׁהֲרֵי בְּשָׁעָה שֶׁנִּתְּנָה רְשׁוּת לַמַּשְׁחִית לְחַבֵּל, לֹא נִצּוֹל הַצַּדִּיק מֵהָרְשָׁעִים.</p>\n<p>וְלָכֵן בְּשָׁעָה שֶׁהַדִּין שָׁרוּי בָּעִיר, צָרִיךְ בֶּן אָדָם לִבְרֹחַ בְּטֶרֶם שֶׁיִּתָּפֵס שָׁם, שֶׁהֲרֵי הַמַּשְׁחִית, כֵּיוָן שֶׁמַּתְחִיל, כָּךְ גַּם עוֹשֶׂה לַצַּדִּיק כְּמוֹ לָרָשָׁע, וְכָל שֶׁכֵּן שֶׁהָיוּ שְׁלָשְׁתָּם כְּאֶחָד. וְהָיָה תוֹבֵעַ שֶׁיִּשָּׂרְפוּ כֻלָּם אוֹ יִנָּצְלוּ כֻלָּם. מִשּׁוּם שֶׁכְּשֶׁנַּעֲשֶׂה נֵס, לֹא נַעֲשֶׂה חֲצִי נֵס וַחֲצִי דִין, אֶלָּא הַכֹּל כְּאֶחָד, אוֹ נֵס אוֹ דִין.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסִי, וָלֹא? וַהֲרֵי בִּזְמַן שֶׁבָּקַע הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַיָּם לְיִשְׂרָאֵל, הָיָה קוֹרֵעַ אֶת הַיָּם לְאֵלֶּה וְהֵם הוֹלְכִים בַּיַּבָּשָׁה, וְהַמַּיִם הָיוּ שָׁבִים מִצַּד אַחֵר וּמַטְבִּיעִים אֶת אֵלֶּה וּמֵתִים. וְנִמְצָא נֵס כָּאן וְדִין כָּאן, הַכֹּל כְּאֶחָד.</p>\n<p>אָמַר לוֹ, וְזֶהוּ שֶׁקָּשֶׁה לְפָנָיו, שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין וְנֵס כְּאֶחָד, לֹא בְּמָקוֹם אֶחָד וְלֹא בְּבַיִת אֶחָד (שהכל נמצא כאחד). וְאִם נַעֲשֶׂה קָשֶׁה לְפָנָיו, שֶׁהֲרֵי לְמַעְלָה לֹא נַעֲשֶׂה הַכֹּל אֶלָּא בִּשְׁלֵמוּת כְּאֶחָד, אוֹ נֵס אוֹ דִין בְּמָקוֹם אֶחָד וְלֹא לַחֲצָאִין.</p>\n<p>לָכֵן לֹא עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בָּרְשָׁעִים עַד שֶׁיִּשְׁתַּלְּמוּ בְּחֶטְאָם. זֶהוּ שֶׁכָּתוּב (בראשית טו) כִּי לֹא שָׁלֵם עֲון הָאֱמֹרִי עַד הֵנָּה, וְכָתוּב (ישעיה כז) בְּסַאסְּאָה בְּשַׁלְּחָהּ תְּרִיבֶנָּה. וְעַל זֶה הָיָה מַסְטִין לִיהוֹשֻׁעַ שֶׁיִּשָּׂרֵף עִמָּם, עַד שֶׁאָמַר לוֹ (זכריה ג) יִגְעַר ה' בְּךְ הַשָּׂטָן. מִי אָמַר לוֹ? זֶה מַלְאַךְ ה' (ונאמר ויאמר ה' אל השטן).</p>\n<p>וְאִם תֹּאמַר, וַיֹּאמֶר ה' אֶל הַשָּׂטָן יִגְעַר ה' בְּךְ וְגוֹ'? בֹּא רְאֵה, כָּךְ גַּם לְמֹשֶׁה בַּסְּנֶה, שֶׁכָּתוּב (שמות ג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ, וְכָתוּב וַיַּרְא ה' כִּי סָר לִרְאוֹת. לִפְעָמִים מַלְאַךְ ה', וְלִפְעָמִים מַלְאָךְ, וְלִפְעָמִים ה'. וְלָכֵן אָמַר לוֹ יִגְעַר ה' בְּךְ הַשָּׂטָן וְלֹא אָמַר הִנְנִי גּוֹעֵר בְּךְ.</p>\n<p>בֹּא רְאֵה, כְּמוֹ זֶה בַּיּוֹם שֶׁנִּמְצָא דִין בָּעוֹלָם וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא הַדִּין, אָז נִמְצָא הַשָּׂטָן הַזֶּה שֶׁמַּסְטֶה לְמַעְלָה וּלְמַטָּה, וְהוּא נִמְצָא לְהַשְׁחִית אֶת הָעוֹלָם וְלִטֹּל הַנְּשָׁמוֹת.</p>"],[9522011240,"<p>רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב וְלוֹמֵד תּוֹרָה, וְהָיָה מִשְׁתַּדֵּל בַּפָּסוּק הַזֶּה, (דברים כא) וְלָקְחוּ זִקְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגוֹ' וְעָרְפוּ שָׁם אֶת הָעֶגְלָה בַּנָּחַל. וְהַדִּין הוּא בְּסַכִּין לַעֲרֹף אוֹתָהּ. אָמַר לוֹ רַבִּי אֶלְעָזָר, לָמָּה צָרִיךְ אֶת זֶה.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, אוֹי לָעוֹלָם שֶׁנִּמְשָׁךְ אַחַר זֶה, שֶׁהֲרֵי מֵאוֹתוֹ הַיּוֹם שֶׁאוֹתוֹ הַנָּחָשׁ הָרָע הִתְפַּתָּה בּוֹ אָדָם, שׁוֹלֵט עַל הָאָדָם וְשׁוֹלֵט עַל בְּנֵי הָעוֹלָם, הוּא עוֹמֵד לְהַסְטוֹת אֶת הָעוֹלָם, וְהָעוֹלָם לֹא יָכוֹל לָצֵאת מֵעָנְשׁוֹ עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ וְיָקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְשֵׁנֵי הֶעָפָר, שֶׁכָּתוּב (ישעיה כא) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ', וְכָתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְהוּא עוֹמֵד עַל עוֹלָם זֶה לִטֹּל אֶת כָּל נִשְׁמוֹת בְּנֵי הָאָדָם.</p>\n<p>וּבֹא וּרְאֵה, הֲרֵי כָּתוּב (דברים כא) כִּי יִמָּצֵא חָלָל וְגוֹ'. בּא רְאֵה, כָּל בְּנֵי הָעוֹלָם נִשְׁמָתָם יוֹצֵאת עַל יְדֵי מַלְאַךְ הַמָּוֶת. אִם תֹּאמַר שֶׁבֶּן אָדָם הַזֶּה יָצְאָה נִשְׁמָתוֹ עַל יְדֵי אוֹתוֹ מַלְאַךְ הַמָּוֶת - לֹא כָּךְ! אֶלָּא מִי שֶׁהוֹרֵג אוֹתוֹ, הוֹצִיא אֶת נִשְׁמָתוֹ בְּטֶרֶם הִגִּיעַ זְמַנּוֹ שֶׁיִּשְׁלֹט בּוֹ אוֹתוֹ מַלְאַךְ הַמָּוֶת.</p>\n<p>וְלָכֵן וְלָאָרֶץ לֹא יְכֻפַּר וְגוֹ'. וְלָאָרֶץ שֶׁלָּנוּ. וְלֹא דַי לָהֶם שֶׁעוֹמֵד הוּא לְהַסְטוֹת הָעוֹלָם לְחִנָּם וּלְקַטְרֵג תָּמִיד, כָּל שֶׁכֵּן שֶׁגּוֹזְלִים מִמֶּנּוּ מַה שֶּׁיֵּשׁ לוֹ לָקַחַת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל בָּנָיו, וְלָכֵן מַקְרִיבִים אֶת הָעֶגְלָה הַזּוֹ, כְּדֵי לְתַקֵּן עִמּוֹ מַה שֶּׁנִּלְקְחָה אוֹתָהּ נְשָׁמָה שֶׁל הָאָדָם מִמֶּנּוּ, וְלֹא יִמָּצֵא מְקַטְרֵג עַל (ד\"א הקרובים בזה) הָעוֹלָם.</p>\n<p>וְסוֹד עֶלְיוֹן שָׁנִינוּ כָּאן. שׁוֹר, פָּרָה, עֵגֶל, עֶגְלָה - כֻּלָּם בְּסוֹד עֶלְיוֹן נִמְצָאִים, וְלָכֵן בָּזֶה מְתַקְּנִים אוֹתוֹ, וְזֶהוּ שֶׁכָּתוּב (דברים כא) יָדֵינוּ לֹא שָׁפְכֻה אֶת הַדָּם הַזֶּה וְגוֹ'. לֹא שָׁפְכוּ וְלֹא גָרַמְנוּ מִיתָתוֹ. וּבָזֶה לֹא נִמְצָא עֲלֵיהֶם מְקַטְרֵג, וּבַכֹּל נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא עֵצָה לָעוֹלָם.</p>"],[9522011241,"<p>בֹּא רְאֵה, כְּמוֹ זֶה בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, שֶׁנִּמְצָא הַדִּין בָּעוֹלָם, הוּא עוֹמֵד לְקַטְרֵג, וְיִשְׂרָאֵל צְרִיכִים לְהִתְעוֹרֵר בַּשּׁוֹפָר וּלְעוֹרֵר קוֹל שֶׁכָּלוּל בְּאֵ\"שׁ וּמַיִ\"ם רוּ\"חַ וְנַעֲשִׂים אֶחָד, וּלְהַשְׁמִיעַ אוֹתוֹ קוֹל מִתּוֹךְ הַשּׁוֹפָר.</p>\n<p>וְאוֹתוֹ קוֹל עוֹלֶה עַד מָקוֹם שֶׁיּוֹשֵׁב כִּסֵּא הַדִּין וּמַכֶּה בּוֹ וְעוֹלֶה. כֵּיוָן שֶׁמַּגִּיעַ הַקּוֹל הַזֶּה מִלְּמַטָּה, הַקּוֹל שֶׁל יַעֲקֹב נִתְקָן לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר רַחֲמִים. שֶׁהֲרֵי כְּמוֹ שֶׁיִּשְׂרָאֵל מְעוֹרְרִים לְמַטָּה קוֹל אֶחָד כָּלוּל בְּאֵ\"שׁ וְרוּ\"חַ מַיִ\"ם שֶׁיּוֹצְאִים כְּאֶחָד מִתּוֹךְ הַשּׁוֹפָר, כָּךְ גַּם מִתְעוֹרֵר לְמַעְלָה שׁוֹפָר. וְאוֹתוֹ קוֹל שֶׁכָּלוּל בְּאֵ\"שׁ וּמַיִ\"ם רוּ\"חַ נִתְקָן, וְיוֹצֵא זֶה מִלְּמַטָּה וְזֶה מִלְמַעְלָה, וְנִתְקָן הָעוֹלָם וְנִמְצָאִים הָרַחֲמִים.</p>\n<p>וְאוֹתוֹ מְקַטְרֵג מִתְעַרְבֵּב, שֶׁחוֹשֵׁב לִשְׁלֹט בַּדִּין וּלְקַטְרֵג בָּעוֹלָם, וְרוֹאֶה שֶׁמִּתְעוֹרְרִים רַחֲמִים. אָז מִתְעַרְבֵּב וְתָשׁ כֹּחוֹ וְלֹא יָכוֹל לַעֲשׂוֹת דָּבָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם בְּרַחֲמִים. שֶׁאִם תֹּאמַר שֶׁנַּעֲשֶׂה דִין - לֹא כָּךְ! אֶלָּא מִתְחַבְּרִים רַחֲמִים עִם דִּין, וְהָעוֹלָם נִדּוֹן בְּרַחֲמִים.</p>\n<p>בֹּא רְאֵה, כָּתוּב (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ, שֶׁהַלְּבָנָה מִתְכַּסָּה, שֶׁהֲרֵי אָז שׁוֹלֵט הַנָּחָשׁ הָרָע וְיָכוֹל לְהַזִּיק לָעוֹלָם. וּכְשֶׁמִּתְעוֹרְרִים רַחֲמִים, עוֹלָה הַלְּבָנָה וּמָעֳבֶרֶת מִשָּׁם, וְהוּא מִתְעַרְבֵּב וְלֹא יָכוֹל לִשְׁלֹט, וְעוֹבֵר שֶׁלֹּא יִתְקָרֵב לְשָׁם, וְלָכֵן בְּרֹאשׁ הַשָּׁנָה צָרִיךְ לְעַרְבֵּב אוֹתוֹ כְּמִי שֶׁמִּתְעוֹרֵר מִשְּׁנָתוֹ וְלֹא יוֹדֵעַ כְּלוּם.</p>\n<p>בְּיוֹם הַכִּפּוּרִים צָרִיךְ לָנוּחַ וְלַעֲשׂוֹת לוֹ נַחַת רוּחַ בַּשָּׂעִיר שֶׁמַּקְרִיבִים לוֹ, וְאָז מִתְהַפֵּךְ לְסָנֵגוֹר עַל יִשְׂרָאֵל, אֲבָל בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה מִתְעַרְבֵּב, שֶׁלֹּא יוֹדֵעַ וְלֹא יָכוֹל לַעֲשׂוֹת כְּלוּם. רוֹאֶה הִתְעוֹרְרוּת שֶׁל הָרַחֲמִים עוֹלִים מִלְּמַטָּה וְרַחֲמִים מִלְמַעְלָה וְהלְּבָנָה עוֹלָה בֵּינֵיהֶם, אָז הוּא מִתְעַרְבֵּב וְלֹא יוֹדֵעַ כְּלוּם וְלֹא יָכוֹל לִשְׁלֹט.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא דָּן אֶת יִשְׂרָאֵל בְּרַחֲמִים וְחָס עֲלֵיהֶם וּמוֹצֵא לָהֶם זְמַן כָּל אוֹתָם עֲשָׂרָה יָמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים לְקַבֵּל אֶת כָּל אוֹתָם הַשָּׁבִים לְפָנָיו וּלְכַפֵּר לָהֶם מֵחֲטָאֵיהֶם וּמַעֲלֶה אוֹתָם לְיוֹם הַכִּפּוּרִים.</p>\n<p>וְעַל זֶה בַּכֹּל מְצַוֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לַעֲשׂוֹת מַעֲשֶׂה, כְּדֵי שֶׁלֹּא יִשְׁלֹט עֲלֵיהֶם מִי שֶׁלֹּא צָרִיךְ וְלֹא יִשְׁלֹט עֲלֵיהֶם הַדִּין וְיִהְיוּ כֻלָּם צַדִּיקִים בָּאָרֶץ כְּאַהֲבַת הָאָב עַל הַבָּנִים (בני אדם), וְהַכֹּל תָּלוּי בְּמַעֲשֶׂה וּבְדִבּוּרִים, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים.</p>"],[9522011242,"<p>וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. רַבִּי יוֹחָנָן פָּתַח בְּפָסוּק זֶה, (שיר ז) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן מֶלֶךְ אָסוּר בָּרְהָטִים. עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא שַׁלִּיטִים לְמַעְלָה וְשַׁלִּיטִים לַטָּה. כְּשֶׁנּוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלָה לְשָׂרִים שֶׁל מַעְלָה, נוֹטְלִים מַעֲלָה הַמְּלָכִים שֶׁל מַטָּה. נָתַן מַעֲלָה לְשָׂרוֹ שֶׁל בָּבֶל - נָטַל מַעֲלָה נְבוּכַדְנֶצַּר הָרָשָׁע, שֶׁכָּתוּב בּוֹ (דניאל ב) אַתָּה הוּא רֹאשׁ הַזָּהָב. וְהָיוּ כָּל הָעוֹלָם מְשֻׁעְבָּדִים תַּחַת יָדוֹ וּבְנוֹ וּבֶן בְּנוֹ. זֶהוּ שֶׁכָּתוּב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. זֶהוּ נְבוּכַדְנֶצַּר. זֶהוּ שֶׁכָּתוּב (שם ד) תַּחְתָּיו תִּצְלַל חַיַּת הַשָּׂדֶה. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן - זֶהוּ בֶּלְשַׁצַּר שֶׁאָמַר (שם ה) יִלְבַּשׁ אַרְגָּמָן. מֶלֶךְ אָסוּר בָּרְהָטִים - זֶהוּ אֱוִיל מְרֹדַךְ שֶׁהָיָה אָסוּר עַד שֶׁמֵּת אָבִיו נְבוּכַדְנֶצַּר וּמָלַךְ תַּחְתָּיו.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לָמָּה בָּא טַעַם זֶה בְּשִׁיר הַשִּׁירִים? אֶלָּא, אָמַר רַבִּי יְהוּדָה, שִׁבְעָה דְבָרִים נִבְרְאוּ קֹדֶם שֶׁנִּבְרָא הָעוֹלָם, וְאֵלּוּ הֵן וְכוּ', כִּסֵּא הַכָּבוֹד - שֶׁנֶּאֱמַר (תהלים צג) נָכוֹן כִּסְאֲךְ מֵאָז מֵעוֹלָם אָתָּה, וְכָתוּב (ירמיה יז) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן. שֶׁהוּא הָיָה רֹאשׁ הַנִּקְדַּם לַכֹּל, וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּשָׁמָה הַטְּהוֹרָה מִכִּסֵּא הַכָּבוֹד לִהְיוֹת מְאִירָה לַגּוּף. זֶהוּ שֶׁכָּתוּב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. זֶהוּ כִּסֵּא הַכָּבוֹד שֶׁהוּא רֹאשׁ עַל הַכֹּל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן - זוֹ הִיא הַנְּשָׁמָה הַנִּטֶּלֶת מִמֶּנּוּ. מֶלֶךְ אָסוּר בָּרְהָטִים - זֶהוּ הַגּוּף שֶׁהוּא אָסוּר בַּקֶּבֶר וְכָלֶה בֶּעָפָר וְלֹא נִשְׁאָר מִמֶּנּוּ אֶלָּא כִּמְלֹא תַרְוָד רֶקֶב, וּמִמֶּנּוּ יִבָּנֶה כָּל הַגּוּף. וּכְשֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַגּוּף, הוּא אוֹמֵר לָאָרֶץ שֶׁתַּפְלִיט אוֹתוֹ לַחוּץ, שֶׁכָּתוּב (ישעיה כו) וָאָרֶץ רְפָאִים תַּפִּיל.</p>\n<p>אָמַר רַבִּי יוֹחָנָן, הַמֵּתִים שֶׁבָּאָרֶץ הֵם חַיִּים תְּחִלָּה, זֶהוּ שֶׁכָּתוּב (שם) יִחְיוּ מֵתֶיךְ. נְבֵלָתִי יְקוּמוּן - אֵלּוּ שֶׁבְּחוּצָה לָאָרֶץ. הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר - אֵלּוּ הַמֵּתִים שֶׁבַּמִּדְבָּר. שֶׁאָמַר רַבִּי יוֹחָנָן, לָמָּה מֵת מֹשֶׁה בְּחוּצָה לָאָרֶץ? לְהַרְאוֹת לְכָל בָּאֵי עוֹלָם, כְּשֵׁם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת לְמֹשֶׁה, כָּךְ עָתִיד לְהַחֲיוֹת לְדוֹרוֹ, (למה)? שֶׁהֵם קִבְּלוּ הַתּוֹרָה. (שאמר רבי יוחנן) וַעֲלֵיהֶם נֶאֱמַר (ירמיה ב) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר בְּאֶרֶץ לֹא זְרוּעָה.</p>\n<p>דָּבָר אַחֵר הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר - אֵלּוּ הֵם הָאָבוֹת. וְהַמֵּתִים בְּחוּצָה לָאָרֶץ יִבָּנֶה גוּפָם וּמִתְגַּלְגְּלִים תַּחַת הָאָרֶץ עַד אֶרֶץ יִשְׂרָאֵל, וְשָׁם יְקַבְּלוּ נִשְׁמָתָם, וְלֹא בְּחוּצָה לָאָרֶץ. זֶהוּ שֶׁכָּתוּב (יחזקאל לז) לָכֵן הִנָּבֵא וְאָמַרְתָּ אֲלֵיהֶם (וגו'), הִנֵּה אֲנִי פֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. מַה כָּתוּב אַחֲרָיו? וְנָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם.</p>\n<p>רַבִּי פִּנְחָס אָמַר, הַנְּשָׁמָה נִטְּלָה מִכִּסֵּא הַכָּבוֹד שֶׁהוּא הָרֹאשׁ, כְּמוֹ שֶׁנֶּאֱמַר (שיר ז) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן - זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא דַּלַּת הָרֹאשׁ. מֶלֶךְ אָסוּר בָּרְהָטִים - הוּא הַגּוּף שֶׁהוּא אָסוּר בַּקְּבָרִים. זֶהוּ הַגּוּף, וְזֶהוּ שָׂרָה, וְזֶהוּ מֶלֶךְ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹקְדָהּ לַמּוֹעֵד אֲשֶׁר דִּבֵּר אֵלָיו. זֶהוּ שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. פּוֹקֵד אֶת הַגּוּף לַזְּמַן הַיָּדוּעַ שֶׁבּוֹ יִפְקֹד הַצַּדִּיקִים.</p>\n<p>אָמַר רַבִּי פִּנְחָס, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַפּוֹת לְגוּף הַצַּדִּיקִים לֶעָתִיד לָבֹא כַּיֹּפִי שֶׁל אָדָם הָרִאשׁוֹן כְּשֶׁנִּכְנַס לְגַן עֵדֶן, שֶׁנֶּאֱמַר (ישעיה נח) וְנָחֲךְ ה' תָּמִיד וְגוֹ' וְהָיִיתָ כְּגַן רָוֶה. אָמַר רַבִּי לֵוִי, הַנְּשָׁמָה בְּעוֹדָהּ בְּמַעֲלָתָהּ, נִזּוֹנֵית בְּאוֹר שֶׁל מַעְלָה וּמִתְלַבֶּשֶׁת בּוֹ, וּכְשֶׁתִּכָּנֵס (ונשתרש) לַגּוּף לֶעָתִיד לָבא - בְּאוֹתוֹ הָאוֹר מַמָּשׁ תִּכָּנֵס, וַאֲזַי הַגּוּף יָאִיר כְּזֹהַר הָרָקִיעַ. זֶהוּ שֶׁכָּתוּב (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. וְיַשִּׂיגוּ בְּנֵי אָדָם דֵּעָה שְׁלֵמָה, שֶׁנֶּאֱמַר (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה'. מִנַּיִן לָנוּ זֶה? מִמַּה שֶּׁכָּתוּב וְנָחֲךְ ה' תָּמִיד וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. זֶה אוֹר שֶׁל מַעְלָה. וְעַצְמֹתֶיךָ יַחֲלִיץ - זֶה פְּקִידַת הַגּוּף. וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו - זֶהוּ דַּעַת הַבּוֹרֵא יִתְבָּרַךְ. וַאֲזַי יֵדְעוּ הַבְּרִיּוֹת שֶׁהַנְּשָׁמָה הַנִּכְנֶסֶת בָּהֶם, שֶׁהִיא נִשְׁמַת הַחַיִּים, נִשְׁמַת הַתַּעֲנוּגִים, שֶׁהִיא קִבְּלָה הַתַּעֲנוּגִים מִלְמַעְלָה וּמְעַדֶּנֶת לַגּוּף, וְהַכֹּל תְּמֵהִים בָּהּ וְאוֹמְרִים (שיר ז) מַה יָּפִית וּמַה נָּעַמְתְּ אַהֲבָה בַּתַּעֲנוּגִים. זוֹ הִיא הַנְּשָׁמָה לֶעָתִיד לָבֹא.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁכָּתוּב (שם) מֶלֶךְ אָסוּר בָּרְהָטִים, וְכָתוּב אַחֲרָיו מַה יָּפִית וּמַה נָּעַמְתְּ. וְאָמַר רַבִּי יְהוּדָה, בְּאוֹתוֹ זְמַן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ עוֹלָמוֹ וְלִשְׂמֹחַ בִּבְרִיּוֹתָיו, שֶׁנֶּאֱמַר (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו. וַאֲזַי יִהְיֶה שְׂחוֹק בָּעוֹלָם מַה שֶּׁאֵין כֵּן עַכְשָׁו, שֶׁכָּתוּב (שם קכו) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וְגוֹ'. זֶהוּ שֶׁכָּתוּב וַתֹּאמֶר שָׂרָה צְחֹק עָשָׂה לִי אֱלֹהִים, שֶׁאֲזַי עֲתִידִים בְּנֵי אָדָם לוֹמַר שִׁירָה, שֶׁהוּא עֵת שְׂחוֹק. רַבִּי אַבָּא אָמַר, הַיּוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו, לֹא הָיְתָה שִׂמְחָה כְּמוֹתָהּ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְהַצַּדִּיקִים הַנִּשְׁאָרִים בִּירוּשָׁלַיִם לֹא יָשׁוּבוּ עוֹד לַעֲפָרָם, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ. הַנּוֹתָר בְּצִיּוֹן וּבִירוּשָׁלַיִם דַּוְקָא.</p>\n<p>אָמַר רַבִּי אָחָא, אִם כֵּן מְעַטִּים הֵם. אֶלָּא כָּל אוֹתָם שֶׁנִּשְׁאֲרוּ בְּאֶרֶץ יִשְׂרָאֵל הַקְּדוֹשָׁה דִּינָם כִּירוּשָׁלַיִם וּכְצִיּוֹן לְכָל דָּבָר. מְלַמֵּד שֶׁכָּל אֶרֶץ יִשְׂרָאֵל בִּכְלַל יְרוּשָׁלַיִם הִיא, מִמַּשְׁמָע שֶׁכָּתוּב (ויקרא יט) וְכִי תָבאוּ אֶל הָאָרֶץ. הַכֹּל בַּכְּלָל. רַבִּי יְהוּדָה בְּרַבִּי אֶלְעָזָר שָׁאַל לְרַבִּי חִזְקִיָּה. אָמַר לוֹ, מֵתִים שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹתָם, לָמָּה לֹא נָתַן נִשְׁמָתָם בְּמָקוֹם שֶׁנִּקְבְּרוּ שָׁם, וְיָבאוּ לְהֵחָיוֹת בְּאֶרֶץ יִשְׂרָאֵל? אָמַר לוֹ, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת יְרוּשָׁלַיִם, וְשֶׁלֹּא תֵהָרֵס לְעוֹלָמִים. שֶׁאָמַר רַבִּי יִרְמְיָה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵּשׁ עוֹלָמוֹ וְלִבְנוֹת יְרוּשָׁלַיִם וּלְהוֹרִידָהּ בְּנוּיָה מִלְמַעְלָה (בנין) כְּדֵי שֶׁלֹּא יֵהָרֵס, וְנִשְׁבַּע שֶׁלֹּא תִגְלֶה עוֹד כְּנֶסֶת יִשְׂרָאֵל, וְנִשְׁבַּע שֶׁלֹּא יֵהָרֵס בִּנְיַן יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר (ישעיה סב) לֹא יֵאָמֵר לָךְ עוֹד עֲזוּבָה וּלְאַרְצֵךְ לֹא יֵאָמֵר עוֹד שְׁמָמָה.</p>\n<p>וּבְכָל מָקוֹם שֶׁאַתָּה מוֹצֵא לֹא לֹא - הִיא שְׁבוּעָה. זֶהוּ שֶׁכָּתוּב (בראשית ט) וְלֹא יִכָּרֵת כָּל בָּשָׂר עוֹד מִמֵּי הַמַּבּוּל וְלֹא יִהְיֶה עוֹד מַבּוּל וְגוֹ', וְכָתוּב (ישעיה נד) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ. מִכָּאן שֶׁלֹּא לֹא - שְׁבוּעָה. וּמִן לָאו אַתָּה שׁוֹמֵעַ הֵן. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַיֵּם עוֹלָמוֹ קִיּוּם שֶׁלֹּא תִגְלֶה כְּנֶסֶת יִשְׂרָאֵל וְלֹא יֵהָרֵס בִּנְיַן בֵּית הַמִּקְדָּשׁ, לְפִיכָךְ אֵין מְקַבְּלִים נִשְׁמָתָם אֶלָּא בְּמָקוֹם קַיָּם לְעוֹלָמִים, כְּדֵי שֶׁתִּהְיֶה הַנְּשָׁמָה קַיֶּמֶת בַּגּוּף לְעוֹלָמִים. וְזֶה הוּא שֶׁכָּתוּב הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, מִכָּאן (מקרא הוא) הוּא קָדוֹשׁ, יְרוּשָׁלַיִם קָדוֹשׁ, הַנּוֹתָר בָּהּ קָדוֹשׁ. הוּא קָדוֹשׁ - שֶׁכָּתוּב (ישעיה ו) קָדוֹשׁ ה' צְבָאוֹת, וְכָתוּב (הושע יא) בְּקִרְבְּךְ קָדוֹשׁ. יְרוּשָׁלַיִם קָדוֹשׁ - שֶׁכָּתוּב (קהלת ח) וּמִמְּקוֹם קָדוֹשׁ יְהַלֵּכוּ. הַנּוֹתָר בָּהּ קָדוֹשׁ - שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ. מַה קָּדוֹשׁ הָרִאשׁוֹן קַיָּם - אַף הַשְּׁאָר קָדוֹשׁ קָדוֹשׁ קַיָּם.</p>\n<p>אָמַר רַבִּי יִצְחָק, מַה זֶּה שֶׁכָּתוּב (זכריה ח) עֹד יֵשְׁבוּ זְקֵנִים וּזְקֵנוֹת בִּרְחֹבוֹת יְרוּשָׁלם וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרֹב יָמִים? מַה טּוֹבָה הִיא זוֹ (כדי) לָלֶכֶת אָז שֶׁכָּתוּב וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ? אֶלָּא, אָמַר רַבִּי יִצְחָק, עֲתִידִים הַצַּדִּיקִים לֶעָתִיד לָבֹא לְהַחֲיוֹת מֵתִים כֶּאֱלִישָׁע הַנָּבִיא, שֶׁכָּתוּב (מלכים ב ד) וְקַח מִשְׁעַנְתִּי בְיָדְךְ וָלֵךְ, וְכָתוּב וְשַׂמְתָּ מִשְׁעַנְתִּי עַל פְּנֵי הַנָּעַר. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: דָּבָר שֶׁעֲתִידִים לַעֲשׂוֹת הַצַּדִּיקִים לֶעָתִיד לָבֹא אַתָּה רוֹצֶה לַעֲשׂוֹת עַכְשָׁו לַעֲשׂוֹת? מַה כָּתוּב? וַיָּשֶׂם אֶת הַמִּשְׁעֶנֶת עַל פְּנֵי הַנַּעַר וְאֵין קוֹל וְאֵין עוֹנֶה וְאֵין קָשֶׁב. אֲבָל הַצַּדִּיקִים לֶעָתִיד לָבֹא עָלָה בְיָדָם הַבְטָחָה זוֹ, שֶׁכָּתוּב (זכריה ח) וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ, כְּדֵי לְהַחֲיוֹת בּוֹ אֶת הַמֵּתִים. (מי הם המתים)? אוֹתָם מֵהַגֵּרִים שֶׁנִּתְגַּיְּרוּ מֵאֻמּוֹת הָעוֹלָם, שֶׁכָּתוּב בָּהֶם (ישעיה סה) כִּי הַנַּעַר בֶּן מֵאָה שָׁנָה יָמוּת וְהַחוֹטֶא בֶּן מֵאָה שָׁנָה יְקֻלָּל. אָמַר רַבִּי יִצְחָק, סוֹף הַפָּסוּק מוֹכִיח, שֶׁכָּתוּב מֵרֹב יָמִים.</p>\n<p>דָּבָר אַחֵר וַתֹּאמֶר שָׂרָה צְחֹק עָשָׂה לִי אֱלֹהִים, כָּתוּב (ישעיה סו) שִׂמְחוּ אֶת יְרוּשָׁלם וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ. אָמַר רַבִּי יְהוּדָה, לֹא הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם כְּאוֹתָהּ שִׂמְחָה שֶׁעָתִיד לִשְׂמֹחַ עִם הַצַּדִּיקִים לֶעָתִיד לָבא, וְכָל אֶחָד מַרְאֶה בָּאֶצְבַּע וְאוֹמֵר, (שם כה) הִנֵּה אֱלֹהֵינוּ זֶה קִוִּינוּ לוֹ וְיוֹשִׁיעֵנוּ זֶה ה' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ, וְכָתוּב (שם יב) זַמְּרוּ ה' כִּי גֵאוּת עָשָׂה מוּדַעַת זאת בְּכָל הָאָרֶץ.</p>\n<p>רַבִּי יוֹחָנָן אָמַר, לֹא רָאִינוּ מִי שֶׁפֵּרַשׁ אֶת הַדָּבָר הַזֶּה כְּדָוִד הַמֶּלֶךְ שֶׁאָמַר (תהלים קד) תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן וְגוֹ'. מִכָּאן שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה רָעָה לְשׁוּם אָדָם, אֶלָּא כְּשֶׁאֵינוֹ מַשְׁגִּיחַ בּוֹ - הוּא כָּלֶה מֵאֵלָיו, שֶׁכָּתוּב תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן תֹּסֵף רוּחָם יִגְוָעוּן וְגוֹ', וְאַחַר כָּךְ (שם) תְּשַׁלַּח רוּחֲךְ יִבָּרֵאוּן וְגוֹ', וְאַחַר כָּךְ (שם) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו. וַאֲזַי הַשְּׂחוֹק בָּעוֹלָם, שֶׁכָּתוּב (שם קכו) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וּלְשׁוֹנֵנוּ רִנָּה. זֶהוּ שֶׁכָּתוּב וַתֹּאמֶר שָׂרָה צְחֹק עָשָׂה לִי אֱלֹהִים, לִשְׂמֹחַ בִּישׁוּעָתוֹ.</p>\n<p>רַבִּי חִיָּיא אָמַר, בֹּא רְאֵה, עַד שֶׁהַגּוּף עוֹמֵד בָּעוֹלָם הַזֶּה, הוּא חָסֵר מִן הַתַּשְׁלוּם. לְאַחַר שֶׁהוּא צַדִּיק וְהוֹלֵךְ בְּדַרְכֵי יֹשֶׁר וּמֵת בְּיָשְׁרוֹ, נִקְרָא שָׂרָה בְּתַשְׁלוּמוֹ. הִגִּיעַ לִתְחִיַּת הַמֵּתִים, הוּא שָׂרָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁאַחֵר הוּא שֶׁהֶחֱיָה הַקָּדוֹשׁ בָּרוּךְ הוּא. לְאַחַר שֶׁהוּא חַי וְשָׂמֵחַ עִם הַשְּׁכִינָה וּמַעֲבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא הַיָּגוֹן מִן הָעוֹלָם, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ', אֲזַי נִקְרָא יִצְחָק בִּשְׁבִיל הַצְּחוֹק וְהַשִּׂמְחָה שֶׁיִּהְיֶה לַצַּדִּיקִים לֶעָתִיד לָבֹא.</p>\n<p>רַבִּי יְהוּדָה בָּא לְאוֹתוֹ מָקוֹם שֶׁל כְּפַר חָנָן. שָׁלְחוּ לוֹ מִנְחָה כָּל בְּנֵי הָעִיר. נִכְנַס לְפָנָיו רַבִּי אַבָּא, אָמַר לוֹ, מָתַי הוֹלֵךְ מַר? אָמַר לוֹ, אֶפְרַע מַה שֶּׁנָּתְנוּ לִי בְּנֵי הָעִיר וְאֵלֵךְ. אָמַר לוֹ, אַל יַחְשֹׁשׁ מַר לַמִּנְחָה הַ את. לַתּוֹרָה הֵם עָשׂוּ אֶת זֶה, וְלֹא יְקַבְּלוּ מִמְּךְ כְּלוּם. אָמַר לוֹ, וְלֹא יְקַבְּלוּ דִּבְרֵי תוֹרָה? אָמַר כֵּן. בָּאוּ כָּל בְּנֵי הָעִיר. אָמַר לוֹ רַבִּי יְהוּדָה, כֻּלָּם רָאשֵׁי יְשִׁיבוֹת. אָמַר לוֹ, וְאִם יֵשׁ מִי שֶׁלֹּא נָאֶה לוֹ לָשֶׁבֶת כָּאן - שֶׁיָּקוּם וְיֵלֵךְ. קָם רַבִּי אַבָּא וְהִבְדִּיל מֵהֶם עֲשָׂרָה שֶׁיְּקַבְּלוּ מִמֶּנּוּ. אָמַר לָהֶם, שְׁבוּ עִם הָאִישׁ הַגָּדוֹל הַזֶּה, וַאֲנִי וְהֵם נְקַבֵּל לְמָחָר וְנֵשֵׁב עִמּוֹ. הָלְכוּ. וְאוֹתָם עֲשָׂרָה שֶׁיָּשְׁבוּ עִמּוֹ יָשְׁבוּ (אותם עשרה) וְלֹא אָמַר כְּלוּם. אָמְרוּ לוֹ, אִם רְצוֹנוֹ שֶׁל מַר, נְקַבֵּל פְּנֵי שְׁכִינָה. אָמַר לָהֶם, וַהֲרֵי רַבִּי אַבָּא אֵינוֹ כָּאן. שָׁלְחוּ לוֹ וּבָא.</p>\n<p>פָּתַח וְאָמַר, וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמַר, מָה הַשִּׁנּוּי שֶׁהָיָה כָּאן? הָיָה לוֹ לוֹמַר, וַה' זָכַר אֶת שָׂרָה, כְּמוֹ שֶׁאָמַר (בראשית ל) וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל, שֶׁאֵין פְּקִידָה אֶלָּא עַל מַה שֶּׁהָיָה בַּתְּחִלָּה. אֶלָּא בַּהַתְחָלָה הָיָה, שֶׁכָּתוּב שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה, וְעַל אוֹתוֹ עִנְיָן נֶאֱמַר שֶׁפָּקַד עַכְשָׁו, מַשְׁמָע שֶׁכָּתוּב כַּאֲשֶׁר אָמָר. שֶׁאִלְמָלֵא לֹא נֶאֱמַר כַּאֲשֶׁר אָמָר, שֶׁיֹּאמַר זְכִירָה. אֲבָל פָּקַד - אוֹתוֹ דָּבָר שֶׁאָמַר לַמּוֹעֵד אָשׁוּב אֵלֶיךְ.</p>\n<p>אַחַר כָּךְ אָמַר כָּךְ, צַדִּיק זֶה שֶׁזּוֹכֶה לַעֲלוֹת לְאוֹתוֹ כָּבוֹד עֶלְיוֹן, דְּמוּתוֹ נֶחְקֶקֶת בְּכִסֵּא כְבוֹדוֹ, וְכֵן לְכָל צַדִּיק וְצַדִּיק דְּמוּתוֹ לְמַעְלָה כְּמוֹ שֶׁהָיָה לְמַטָּה לְהַבְטִיחַ לְאוֹתָהּ נְשָׁמָה קְדוֹשָׁה.</p>\n<p>וְזְהִוּ שֶׁאָמַר רַבִּי יוֹחָנָן, מַה זֶּה שֶׁכָּתוּב (חבקוק ג) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה? שֶׁזּוֹהֲרִים גּוּף וּנְשָׁמָה שֶׁעוֹמְדִים בַּגֹּרֶן הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁלְּמַעְלָה כִּדְמוּת שֶׁהָיָה עוֹמֵד בָּאָרֶץ, וְאוֹתָהּ דְּמוּת נִזּוֹנֵית הֲנָאַת הַנְּשָׁמָה, וְאוֹתָהּ הָעֲתִידָה לְהִתְלַבֵּשׁ בָּעֶצֶם הַזּוֹ שֶׁנִּשְׁאֲרָה בָּאָרֶץ, וְהָאֲדָמָה תַּעֲבֹר מִמֶּנָּה וְטוֹפֶלֶת אֶת הַזֻּהֲמָה הַחוּצָה, וְזֶהוּ שֶׁנִּקְרָא קְדֻשָּׁה.</p>\n<p>וּכְשֶׁעוֹמֶדֶת אוֹתָהּ הַדְּמוּת הַהִיא שֶׁלְּמַעְלָה, בָּאָה בְּכָל חֹדֶשׁ לְהִשְׁתַּחֲווֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ. וְהוּא מְבַשֵּׂר לוֹ וְאוֹמֵר, לַמּוֹעֵד אָשׁוּב אֵלֶיךְ. לְאוֹתוֹ זְמַן שֶׁעָתִיד לְהַחֲיוֹת מֵתִים עַד שֶׁתִּפָּקֵד לְאוֹתוֹ זְמַן כְּמוֹ שֶׁהִתְבַּשְּׂרָה. זֶהוּ שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. וְאוֹתוֹ יוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשָׂיו, זֶהוּ שֶׁכָּתוּב (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, יֹאמַר לָנוּ מַר עַל הַפָּרָשָׁה שֶׁאַחַר כָּךְ. אָמַר, יָפֶה לָכֶם לִפְתֹּחַ פָּרָשָׁה זוֹ. פָּתַח וְאָמַר, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וְגוֹ', וַיֹּאמֶר קַח נָא אֶת בִּנְךְ אֶת יְחִידְךְ אֲשֶׁר אָהַבְתָּ וְגוֹ'. כָּאן יֵשׁ לְהִתְבּוֹנֵן, הָאֻמָּן הַזֶּה שֶׁמּוֹצִיא כֶסֶף מִמְּקוֹר הָאָרֶץ, מָה עוֹשֶׂה. בַּתְּחִלָּה? מַכְנִיס אוֹתוֹ לְאֵשׁ דּוֹלֶקֶת עַד שֶׁמּוֹצִיא מִמֶּנּוּ אֶת כָּל הַזֻּהֲמָה שֶׁל הָאָרֶץ, וַהֲרֵי נִשְׁאָר כֶּסֶף, אֲבָל לֹא כֶּסֶף שָׁלֵם. אַחַר כָּךְ מָה עוֹשֶׂה? מַכְנִיס אוֹתוֹ בָּאֵשׁ כְּבַתְּחִלָּה וּמוֹצִיא מִמֶּנּוּ סִיגִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי כה) הָגוֹ סִיגִים מִכֶּסֶף וְגוֹ', וְאָז הוּא כֶּסֶף שָׁלֵם לְלֹא עִרְבּוּבְיָה.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס אֶת הַגּוּף הַזֶּה תַּחַת הָאָרֶץ, עַד שֶׁכֻּלּוֹ נִרְקָב וְיָצְאָה מִמֶּנּוּ כָּל הַזֻּהֲמָה הָרָעָה, וְנִשְׁאָר אוֹתוֹ תַּרְוַד רֶקֶב וְנִבְנֶה מִמֶּנּוּ הַגּוּף, וְעַד עַכְשָׁו הוּא גוּף לֹא שָׁלֵם.</p>\n<p>אַחַר אוֹתוֹ יוֹם הַגָּדוֹל, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לָיְלָה, מֻסְתָּרִים כֻּלָּם בֶּעָפָר כְּמוֹ בַּתְּחִלָּה מִלִּפְנֵי פַּחַד וְהַחֹזֶק שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיה ב) וּבָאוּ בִּמְעָרוֹת צֻרִים וּבִמְחִלּוֹת עָפָר מִפְּנֵי פַּחַד ה' וּמֵהֲדַר גְּאוֹנוֹ וְגוֹ'. וְיָצָא נִשְׁמָתָם וּמִתְעַכֵּל אוֹתוֹ תַּרְוַד רֶקֶב, וְנִשְׁאָר גּוּף שֶׁנִּבְנָה שָׁם (האור) שֶׁלּוֹ כְּאוֹר הַשֶּׁמֶשׁ וּכְזהַר הָרָקִיעַ, שֶׁכָּתוּב (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזהַר הָרָקִיעַ וְגוֹ', וְאָז כֶּסֶף שָׁלֵם, גּוּף שָׁלֵם בְּלִי עִרְבּוּבְיָה אַחֶרֶת.</p>\n<p>שֶׁאָמַר רַבִּי יַעֲקֹב, גּוּף שֶׁמֵּאִיר יִזְרֹק הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְמַעְלָה, שֶׁכָּתוּב (ישעיה כו) כִּי טַל אוֹרוֹת טַלֶּךְ, וְכָתוּב (שם כב) הִנֵּה ה' מְטַלְטֶלְךְ וְגוֹ'. וְאָז יִקָּרְאוּ קְדוֹשִׁים עֶלְיוֹנִים, שֶׁכָּתוּב (שם ד) קָדוֹשׁ יֵאָמֶר לוֹ. וְזֶהוּ שֶׁנִּקְרָא תְּחִיַּת הַמֵּתִים שֶׁל הַסּוֹף, וְזֶהוּ (כסף שלם גוף שלם) (נסיון) אַחֲרוֹן, וְלֹא יִטְעֲמוּ עוֹד טַעַם הַמָּוֶת, שֶׁכָּתוּב בִּי נִשְׁבַּעְתִּי נְאֻם ה' כִּי יַעַן אֲשֶׁר עָשִׂיתָ וְגוֹ' כִּי בָרֵךְ אֲבָרֶכְךְ וְגוֹ'. וּבְאוֹתוֹ זְמַן מִתְפַּלְלִים הַצַּדִּיקִים שֶׁלֹּא יִתְנַסּוּ בָזֶה יוֹתֵר.</p>\n<p>מַה כָּתוּב? וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל וְגוֹ'. אֵלּוּ שְׁאָר רִשְׁעֵי הָעוֹלָם שֶׁנִּקְרְאוּ אֵילִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) אֵילֵי נְבָיוֹת יְשָׁרְתוּנֶךְ, וּמְתַרְגְּמִים: גְּדוֹלֵי נְבָיוֹת. אַחַר נֶאֱחַז בַּסְּבַךְ וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר וְכָל קַרְנֵי רְשָׁעִים אֲגַדֵּעַ. וַיֵּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל וְגוֹ', שֶׁהֵם מְזֻמָּנִים לְהִתְנַסּוֹת בְּכָל נִסָּיוֹן רַע, וְיִשָּׁאֲרוּ הַצַּדִּיקִים לָעוֹלָם הַבָּא כְּמוֹ מַלְאָכִים עֶלְיוֹנִים קְדוֹשִׁים לְיַחֵד אֶת שְׁמוֹ, וְלָכֵן כָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד וְגוֹ'.</p>\n<p>אָמַר לוֹ (אמר להם) רַבִּי יְהוּדָה, מִכָּאן וָהָלְאָה פִּתְחוּ הַפֶּתַח. נִכְנַס יוֹם אַחֵר, וְנִכְנְסוּ לְפָנָיו כָּל בְּנֵי הָעִיר. אָמְרוּ לוֹ, יֹאמַר לָנוּ מַר דִּבְרֵי תוֹרָה בַּפָּרָשָׁה שֶׁקָּרִינוּ בָהּ בְּיוֹם שַׁבָּת, וַה' פָּקַד אֶת שָׂרָה. קָּם בֵּין הָעַמּוּדִים, פָּתַח וְאָמַר, וַה' פָּקַד אֶת שָׂרָה וְגוֹ'. שְׁלֹשָׁה מַפְתְּחוֹת בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מְסָרָם לֹא בְּיַד מַלְאָךְ וְלֹא בְּיַד שָׂרָף: מַפְתֵּחַ שֶׁל חַיָּה, וְשֶׁל גְּשָׁמִים, וְשֶׁל תְּחִיַּת הַמֵּתִים. בָּא אֵלִיָּהוּ וְנָטַל הַשְּׁנַיִם - שֶׁל גְּשָׁמִים וְשֶׁל תְּחִיַּת הַמֵּתִים. וְאָמַר רַבִּי יוֹחָנָן, לֹא נִמְסַר בְּיַד אֵלִיָּהוּ אֶלָּא אַחַת. שֶׁאָמַר רַבִּי יוֹחָנָן, כְּשֶׁבִּקֵּשׁ אֵלִיָּהוּ לְהַחֲיוֹת בֶּן הַצָּרְפִית, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: לֹא נָאֶה לְךְ לָקַחַת בְּיָדְךְ שְׁנֵי מַפְתְּחוֹת, אֶלָּא תֵּן לִי מַפְתֵּחַ הַגְּשָׁמִים, וּתְחַיֶּה הַמֵּת. וְהַיְנוּ שֶׁכָּתוּב (מלכים א יח) לֵךְ הֵרָאֵה אֶל אַחְאָב וְגוֹ' וְאֶתְּנָה מָטָר. לֹא אָמַר וְתֵן מָטָר, אֶלָּא וְאֶתְּנָה.</p>\n<p>וַהֲרֵי אֱלִישָׁע הָיוּ לוֹ? כֵּן. לְקַיֵּם פִּי שְׁנַיִם בְּרוּחוֹ שֶׁל אֵלִיָּהוּ. אֶלָּא שְׁלָשְׁתָּם לֹא מְסָרָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיַד שָׁלִיחַ. שֶׁאָמַר רַבִּי סִימוֹן, בֹּא רְאֵה כֹּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא: בְּפַעַם אַחַת מְחַיֵּה מֵתִים וּמוֹרִיד שְׁאוֹל וַיָּעַל, מַזְרִיחַ מְאוֹרוֹת וּמוֹרִיד גְּשָׁמִים, מַצְמִיחַ חָצִיר, מְדַשֵּׁן יְבוּלִים, פּוֹקֵד עֲקָרוֹת, נוֹתֵן פַּרְנָסוֹת, עוֹזֵר דַּלִּים, סוֹמֵךְ נוֹפְלִים, זוֹקֵף כְּפוּפִים, מַעֲבִיר מְלָכִים וּמֵקִים מְלָכִים, וְהַכֹּל בִּזְמַן אֶחָד וּבְרֶגַע אֶחָד וּבְבַת אַחַת מַה שֶּׁאֵין שָׁלִיחַ לְעוֹלָם יָכוֹל לַעֲשׂוֹתוֹ.</p>\n<p>שָׁנִינוּ בַּבָּרַיְתָא, אָמַר רַבִּי יוֹסֵי, כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינוֹ צָרִיךְ לַעֲשׂוֹת אֶלָּא בְּדִבּוּר. שֶׁכֵּיוָן שֶׁאָמַר מִמְּקוֹם קְדֻשָּׁתוֹ יְהֵא כָּךְ - מִיָּד נַעֲשָׂה. בֹּא רְאֵה כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. שֶׁאָמַר רַבִּי יוֹחָנָן (יהודה), מַה זֶּה שֶׁכָּתוּב (שמות יב) וְעָבַרְתִּי בְּאֶרֶץ מִצְרַיִם אֲנִי וְלֹא מַלְאָךְ וְגוֹ'?</p>\n<p>אִם כָּךְ, כָּבוֹד גָּדוֹל הוּא לְמִצְרַיִם, שֶׁלֹּא דוֹמֶה מִי שֶׁתָּפַס מֶלֶךְ לְמִי שֶׁתָּפַס הֶדְיוֹט. וְעוֹד, אֵין לְךְ אֻמָּה מְזֹהֶמֶת בְּכָל טֻמְאָה כְּמוֹ הַמִּצְרִים, שֶׁכָּתוּב בָּהֶם (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְגוֹ', שֶׁהֵם חֲשׁוּדִים עַל מִשְׁכַּב זָכוּר, וְהֵם בָּאִים מֵחָם שֶׁעָשָׂה מַה שֶּׁעָשָׂה לְאָבִיו, וְקִלֵּל אוֹתוֹ וְלִכְנַעַן בְּנוֹ. וְכִי לֹא הָיָה לַקָּבָּ\"ה מַלְאָךְ אוֹ שָׁלִיחַ לְשַׁגֵּר לַעֲשׂוֹת נְקָמָה בְּמִצְרַיִם כְּמוֹ שֶׁעָשָׂה בְּאַשּׁוּר שֶׁהָיָה בְּנוֹ שֶׁל שֵׁם, שֶׁכָּתוּב (בראשית י) וּבְנֵי שֵׁם עֵילָם וְאַשּׁוּר. וְשֵׁם הָיָה כֹּהֵן גָּדוֹל וְנִתְבָּרֵךְ, שֶׁנֶּאֱמַר (שם ט) בָּרוּךְ ה' אֱלֹהֵי שֵׁם, וְהָיָה לְשֵׁם הַגְּדֻלָּה וְהַבְּרָכָה עַל אֶחָיו, וְכָתוּב בָּם (ישעיה לז) וַיֵּצֵא מַלְאַךְ ה' וַיַּכֶּה בְּמַחֲנֵה אַשּׁוּר, וְעַל יְדֵי שָׁלִיחַ נַעֲשָׂה. כָּל שֶׁכֵּן הַמִּצְרִים שֶׁהֵם מְזהָמִים יוֹתֵר מִכָּל אֻמָּה, וְאָמַר אֲנִי וְלֹא מַלְאָךְ.</p>\n<p>אֶלָּא,? אָמַר רַבִּי יְהוּדָה, מִכָּאן לָמַדְנוּ כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַעֲלָתוֹ שֶׁהוּא גָבוֹהַּ מֵעַל הַכֹּל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֻמָּה זוֹ שֶׁל מִצְרַיִם מְזֹהֶמֶת וּמְטֻנֶּפֶת, וְאֵין רָאוּי לְשַׁגֵּר מַלְאָךְ וְלֹא שָׂרָף, דָּבָר קָדוֹשׁ בֵּין רְשָׁעִים אֲרוּרִים מְטֻנָּפִים, אֶלָּא אֲנִי עוֹשֶׂה מַה שֶּׁאֵין יָכוֹל לַעֲשׂוֹת מַלְאָךְ וְלֹא שָׂרָף וְלֹא שָׁלִיחַ. שֶׁאֲנִי אוֹמֵר מִמְּקוֹם קְדֻשָּׁתִי יְהֵא כָּךְ - וּמִיָּד נַעֲשֶׂה, מַה שֶּׁאֵין הַמַּלְאָךְ יָכוֹל לַעֲשׂוֹתוֹ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מִמְּקוֹם קְדֻשָּׁתוֹ אוֹמֵר יְהֵא כָּךְ - וּמִיָּד נַעֲשֶׂה מַה שֶּׁהוּא רוֹצֶה לַעֲשׂוֹת. וּלְפִיכָךְ לֹא נַעֲשֵׂית נְקָמָה זוֹ עַל יְדֵי מַלְאָךְ וְשָׁלִיחַ, בִּשְׁבִיל קְלוֹן הַמִּצְרִים, וּלְהַרְאוֹת גְּדֻלָּתוֹ שֶׁל מָקוֹם שֶׁלֹּא רָצָה שֶׁיִּכָּנְסוּ בֵינֵיהֶם דָּבָר קָדוֹשׁ. וְעַל הַדֶּרֶךְ הַזֶּה נֶאֱמַר אֲנִי וְלֹא מַלְאָךְ. אֲנִי יָכוֹל לַעֲשׂוֹתוֹ, וְלֹא מַלְאָךְ.</p>\n<p>כַּיּוֹצֵא בּוֹ אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (יונה ב) וַיֹּאמֶר ה' לַדָּג? וְכַמָּה צַדִּיקִים וַחֲסִידִים מִיִּשְׂרָאֵל שֶׁלֹּא דִבֵּר עִמָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָא לְדַבֵּר עִם הַדָּג דָּבָר שֶׁאֵינוֹ מַכִּיר וְיוֹדֵעַ!? אֶלָּא, אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁעָלְתָה תְפִלָּתוֹ שֶׁל יוֹנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמְּקוֹם קְדֻשָּׁתוֹ אָמַר בִּשְׁבִיל שֶׁיָּקִיא הַדָּג אֶת יוֹנָה אֶל הַיַּבָּשָׁה. לָמֶ\"ד לַ'דָּג כְּמוֹ בִּשְׁבִיל. כְּלוֹמַר, וַיּאמֶר ה' בִּשְׁבִיל הַדָּג שֶׁיָּקִיא אֶת יוֹנָה אֶל הַיַּבָּשָׁה. מִמְּקוֹם קְדֻשָּׁתוֹ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא יְהֵא כָּךְ - וּמִיָּד נַעֲשָׂה, מַה שֶּׁאֵין שָׁלִיחַ יָכוֹל לַעֲשׂוֹתוֹ.</p>\n<p>שָׁנִינוּ בַּבָּרַיְתָא, אָמַר רַבִּי שִׁמְעוֹן, מַפְתֵּחַ שֶׁל חַיָּה בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא, וּבְעוֹד שֶׁהִיא יוֹשֶׁבֶת עַל הַמַּשְׁבֵּר, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּן בְּאוֹתוֹ הַוָּלָד. אִם רָאוּי הוּא לָצֵאת לָעוֹלָם - (יוצא, ו) פוֹתֵחַ דַּלְתוֹת בִּטְנָהּ וְיוֹצֵא. וְאִם לָאו - סוֹגֵר דַּלְתוֹתֶיהָ וּמֵתוּ שְׁנֵיהֶם. אִם כָּךְ, לֹא יֵצֵא רָשָׁע לְעוֹלָם? אֶלָּא כָּךְ שָׁנִינוּ, עַל שָׁלֹשׁ עֲבֵרוֹת נָשִׁים מֵתוֹת וְכוּ', (אמר רבי שמעון והרי) וְאָמַר רַבִּי יִצְחָק, לָמָּה אִשָּׁה מַפֶּלֶת פְּרִי בִטְנָהּ. אֶלָּא,? אָמַר רַבִּי יִצְחָק, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אוֹתוֹ הָעֻבָּר שֶׁאֵינוֹ רָאוּי לָצֵאת לָעוֹלָם, וּמַקְדִּים לַהֲמִיתוֹ בִּמְעֵי אִמּוֹ, שֶׁנֶּאֱמַר (בראשית ו) הַנְּפִלִים הָיוּ בָאָרֶץ בַּיָּמִים הָהֵם. הַנְּפִלִים כָּתוּב בְּלֹא יוֹ\"ד רִאשׁוֹנָה, וְלָמָּה? בִּשְׁבִיל שֶׁאַחֲרֵי כֵן בָּאוּ בְּנֵי הָאֱלֹהִים אֶל בְּנוֹת הָאָדָם וְיָלְדוּ לָהֶם בִּזְנוּת וַיִּרְבּוּ מַמְזֵרִים בָּעוֹלָם.</p>\n<p>הֵמָּה הַגִּבֹּרִים אֲשֶׁר מֵעוֹלָם - שֶׁאֵין גִּבּוֹר וּפָרִיץ וְעָרִיץ כְּמוֹ הַמַּמְזֵר. אַנְשֵׁי הַשֵּׁם - שֶׁהַכֹּל יַכִּירוּ לִקְרוֹת הַשֵּׁם הַיָּדוּעַ מַמְזֵר. שֶׁכֵּיוָן שֶׁרוֹאִים מַעֲשָׂיו שֶׁהוּא פָּרִיץ וְעָרִיץ וְגִבּוֹר, הַכֹּל יִקְרָאוּהוּ אוֹתוֹ שֵׁם. וּמַה שֶּׁאָמַר רַבִּי שִׁמְעוֹן, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּן בְּאוֹתוֹ הַוָּלָד - אֵין לְךְ רָשָׁע בָּעוֹלָם מֵאוֹתָם הָרְשָׁעִים הַיּוֹצְאִים לָעוֹלָם שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּן בּוֹ וְרוֹאֶה אִם אוֹתוֹ הַגּוּף יַנִּיחַ בֵּן צַדִּיק וְכָשֵׁר, אוֹ שֶׁיַּצִּיל לְאָדָם מִיִּשְׂרָאֵל מִמִּיתָה מְשֻׁנָּה, אוֹ שֶׁיַּעֲשֶׂה טוֹבָה אַחַת, וּבִשְׁבִיל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיאוֹ לָעוֹלָם.</p>\n<p>בִּימֵי רַבִּי יוֹסֵי הָיוּ אוֹתָם פָּרִיצִים שֶׁהָיוּ שׁוֹדְדִים בֶּהָרִים עִם פָּרִיצֵי אֻמּוֹת הָעוֹלָם, וּכְשֶׁמּוֹצְאים בֶּן אָדָם וְתוֹפְסִים אוֹתוֹ לְהָרְגוֹ, הָיוּ אוֹמְרִים לוֹ: מַה שִּׁמְךְ? אִם הָיָה יְהוּדִי - הָיוּ הוֹלְכִים עִמּוֹ וּמוֹצִיאִים אוֹתוֹ מִן הֶהָרִים, וְאִם הָיָה אִישׁ אַחֵר - הוֹרְגִים אוֹתוֹ. (והרי) וְהָיָה אוֹמֵר רַבִּי יוֹסֵי, רְאוּיִים אֵלּוּ בְּכָל זֶה לְהִכָּנֵס לָעוֹלָם הַבָּא.</p>\n<p>שָׁנוּ רַבּוֹתֵינוּ, שְׁלֹשָׁה דְבָרִים הַלָּלוּ אֵינָם בָּאִים לָעוֹלָם אֶלָּא בְקוֹלוֹת: קוֹל חַיָּה, שֶׁכָּתוּב (בראשית ג) בְּעֶצֶב תֵּלְדִי בָנִים, וְכָתוּב (שם ל) וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים. קוֹל גְּשָׁמִים, שֶׁכָּתוּב (תהלים כט) קוֹל ה' עַל הַמָּיִם, וְכָתוּב (מלכים א יח) כִּי קוֹל הֲמוֹן הַגָּשֶׁם. קוֹל תְּחִיַּת הַמֵּתִים, שֶׁכָּתוּב (ישעיה מ) קוֹל קוֹרֵא בַּמִּדְבָּר. מַה צָּרִיךְ כָּאן קוֹל בַּמִּדְבָּר אֶלָּא,? אָמַר רַבִּי זְרִיקָא, אֵלּוּ אוֹתָם קוֹלוֹת לְעוֹרֵר מֵתֵי מִדְבָּר. וּמִכָּאן שֶׁהוּא הַדִּין לְכָל הָעוֹלָם. אָמַר רַבִּי יוֹחָנָן, הֲרֵי שָׁנִינוּ, כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר, נִכְנַס בְּקוֹלוֹת. כְּשֶׁיָּקוּמוּ בִּתְחִיַּת הַמֵּתִים אֵינוֹ דִין שֶׁיָּקוּמוּ בְּקוֹלֵי קוֹלוֹת?</p>\n<p>אָמַר רַבִּי יַעֲקֹב, עֲתִידָה בַּת קוֹל לִהְיוֹת מִתְפּוֹצֶצֶת בְּבָתֵּי קְבָרוֹת וְאוֹמֶרֶת: (ישעיה כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר. וַעֲתִידִים לִחְיוֹת בְּטַל שֶׁל אוֹר גָּדוֹל שֶׁל מַעְלָה, שֶׁכָּתוּב (שם) כִּי טַל אוֹרוֹת טַלֶּךְ וָאָרֶץ רְפָאִים תַּפִּיל. אָמֵן כֵּן יְהִי רָצוֹן. עד כאן מדרש הנעלם.</p>\n<p>וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר, שֶׁכָּתוּב לַמּוֹעֵד אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וּלְשָׂרָה בֵן. וְשָׁנִינוּ, פָּקַד אֶת שָׂרָה - פְּקִידָה לִנְקֵבָה, זְכִירָה לְזָכָר. וּמִשּׁוּם כָּךְ וַה' פָּקַד אֶת שָׂרָה. כַּאֲשֶׁר אָמָר, שֶׁכָּתוּב שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וְגוֹ'. מִכָּאן מַשְׁמָע שֶׁאָמַר וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ, וַיֹּאמֶר סְתָם, שֶׁהוּא הָיָה וְלֹא שָׁלִיחַ אַחֵר.</p>"],[9522011243,"<p>וַיַּעַשׂ ה' לְשָׂרָה וְגוֹ'. כֵּיוָן שֶׁאָמַר וַה' פָּקַד אֶת שָׂרָה, מַהוּ וַיַּעַשׂ ה' לְשָׂרָה? אֶלָּא כָּךְ שָׁנִינוּ, שֶׁפְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן הוּא, וְהוּא נִשְׁמוֹת הַצַּדִּיקִים, וְהוּא הַמַּזָּל שֶׁכָּל הַבְּרָכוֹת הַטּוֹבוֹת וְגִשְׁמֵי בְרָכָה נוֹזְלִים מִמֶּנּוּ וּמִשָּׁם יוֹצְאִים, שֶׁכָּתוּב לְהַשְׁקוֹת אֶת הַגָּן. שֶׁהוּא מַזִּיל וּמַשְׁקֶה מִלְמַעְלָה לְמַטָּה מִשּׁוּם שֶׁבָּנִים בַּמַּזָּל הַזֶּה תְּלוּיִים, וְלֹא בְמָקוֹם אַחֵר. וְעַל זֶה כָּתוּב וַה' פָּקַד אֶת שָׂרָה, פְּקִידָה בִּלְבַדָּהּ.</p>\n<p>וַיַּעַשׂ ה' לְשָׂרָה, עֲשִׂיָּה הִיא לְמַעְלָה מִן הַדַּרְגָּה הַזּוֹ, כְּמוֹ שֶׁנֶּאֱמַר שֶׁבְּמַזָּל זֶה תָּלוּי, וְעַל זֶה כָּאן פְּקִידָה וְכָאן עֲשִׂיָּה. וְלָכֵן אָמַר ה' וַה', וְהַכֹּל אֶחָד.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים קכז) הִנֵּה נַחֲלַת ה' בָּנִים שָׂכָר פְּרִי הַבָּטֶן. הִנֵּה נַחֲלַת ה', חֵלֶק לְהֵאָחֵז בַּה' שֶׁלֹּא יִתְבַּטֵּל מִמֶּנָּה לְעוֹלָמִים. שֶׁבֶּן אָדָם שֶׁזּוֹכֶה לְבָנִים בָּעוֹלָם הַזֶּה, זוֹכֶה בָהֶם לְהִכָּנֵס לַפַּרְגּוֹד לָעוֹלָם הַבָּא, מִשּׁוּם שֶׁאוֹתוֹ הַבֵּן שֶׁהִשְׁאִיר בֶּן הָאָדָם וְזוֹכֶה בּוֹ בָּעוֹלָם הַזֶּה, הוּא יְזַכֶּה אוֹתוֹ לָעוֹלָם הַבָּא, וְזוֹכֶה לְהִכָּנֵס בּוֹ לְנַחֲלַת ה'. מַה זֶּה נַחֲלַת ה'? זוֹ אֶרֶץ הַחַיִּים. וְכָךְ קָרָא לָהּ אֶת אֶרֶץ יִשְׂרָאֵל, שֶׁהִיא אֶרֶץ הַחַיִּים.</p>\n<p>דָּוִד הַמֶּלֶךְ (קרא לה) נַחֲלַת ה', שֶׁכָּתוּב (שמואל א כו) כִּי גֵרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת ה' לֵאמֹר לֵךְ עֲבֹד אֱלֹהִים אֲחֵרִים, וּמִשּׁוּם כָּךְ הִנֵּה נַחֲלַת ה' בָּנִים. מִי מְזַכֶּה אֶת הָאִישׁ הַזֶּה? בָּנִים. אִם זוֹכֶה בָהֶם בָּעוֹלָם הַזֶּה - שָׂכָר פְּרִי הַבָּטֶן. שָׂכָר וְחֵלֶק טוֹב בְּאוֹתוֹ עוֹלָם בְּאוֹתוֹ פְּרִי מֵעָיו הוּא שֶׁזּוֹכֶה בֶּן אָדָם בְּאוֹתוֹ עוֹלָם בָּהֶם.</p>\n<p>בֹּא רְאֵה, הִנֵּה נַחֲלַת ה' בָּנִים, יְרֻשָּׁה וְחֵלֶק שֶׁל פֵּרוֹת שֶׁל מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְמַעְלָה הוּא מֵעֵץ הַחַיִּים, שֶׁהֲרֵי מִשָּׁם זוֹכֶה בֶּן אָדָם לְבָנִים, כְּמוֹ שֶׁנֶּאֱמַר (הושע יד) מִמֶּנִּי פֶּרְיְךְ נִמְצָא. מַה כָּתוּב? (תהלים קכז) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לֹא יֵבֹשׁוּ וְגוֹ'. אַשְׁרֵי בָּעוֹלָם הַזֶּה, וְאַשְׁרֵי בָּעוֹלָם הַבָּא.</p>\n<p>לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר, מִי הָאוֹיְבִים בַּשַּׁעַר? אֵלּוּ בַּעֲלֵי הַדִּינִים. שֶׁכַּאֲשֶׁר נְשָׁמָה יוֹצֵאת מֵהָעוֹלָם הַזֶּה, כַּמָּה הֵם בַּעֲלֵי הַדִּינִים שֶׁמְּזֻמָּנִים לְפָנֶיהָ עַד שֶׁלֹּא תִכָּנֵס לַמָּקוֹם בַּשַּׁעַר בְּאוֹתוֹ שַׁעַר שֶׁתִּכָּנֵס לְשָׁם, מִשּׁוּם שֶׁהִשְׁאִיר מַשְׁכּוֹנוֹת בָּעוֹלָם הַזֶּה וּבִגְלָלָם יִזְכֶּה בְּאוֹתוֹ עוֹלָם. וְעַל זֶה לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי יוֹסִי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יוֹסִי, פְּתַח פִּיךְ וְדַבֵּר בַּתּוֹרָה, שֶׁהֲרֵי הַשְּׁכִינָה נִמְצֵאת אֶצְלְךְ, שֶׁבְּכָל זְמַן שֶׁבְּדִבְרֵי תוֹרָה מְדַבְּרִים, בָּאָה הַשְּׁכִינָה וּמִתְחַבֶּרֶת, וְכָל שֶׁכֵּן בַּדֶּרֶךְ, שֶׁשְּׁכִינָה מַקְדִּימָה וּבָאָה וְהוֹלֶכֶת לִפְנֵי בְּנֵי אָדָם שֶׁזּוֹכִים בֶּאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011244,"<p>פָּתַח רַבִּי יוֹסִי וְאָמַר, (שם) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךְ. אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה - כָּל זְמַן שֶׁהָאִשָּׁה בְּיַרְכְּתֵי הַבַּיִת וְלֹא יוֹצֵאת הַחוּצָה, הִיא צְנוּעָה וּרְאוּיָה לְהוֹלִיד בָּנִים כְּשֵׁרִים. כְּגֶפֶן - מַה גֶּפֶן לֹא נִנְטַעַת אֶלָּא בְּמִינָהּ וְלֹא בְּמִין אַחֵר, כָּךְ אִשָּׁה כְּשֵׁרָה לֹא תַעֲשֶׂה נְטִיעוֹת עִם אִישׁ אַחֵר; מַה גֶּפֶן אֵין בָּהּ הַרְכָּבָה מֵעֵץ אַחֵר, אַף כָּךְ אִשָּׁה כְּשֵׁרָה גַּם כָּךְ.</p>\n<p>רְאֵה מַה שְּׂכָרָהּ: בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים. מַה זֵּיתִים אֵין עֲלֵיהֶם נוֹפְלִים כָּל יְמוֹת הַשָּׁנָה וְכֻלָּם קְשׁוּרִים (בסר) תָּמִיד, אַף כָּךְ בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךְ.</p>\n<p>מַה כָּתוּב אַחֲרָיו? הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר יְרֵא ה'. מַה זֶּה הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר? הִנֵּה כֵן הָיָה צָרִיךְ (לכתב) ! אֶלָּא לְרַבּוֹת דָּבָר אַחֵר שֶׁלָּמַדְנוּ זֶה מִמֶּנָּה, שֶׁכָּל זְמַן שֶׁהַשְּׁכִינָה הָיְתָה צְנוּעָה בִּמְקוֹמָהּ כָּרָאוּי לָהּ כִּבְיָכוֹל - בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים, אֵלּוּ יִשְׂרָאֵל כְּשֶׁשְּׁרוּיִים בָּאָרֶץ. סָבִיב לְשֻׁלְחָנֶךְ - שֶׁאוֹכְלִים וְשׁוֹתִים וּמַקְרִיבִים קָרְבָּנוֹת וּשְׂמֵחִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים בִּגְלָלָם.</p>\n<p>אַחַר שֶׁיָּצְאָה הַשְּׁכִינָה וְגָלוּ יִשְׂרָאֵל מֵעַל שֻׁלְחַן אֲבִיהֶם, וְהֵם בֵּין הָעַמִּים וְצוֹוְחִים כָּל יוֹם, וְאֵין מִי שֶׁיַּשְׁגִּיחַ בָּהֶם פְּרָט לַקָּבָּ\"ה, שֶׁכָּתוּב (ויקרא כו) וְאַף גַּם זאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'. וְרָאִינוּ כַּמָּה קְדוֹשִׁים עֶלְיוֹנִים מֵתוּ בִּגְזֵרוֹת תַּקִּיפוֹת, וְכָל זֶה מִשּׁוּם עֹנֶשׁ הַתּוֹרָה שֶׁלֹּא קִיְּמוּ יִשְׂרָאֵל כְּשֶׁהָיוּ שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>רְאֵה מַה כָּתוּב, (דברים כח) תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה' אֱלֹהֶיךְ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כֹּל. פָּסוּק זֶה הוּא סוֹד. תַּחַת אֲשֶׁר לֹא עָבַדְתָּ בְּשִׂמְחָה, בִּזְמַן שֶׁכֹּהֲנִים הָיוּ מַקְרִיבִים קָרְבָּנוֹת וְעוֹלוֹת, וְזוֹ הִיא בְּשִׂמְחָה. וּבְטוּב לֵבָב - אֵלּוּ הַלְוִיִּם. מֵרֹב כֹּל - אֵלּוּ יִשְׂרָאֵל שֶׁהָיוּ אֶמְצָעִיִּים בֵּינֵיהֶם וְנָטְלוּ בְרָכוֹת מִכָּל הַצְּדָדִים,</p>\n<p>שֶׁכָּתוּב (ישעיה ט) הִרְבִּיתָ הַגּוֹי לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה. אֵלּוּ הַכֹּהֲנִים. שָׂמְחוּ לְפָנֶיךְ כְּשִׂמְחַת בַּקָּצִיר - אֵלּוּ יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ לָהֶם אֶת תְּבוּאַת הַשָּׂדֶה וְנוֹתְנִים מַעֲשֵׂר מִן הַכֹּל. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל - אֵלּוּ לְוִיִּם שֶׁנּוֹטְלִים מַעֲשֵׂר מִתּוֹךְ הַגֹּרֶן.</p>\n<p>דָּבָר אַחֵר הִרְבִּיתָ הַגּוֹי - אֵלּוּ יִשְׂרָאֵל שֶׁאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם כָּרָאוּי. לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה - זוֹהִי דַּרְגַּת הָרֹאשׁ הָעֶלְיוֹן שֶׁל אַבְרָהָם שֶׁנִּדְבַּק בָּהּ, שֶׁהוּא גָדוֹל, וְחֶדְוָה נִמְצֵאת בּוֹ.</p>\n<p>שָׂמְחוּ לְפָנֶיךְ - בְּשָׁעָה שֶׁעוֹלִים לְהִדָּבֵק בְּךְ. כְּשִׂמְחַת בַּקָּצִיר - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁשִּׂמְחַת הַקָּצִיר הִיא שֶׁלָּהּ. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל - כַּאֲשֶׁר יָגִילוּ אֵלּוּ שְׁאָר הַצְּבָאוֹת וְהַמֶּרְכָּבוֹת לְמַטָּה בִּזְמַן שֶׁמְּחַלְּקִים שָׁלָל וְטוֹרְפִים טֶרֶף בְּרֵאשִׁית הַכֹּל.</p>"],[9522011245,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים קיט) עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תוֹרָתֶךְ. מַה זֶּה עֵת לַעֲשׂוֹת לַה'? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, אֲבָל עֵת - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת עֵת, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טז) וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ. מַה זֶּה וְאַל יָבֹא בְכָל עֵת? כְּמוֹ שֶׁנֶּאֱמַר (משלי ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה. וְזֶהוּ (ויקרא י) וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה וְגוֹ'. מָה הַטַּעַם עֵת? מִשּׁוּם שֶׁיֵּשׁ לָהּ עֵת וּזְמַן לַכֹּל לְהִתְקָרֵב לִהְיוֹת מְאִירָה וּלְהִתְחַבֵּר כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ ה' עֵת רָצוֹן.</p>\n<p>לַעָשׂוֹת לַה', כְּמוֹ שֶׁכָּתוּב (שמואל ב ח) וַיַּעַשׂ דָּוִד שֵׁם. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כְּאִלּוּ עָשָׂה וְתִקֵּן אֶת הָעֵת הַזֹּאת לְחַבֵּר אוֹתָהּ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא (תפארת). וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁהֵפֵרוּ תוֹרָתֶךְ. שֶׁאִלּוּ לֹא הֵפֵרוּ תוֹרָתֶךְ, לֹא נִמְצָא פֵרוּד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִיִּשְׂרָאֵל לְעוֹלָמִים.</p>\n<p>אָמַר רַבִּי יוֹסִי, כְּמוֹ זֶה כָּתוּב (ישעיה ס) אֲנִי ה' בְּעִתָּהּ אֲחִישֶׁנָּה. מַהוּ בְּעִתָּהּ? בְּעֵת ה'. שֶׁתָּקוּם מִן הֶעָפָר, אָז אֲחִישֶׁנָּה.</p>\n<p>אָמַר רַבִּי יוֹסִי, וְעִם כָּל זֶה, יוֹם אֶחָד הִיא כְּנֶסֶת יִשְׂרָאֵל בְּתוֹךְ הֶעָפָר וְלֹא יוֹתֵר. אָמַר רַבִּי יְהוּדָה, כָּךְ אָמְרוּ, אֲבָל בֹּא רְאֵה הַסּוֹד שֶׁלָּמַדְנוּ. בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל גָּלְתָה מִמְּקוֹמָהּ, אָז אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ כִּבְיָכוֹל נִפְרְדוּ, שֶׁנִּפְרְדָה הֵ\"א מִן וָא\"ו, וּמִשּׁוּם שֶׁנִּפְרְדוּ מַה כָּתוּב? (תהלים לט) נֶאֱלַמְתִּי דוּמִיָּ\"ה, מִשּׁוּם שֶׁהִסְתַּלֵּק וָא\"ו מֵהֵ\"א וְקוֹל לֹא נִמְצָא, אָז הַדִּבּוּר נֶאֱלָם,</p>\n<p>וְלָכֵן הִיא שׁוֹכֶבֶת לֶעָפָר כָּל אוֹתוֹ הַיּוֹם הַזֶּה שֶׁל הֵ\"א. וּמִיהוּ? הָאֶלֶף הַחֲמִישִׁי. וְאַף עַל גַּב שֶׁהִקְדִּימָה בַּגָּלוּת עַד שֶׁלֹּא נִכְנָס אוֹתוֹ הָאֶלֶף הַחֲמִישִׁי, הַסּוֹד שֶׁל הֵ\"א.</p>\n<p>וּכְשֶׁיָּבֹא הָאֶלֶף הַשִּׁשִּׁי, שֶׁהוּא הַסּוֹד שֶׁל וָא\"ו, אָז וָא\"ו יָקִים אֶת הֵ\"א. בִּזְמַן שֵׁשׁ פְּעָמִים עֶשֶׂר שִׁשִּׁים נֶפֶשׁ, אָז שְׁלֵמוּת שֶׁל וָא\"ו עֶשֶׂר פְּעָמִים, וָא\"ו שֵׁשׁ פְּעָמִים עֶשֶׂר, (שוא\"ו) וָא\"ו עוֹלָה (בעשר) בְּי', וָא\"ו יוֹרֶדֶת בְּהֵ\"א.</p>\n<p>נִשְׁלֶמֶת וָא\"ו בְּתוֹךְ עֶשֶׂר שֵׁשׁ פְּעָמִים, אָז הֵם שִׁשִּׁים לַהֲקִימָהּ מֵהֶעָפָר. וּבְכָל שִׁשִּׁים וְשִׁשִּׁים מֵאוֹתוֹ הָאֶלֶף הַשִּׁשִּׁי מִתְחַזֶּקֶת הֵ\"א, וְעוֹלָה בְּדַרְגוֹתֶיהָ לְהִתְחַזֵּק. וּבְשֵׁשׁ מֵאוֹת שָׁנִים לָאֶלֶף הַשִּׁשִּׁי יִפָּתְחוּ שַׁעֲרֵי הַחָכְמָה לְמַעְלָה וּמַעְיָנוֹת שֶׁל חָכְמָה לְמַטָּה, וְיִתְתַּקֵּן הָעוֹלָם לְהִכָּנֵס לַשְּׁבִיעִי. כְּמוֹ בֶּן אָדָם שֶׁמְּתַקֵּן בְּיוֹם שִׁשִּׁי מִכְּשֶׁמַּעֲרִיב הַשֶּׁמֶשׁ לְהִכָּנֵס לְשַׁבָּת, אַף כָּךְ גַּם, וְסִימָן לַדָּבָר - (בראשית ז) בִּשְׁנַת שֵׁשׁ מֵאוֹת שָׁנָה לְחַיֵּי נֹחַ וְגוֹ' נִבְקְעוּ כָּל מַעְיְנוֹת תְּהוֹם רַבָּה.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסִי, כָּל זֶה זְמַן אָרֹךְ יוֹתֵר מִכְּפִי שֶׁבֵּאֲרוּהוּ הַחֲבֵרִים שֶׁהוּא יוֹם אֶחָד גָּלוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל וְלֹא יוֹתֵר, שֶׁכָּתוּב (איכה א) נְתָנַני שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. אָמַר לוֹ, כָּךְ לָמַדְתִּי מֵאָבִי בְּסוֹדוֹת הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ וּבַיָּמִים שֶׁל שְׁנוֹת הָעוֹלָם וּבַיָּמִים שֶׁל בְּרֵאשִׁית, וְהַכֹּל בְּסוֹד אֶחָד הוּא.</p>\n<p>וְאָז תֵּרָאֶה הַקֶּשֶׁת בִּגְוָנִים מְאִירִים כְּמוֹ אִשָּׁה שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ, שֶׁכָּתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ וְיָפֶה הוּא. וּרְאִיתִיהָ בִּגְוָנִים מְאִירִים כָּרָאוּי,</p>\n<p>וְאָז לִזְכֹּר בְּרִית עוֹלָם. מַה זֶּה בְּרִית עוֹלָם? זוֹ כְּנֶסֶת יִשְׂרָאֵל, וְיִתְחַבֵּר וָא\"ו עִם הֵ\"א וִיקִימָהּ מִן הֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ. זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא בְּרִית, כְּמוֹ שֶׁנֶּאֱמַר וְהָיְתָה לְאוֹת בְּרִית וְגוֹ'.</p>\n<p>אָז יִתְעוֹרֵר וָא\"ו אֶל הֵ\"א, אָז אוֹתוֹת עֶלְיוֹנִים יִתְעוֹרְרוּ בָעוֹלָם, וַעֲתִידִים בְּנֵי רְאוּבֵן לְעוֹרֵר קְרָבוֹת בְּכָל הָעוֹלָם, וּכְנֶסֶת יִשְׂרָאֵל יָקִים אוֹתָהּ מִן הֶעָפָר וְיִזְכֹּר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא,</p>\n<p>וְיִמָּצֵא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְלָהּ בְּתוֹךְ הַגָּלוּת כְּחֶשְׁבּוֹן וָא\"ו שֵׁשׁ פְּעָמִים י' (עשר). עֶשֶׂר פְּעָמִים שֵׁשׁ שָׁנִים, וְאָז תָּקוּם וְיִפָּקֵד הָעוֹלָם לַעֲשׂוֹת נְקָמוֹת. וּמִי שֶׁהוּא נָמוּךְ - יִגְבַּהּ.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסִי, יָפֶה אָמַרְתָּ, מִשּׁוּם שֶׁהוּא בְּתוֹךְ סוֹד הָאוֹתִיּוֹת וְאֵין לָנוּ לְעוֹרֵר חֶשְׁבּוֹן וְקִצִּים אֲחֵרִים, שֶׁהֲרֵי בְּסִפְרוֹ שֶׁל רַב יֵיבָא הַזָּקֵן מָצָאנוּ חֶשְׁבּוֹן זֶה, שֶׁכָּתוּב (ויקרא כו) אָז תִּרְצֶה הָאָרֶץ, וְהוּא הַסּוֹד שֶׁל וָא\"ו, שֶׁכָּתוּב (שם) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב, וְזֶהוּ וָא\"ו, הַכֹּל כְּאֶחָד. וְעַל זֶה אֶזְכֹּר. וְאַחַר כָּךְ וְהָאָרֶץ אֶזְכֹּר, זוֹ כְּנֶסֶת יִשְׂרָאֵל. תִּרְצֶה, תִּתְרַצֶּה הָאָרֶץ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אֲבָל יוֹם אֶחָד שֶׁאָמְרוּ הַחֲבֵרִים, וַדַּאי הַכֹּל גָּנוּז לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַכֹּל נִמְצָא בְּסוֹד הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהֲרֵי הַגָּלוּת בְּאוֹתָן הָאוֹתִיּוֹת גִּלָּה אוֹתָן רַבִּי יֵיסָא כָּאן, וְעַכְשָׁו בְּאוֹתָן הָאוֹתִיּוֹת הִתְגַּלּוּ וְגִלָּה אוֹתָן.</p>\n<p>אָמַר לוֹ, בּא רְאֵה שֶׁאֲפִלּוּ כְּשֶׁנִּפְקְדָה שָׂרָה, מִדַּרְגָּה הַזּוֹ לֹא פָקַד אוֹתָהּ, אֶלָּא בַּסּוֹד שֶׁל וָא\"ו, שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה וְגוֹ', מִשּׁוּם שֶׁהַכֹּל הוּא בַּסּוֹד שֶׁל וָא\"ו, וּבְהֵ\"א כּוֹלֵל הַכֹּל וּבוֹ מִתְגַּלֶּה הַכֹּל, מִשּׁוּם שֶׁכָּל דָּבָר נִסְתָּר הוּא מְגַלֶּה כָּל נִסְתָּר וְלֹא בָא מִישֶׁהוּ בְּגִלּוּי וִיגַלֶּה מַה שֶּׁהוּא נִסְתָּר.</p>\n<p>אָמַר רַבִּי יוֹסִי, כַּמָּה יֵשׁ לָנוּ לְהִמָּשֵׁךְ בְּתוֹךְ הַגָּלוּת עַד אוֹתוֹ הַזְּמַן, וְהַכֹּל תָּלָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁיָּשׁוּבוּ בִתְשׁוּבָה - אִם יִזְכּוּ וְאִם לֹא יִזְכּוּ, כְּמוֹ שֶׁנֶּאֱמַר בַּפָּסוּק הַזֶּה שֶׁכָּתוּב אֲנִי ה' בְּעִתָּהּ אֲחִישֶׁנָּה. זָכוּ - אֲחִישֶׁנָּה. לֹא זָכוּ - בְּעִתָּהּ.</p>\n<p>הָלְכוּ, בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי יוֹסִי, נִזְכַּרְתִּי עַכְשָׁו שֶׁבַּמָּקוֹם הַזֶּה יָשַׁבְתִּי יוֹם אֶחָד עִם אָבִי וְאָמַר לִי, בְּנִי, עָתִיד אַתָּה כְּשֶׁתַּגִּיעַ יָמֶיךְ לְשִׁשִּׁים שָׁנִים לִמְצֹא בַּמָּקוֹם הַזֶּה אוֹצָר שֶׁל חָכְמָה עֶלְיוֹנָה, וַהֲרֵי זָכִיתִי לְאוֹתָם הַיָּמִים וְלֹא מָצָאתִי, וְאֵינוֹ יוֹדֵעַ אִם הַדְּבָרִים הַלָּלוּ שֶׁאָמַרְנוּ אוֹ אוֹתָהּ הַחָכְמָה שֶׁהוּא אָמַר.</p>\n<p>וְאָמַר לִי, כְּשֶׁיַּגִּיעוּ הַשַׁלְהָבוֹת שֶׁל הָאֵשׁ לְתוֹךְ הָאֲוִיר שֶׁל יָדֶיךְ, יֹאבַד מִמְּךְ. אָמַרְתִּי לוֹ, אַבָּא, בַּמֶּה יָדַעְתָּ? אָמַר לִי, בְּאוֹתָן שְׁתֵּי צִפֳּרִים שֶׁעָבְרוּ עַל רֹאשְׁךְ יָדַעְתִּי.</p>\n<p>בֵּין כָּךְ נִפְרַד רַבִּי יוֹסִי וְנִכְנַס לְתוֹךְ מְעָרָה אַחַת, וּמָצָא סֵפֶר אֶחָד שֶׁהָיָה נָעוּץ בְּתוֹךְ נֶקֶב שֶׁל הַסֶּלַע בִּקְצֵה הַמְּעָרָה. יָצָא אִתּוֹ.</p>\n<p>כֵּיוָן שֶׁפָּתַח אוֹתוֹ, רָאָה שִׁבְעִים וּשְׁתַּיִם חִקּוּקֵי אוֹתִיּוֹת שֶׁנִּמְסְרוּ לְאָדָם הָרִאשׁוֹן, וּבָהֶם הָיָה יוֹדֵעַ כָּל הַחָכְמָה שֶׁל עֶלְיוֹנִים קְדוֹשִׁים וְכָל אוֹתָם שֶׁאַחַר הָרֵיחַיִם שֶׁמִּתְגַּלְגְּלִים אַחַר הַפָּרֹכֶת תּוֹךְ אוֹרוֹת עֶלְיוֹנִים וְכָל אוֹתָם דְּבָרִים שֶׁעֲתִידִים לָבֹא לָעוֹלָם עַד הַיּוֹם שֶׁיָּקוּם עָנָן בְּצַד מַעֲרָב וְיַחְשִׁיךְ אֶת הָעוֹלָם.</p>\n<p>קָרָא לְרַבִּי יְהוּדָה וְהִתְחִילוּ לִלְמֹד בְּאוֹתוֹ סֵפֶר. לֹא הִסְפִּיקוּ לִלְמֹד שְׁנַיִם אוֹ שְׁלֹשָׁה צְדָדִים שֶׁל אוֹתָן הָאוֹתִיּוֹת עַד שֶׁהָיוּ מִסְתַּכְּלִים בְּאוֹתָהּ חָכְמָה עֶלְיוֹנָה. כֵּיוָן שֶׁהִגִּיעוּ לִלְמֹד בְּסִתְרֵי הַסֵּפֶר וְדִבְּרוּ זֶה עִם זֶה, יָצָא שְׁבִיב שֶׁל אֵשׁ וּמַשָּׁב שֶׁל רוּחַ וְהִכָּה בִידֵיהֶם וְאָבַד מֵהֶם. בָּכָה רַבִּי יוֹסִי וְאָמַר, אוּלַי חַס וְחָלִילָה חֵטְא הוּא אֶצְלֵנוּ, אוֹ שֶׁאֵין אָנוּ זַכָּאִים לָדַעַת אוֹתוֹ.</p>\n<p>כְּשֶׁבָּאוּ אֶל רַבִּי שִׁמְעוֹן, סִפְּרוּ לוֹ הַמַּעֲשֶׂה הַזֶּה. אָמַר לָהֶם, אוּלַי בְּקֵץ הַמָּשִׁיחַ שֶׁל אוֹתָם אוֹתִיּוֹת הֱיִיתֶם עֲסוּקִים? אָמְרוּ לוֹ, אֶת זֶה לֹא יָדַעְנוּ, שֶׁהֲרֵי הַכֹּל נִשְׁכָּח מֵעִמָּנוּ. אָמַר לָהֶם רַבִּי שִׁמְעוֹן, שֶׁאֵין רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא בָּזֶה שֶׁיִּתְגַּלֶּה כָּל כָּךְ לָעוֹלָם, וּכְשֶׁיִּהְיֶה קָרוֹב לִימוֹת הַמָּשִׁיחַ, אֲפִלּוּ תִינוֹקוֹת שֶׁל הָעוֹלָם עֲתִידִים לִמְצֹא נִסְתָּרוֹת שֶׁל חָכְמָה וְלָדַעַת בּוֹ קִצִּים וְחֶשְׁבּוֹנוֹת, וּבְאוֹתוֹ זְמַן יִתְגַּלֶּה לַכֹּל. זֶהוּ שֶׁכָּתוּב (צפניה ג) כִּי אָז אֶהְפֹּךְ אֶל עַמִּים וְגוֹ'. מַה זֶּה אָז? בִּזְמַן שֶׁתָּקוּם כְּנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר וְיָקִים אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם ה' וּלְעָבְדוֹ שְׁכֶם אֶחָד.</p>\n<p>בֹּא רְאֵה, אַף עַל גַּב שֶׁכָּתוּב בְּאַבְרָהָם, וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, וְכָל מַסְעוֹתָיו הָיוּ לַדָּרוֹם וְנִקְשַׁר בּוֹ, לֹא עָלָה לִמְקוֹמוֹ כָּרָאוּי עַד שֶׁנּוֹלַד יִצְחָק. כֵּיוָן שֶׁנּוֹלַד יִצְחָק, הִתְעַלָּה לִמְקוֹמוֹ וְהִשְׁתַּתֵּף עִמּוֹ וְנִקְשְׁרוּ זֶה עִם זֶה.</p>\n<p>לָכֵן הוּא קָרָא לוֹ יִצְחָק וְלֹא אַחֵר, כְּדֵי לְשַׁתֵּף מַיִם עִם אֵשׁ, שֶׁכָּתוּב וַיִּקְרָא אַבְרָהָם אֶת שֶׁם בְּנוֹ הַנּוֹלַד לוֹ אֲשֶׁר יָלְדָה לּוֹ שָׂרָה יִצְחָק. מִי הַנּוֹלַד לוֹ? אֵשׁ מִמַּיִם.</p>"],[9522011246,"<p>וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית אֲשֶׁר יָלְדָה לְאַבְרָהָם מְצַחֵק. אָמַר רַבִּי חִיָּיא, מִיּוֹם שֶׁנּוֹלַד יִצְחָק וְהָיָה יִשְׁמָעֵאל בְּבֵית אַבְרָהָם, לֹא הִתְעַלָּה יִשְׁמָעֵאל בַּשֵּׁם. בְּמָקוֹם שֶׁזָּהָב שׁוֹרֶה, לֹא נִזְכָּר פְּסֹלֶת לְפָנָיו, וְלָכֵן אֶת בֶּן הָגָר הַמִּצְרִית, אִישׁ שֶׁלֹּא רָאוּי לְהִזָּכֵר לִפְנֵי יִצְחָק.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַתֵּרֶא שָׂרָה, בְּעַיִן שֶׁל קָלוֹן רָאֲתָה אוֹתוֹ שָׂרָה, שֶׁלֹּא רָאֲתָה אוֹתוֹ בְּעַיִן שֶׁהוּא בֶּן אַבְרָהָם, אֶלָּא שֶׁהוּא בֶּן הָגָר הַמִּצְרִית, וּמִשּׁום כָּךְ וַתֵּרֶא שָׂרָה. שֶׁרָאֲתָה שָׂרָה אוֹתוֹ בְּעַיִן זוֹ וְלֹא אַבְרָהָם, שֶׁאִלּוּ בְּאַבְרָהָם לֹא כָתוּב אֶת בֶּן הָגָר, אֶלָּא אֶת בְּנוֹ.</p>\n<p>בֹּא רְאֵה אַחַר כָּךְ מַה כָּתוּב, וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינֵי אַבְרָהָם עַל אוֹדת בְּנוֹ. וְלֹא כָתוּב עַל אוֹדוֹת בֶּן הָגָר הַמִּצְרִית. מִשּׁוּם כָּךְ וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית, וְלֹא רָאֲתָה שֶׁהוּא בֶּן אַבְרָהָם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הַפָּסוּק הַזֶּה תִּשְׁבַּחַת לְשָׂרָה הוּא. מִשּׁוּם שֶׁרָאֲתָה אוֹתוֹ מְצַחֵק לְכוֹכָבִים וּמַזָּלוֹת, אָמְרָה וַדַּאי שֶׁבֵּן זֶה אֵינוֹ בְּנוֹ שֶׁל אַבְרָהָם לַעֲשׂוֹת אֶת מַעֲשֵׂי אַבְרָהָם, אֶלָּא בֶּן הָגָר הַמִּצְרִית הוּא, חָזַר לַחֵלֶק שֶׁל אִמּוֹ. לָכֵן וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַ את עִם בְּנִי עִם יִצְחָק.</p>\n<p>וְכִי עָלָה עַל דַּעְתְּךְ שֶׁקִּנְּאָה לָהּ שָׂרָה אוֹ לַבֵּן שֶׁלָּהּ? אִם כָּךְ, לֹא הָיָה מוֹדֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהּ, שֶׁכָּתוּב כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךְ שָׂרָה שְׁמַע בְּקֹלָהּ. אֶלָּא מִשּׁוּם שֶׁרָאֲתָה אוֹתוֹ עִם כּוֹכָבִים וּמַזָּלוֹת וְאִמּוֹ מְלַמֶּדֶת אוֹתוֹ מִנְהֲגֵי עֲבוֹדָה זָרָה, לָכֵן אָמְרָה שָׂרָה כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזאת. אֲנִי יוֹדַעַת שֶׁלֹּא יִירַשׁ לְעוֹלָמִים אֶת חֵלֶק הָאֱמוּנָה, וְלֹא יִהְיֶה לוֹ עִם בְּנִי חֵלֶק לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא. וְלָכֵן הוֹדָה עִמָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא רָצָה לְהַפְרִיד לְבַדּוֹ אֶת הַזֶּרַע הַקָּדוֹשׁ כָּרָאוּי, שֶׁמִּשּׁוּם כָּךְ בָּרָא אֶת הָעוֹלָם, שֶׁהֲרֵי יִשְׂרָאֵל עָלָה בִרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, וְלָכֵן יָצָא אַבְרָהָם לָעוֹלָם וְהָעוֹלָם הָיָה מִתְקַיֵּם בִּגְלָלוֹ, וְאַבְרָהָם וְיִצְחָק (לא) עָמְדוּ וְלֹא הִתְיַשְּׁבוּ בִמְקוֹמָם עַד שֶׁיָּצָא יַעֲקֹב לָעוֹלָם.</p>\n<p>כֵּיוָן שֶׁיָּצָא יַעֲקֹב לָעוֹלָם, הִתְקַיְּמוּ אַבְרָהָם וְיִצְחָק וְעָמַד כָּל הָעוֹלָם, וּמִשָּׁם יָצָא הָעָם הַקָּדוֹשׁ לָעוֹלָם וְהִתְקַיֵּם הַכֹּל בְּגָוֶן קָדוֹשׁ כָּרָאוּי. וְלָכֵן אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךְ שָׂרָה שְׁמַע בְּקֹלָהּ כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע, וְלֹא בְּיִשְׁמָעֵאל. מַה כָּתוּב אַחַר כָּךְ? וַתֵּלֶךְ וַתֵּתַע בְּמִדְבַּר בְּאֵר שָׁבַע.</p>\n<p>כָּתוּב כָּאן וַתֵּתַע, וְכָתוּב שָׁם (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְלַל אַבְרָהָם לֹא עָזַב אוֹתָהּ וְאֶת בְּנָהּ.</p>\n<p>בֹּא רְאֵה, בַּהַתְחָלָה כְּשֶׁהָלְכָה מִלִּפְנֵי שָׂרָה מַה כָּתוּב? כִּי שָׁמַע ה' אֶל עָנְיֵךְ. וְכָאן שֶׁטָּעֲתָה אַחַר כּוֹכָבִים וּמַזָּלוֹת, אַף עַל גַּב שֶׁכָּתוּב וַתִּשָּׂא אֶת קֹלָהּ וַתֵּבְךָּ, מַה כָּתוּב? כִּי שָׁמַע אֱלֹהִים אֶל קוֹל הַנַּעַר, וְלֹא כָתוּב כִּי שָׁמַע אֱלֹהִים אֶת קוֹלֵךְ.</p>\n<p>בַּאֲשֶׁר הוּא שָׁם, הֲרֵי פֵּרְשׁוּהָ שֶׁלֹּא בָר עֹנֶשׁ הוּא אֵצֶל בֵּית הַדִּין שֶׁלְּמַעְלָה, שֶׁהֲרֵי בֵּית דִּין שֶׁל מַטָּה מַעֲנִישִׁים מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנָה וָמַעְלָה, וּבֵית שֶׁל שֶׁל מַעְלָה מֵעֶשְׂרִים שָׁנָה וָמַעְלָה, וְאַף עַל גַּב שֶׁהָיָה רָשָׁע, אֵינוֹ בֶּן עֹנֶשׁ. וַהֲרֵי פֵּרְשׁוּהָ, וְזֶהוּ שֶׁכָּתוּב בַּאֲשֶׁר הוּא שָׁם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אִם כָּךְ, מִי שֶׁמִּסְתַּלֵּק מֵהָעוֹלָם בְּטֶרֶם הִגִּיעוּ יָמָיו לְעֶשְׂרִים שָׁנָה, מֵאֵיזֶה מָקוֹם נֶעֱנָשׁ, מִשּׁוּם שֶׁהֲרֵי מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַטָּה אֵינוֹ בַּר עֳנָשִׁים אֶלָּא בַּחֲטָאֵי אָבִיו, אֲבָל מִשְּׁלֹשׁ עֶשְׂרֵה וָמַעְלָה מַהוּ? אָמַר לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו שֶׁיָּמוּת זַכַּאי (ולא ימות חיב), וְנוֹתֵן לוֹ שָׂכָר טוֹב בָּעוֹלָם הַהוּא, וְלֹא יָמוּת חַיָּב שֶׁיֵּעָנֵשׁ בְּאוֹתוֹ עוֹלָם, וּבֵאֲרוּהָ.</p>\n<p>אָמַר לוֹ, אִם אֵינוֹ חַיָּב וְלֹא הִגִּיעוּ יָמָיו לְעֶשְׂרִים שָׁנָה, כֵּיוָן שֶׁהִסְתַּלֵּק מֵהָעוֹלָם בַּמָּה הוּא עָנְשׁוֹ? אָמַר לוֹ, בָּזֶה מִתְקַיֵּם, (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. שֶׁכְּשֶׁעֹנֶשׁ יוֹרֵד לָעוֹלָם, הוּא (הדין) פּוֹגֵעַ בְּלִי כַוָּנָה לְמַעְלָה וּלְמַטָּה בְּאוֹתוֹ מַשְׁחִית, וְיֵעָנֵשׁ כְּשֶׁלֹּא מַשְׁגִּיחִים עָלָיו מִלְמַעְלָה.</p>\n<p>וְעָלָיו כָּתוּב (שם ה) עֲווֹנוֹתָיו יִלְכְּדֻנוֹ אֶת הָרָשָׁע. אֶת - לְרַבּוֹת מִי שֶׁלֹּא הִגִּיעוּ יָמָיו לְהֵעָנֵשׁ. עֲווֹנוֹתָיו יִלְכְּדֻנוֹ (את הרשע), וְלֹא בֵּית הַדִּין שֶׁלְּמַעְלָה. וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ, וְלֹא בֵּית דִּין שֶׁלְּמַטָּה. לָכֵן כָּתוּב כִּי שָׁמַע אֱלֹהִים אֶל קוֹל הַנַּעַר בַּאֲשֶׁר הוּא שָׁם.</p>"],[9522011247,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. מָלֵא בְּוָא\"ו לָמָּה? אֶלָּא בִּשְׁנֵי צְדָדִים הוּא (הם). סוֹד שֶׁל חָכְמָה אֶחָד. שֶׁהוּא הַסּוֹד שֶׁל דַּרְגָּה שֶׁל חָכְמָה, הַמָּקוֹם שֶׁשּׁוֹרֶה בּוֹ יַעֲקֹב. אֲבָל פָּסוּק זֶה נֶאֱמַר עַל הַגָּלוּת שֶׁל יִשְׂרָאֵל. שֶׁכְּשֶׁהֵם בְּתוֹךְ הַגָּלוּת, אוֹתוֹ זְמַן שֶׁיִּפָּקְדוּ (בו י קב), הֵם יִפָּקְדוּ בַּסּוֹד שֶׁל וָא\"ו, וְהוּא בָּאֶלֶף הַשִּׁשִּׁי.</p>\n<p>וּפְקִידָה בְּסוֹד שֶׁל וָא\"ו שִׁשָּׁה רְגָעִים וַחֲצִי זְמַן. וּבִזְמַן שֶׁל שִׁשִּׁים שָׁנִים לִבְרִיחַ הַדֶּלֶת בָּאֶלֶף הַשִּׁשִּׁי, יָקִים אֱלֹהֵי הַשָּׁמַיִם פְּקִידָה לְבַת יַעֲקֹב. וּמֵאוֹתוֹ זְמַן עַד שֶׁיִּהְיֶה לָהּ זְכִירָה - שֵׁשׁ שָׁנִים וָחֵצִי. וּמֵאוֹתוֹ זְמַן שֵׁשׁ שָׁנִים אֲחֵרוֹת, וְהֵם שִׁבְעִים (ושלש) וּשְׁתַּיִם וָחֵצִי.</p>\n<p>בְּשִׁשִּׁים וָשֵׁשׁ יִתְגַּלֶּה מֶלֶךְ הַמָּשִׁיחַ בְּאֶרֶץ הַגָּלִיל, וְכוֹכָב אֶחָד בְּצַד מִזְרָח יִבְלַע שִׁבְעָה כּוֹכָבִים מִצַּד צָפוֹן, וְשַׁלְהֶבֶת אֵשׁ שְׁחוֹרָה תִּהְיֶה תְלוּיָה בָּרָקִיעַ שִׁשִּׁים יוֹם, וּקְרָבוֹת יִתְעוֹרְרוּ בָעוֹלָם לְצַד צָפוֹן, וּשְׁנֵי מְלָכִים יִפְּלוּ בְּאוֹתָם קְרָבוֹת.</p>\n<p>וְיִזְדַּוְּגוּ כָּל הָעַמִּים עַל בַּת יַעֲקֹב לִדְחוֹת אוֹתָהּ (אותם) מֵהָעוֹלָם. וְעַל אוֹתוֹ הַזְּמַן כָּתוּב, (והיתה) (ירמיה ל) וְעֵת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּה יִוָּשֵׁעַ, וְאָז יִסְתַּיְּמוּ הַנְּפָשׁוֹת מֵהַגּוּף וְרוֹצִים לְהִתְחַדֵּשׁ, וְסִימָן לַדָּבָר - (כל הנפש לבית יעקב הבאה מצרימה שבעים, וכתוב) (בראשית מו) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה וְגוֹ', כָּל נֶפֶשׁ שִׁשִּׁים וָשֵׁשׁ.</p>\n<p>בְּשִׁבְעִים וְשָׁלֹשׁ כָּל מַלְכֵי הָעוֹלָם יִתְכַּנְּסוּ לְתוֹךְ הָעִיר הַגְּדוֹלָה שֶׁל רוֹמִי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר עֲלֵיהֶם אֵשׁ וּבָרָד וְאַבְנֵי אֶלְגָּבִישׁ וְיאבְדוּ מֵהָעוֹלָם, פְּרָט לְאוֹתָם מְלָכִים שֶׁלֹּא יַגִּיעוּ לְשָׁם וְיַחְזְרוּ לְעוֹרֵר קְרָבוֹת אֲחֵרִים. וּמֵאוֹתוֹ זְמַן מֶלֶךְ הַמָּשִׁיחַ יִתְעוֹרֵר בְּכָל הָעוֹלָם, וְיִתְכַּנְּסוּ עִמּוֹ כַּמָּה עַמִּים וְכַמָּה חֲיָלוֹת מִכָּל סוֹפֵי הָעוֹלָם, וְכָל בְּנֵי יִשְׂרָאֵל יִתְכַּנְּסוּ בְּכָל אוֹתָם מְקוֹמוֹת.</p>\n<p>עַד שֶׁיִּשְׁלְמוּ אוֹתָן שָׁנִים לְמֵאָה. אָז וָא\"ו תִּתְחַבֵּר עִם הֵ\"א, וְאָז (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגוֹ'. וּבְנֵי יִשְׁמָעֵאל (ישראל) עֲתִידִים בְּאוֹתוֹ זְמַן לְהִתְעוֹרֵר (עליהם) עִם כָּל עַמֵּי הָעוֹלָם לָבא עַל יְרוּשָׁלַיִם, שֶׁכָּתוּב (זכריה יד) וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלַיִם לַמִּלְחָמָה וְגוֹ'. וְכָתוּב (תהלים ב) יִתְיַצְּבוּ מַלְכֵי אֶרֶץ וְרוֹזְנִים נוֹסְדוּ יָחַד עַל ה' וְעַל מְשִׁיחוֹ. וְכָתוּב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק ה' יִלְעַג לָמוֹ.</p>\n<p>אַחַר כָּךְ וָא\"ו קְטַנָּה תִּתְעוֹרֵר לְהִתְחַבֵּר וּלְחַדֵּשׁ נְשָׁמוֹת שֶׁהָיוּ יְשָׁנוֹת כְּדֵי לְחַדֵּשׁ אֶת הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב (שם קד) יִשְׂמַח ה' בְּמַעֲשָׂיו. וְכָתוּב יְהִי כְבוֹד ה' לְעוֹלָם, לְהִתְחַבֵּר כָּרָאוּי. יִשְׂמַח ה' בְּמַעֲשָׂיו, לְהוֹרִיד אוֹתָם לָעוֹלָם, וְשֶׁכֻּלָּם יִהְיוּ בְרִיּוֹת חֲדָשׁוֹת לְחַבֵּר אֶת כָּל הָעוֹלָמוֹת יַחַד.</p>\n<p>אַשְׁרֵיהֶם כָּל אוֹתָם שֶׁיִּשָּׁאֲרוּ בְּסוֹף הָאֶלֶף הַשִּׁשִּׁי לְהִכָּנֵס לְשַׁבָּת, שֶׁהֲרֵי אָז הוּא יוֹם אֶחָד לַקָּבָּ\"ה לְבַדּוֹ, לְהִזְדַּוֵּג כָּרָאוּי וְלִלְקֹט נְשָׁמוֹת חֲדָשׁוֹת שֶׁיִּהְיוּ בָעוֹלָם עִם אוֹתָם שֶׁנִּשְׁאֲרוּ בָרִאשׁוֹנָה, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלם.</p>"],[9522011248,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וַיֹּאמֶר אֵלָיו אַבְרָהָם וַיֹּאמֶר הִנֵּנִי. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים מד) אַתָּה הוּא מַלְכִּי וְגוֹ'. זוֹהִי הַשְּׁלֵמוּת שֶׁל כָּל הַדְּרָגוֹת יַחַד זוֹ עִם זוֹ.</p>\n<p>צַוֵּה יְשׁוּעוֹת יַעֲקֹב, כָּל אוֹתָם הַשְּׁלִיחִים שֶׁעוֹשִׂים שְׁלִיחוּת בָּעוֹלָם, שֶׁכֻּלָּם יִהְיוּ בְּצַד הָרַחֲמִים וְלֹא יִהְיוּ מִצַּד הַדִּין, מִשּׁוּם שֶׁיֵּשׁ בַּעֲלֵי שְׁלִיחִים מִצַּד הָרַחֲמִים וּמִצַּד הַדִּין הַקָּשֶׁה. אוֹתָם שְׁלִיחִים שֶׁבָּאִים מִצַּד הָרַחֲמִים לֹא עוֹשִׂים שְׁלִיחוּת שֶׁל דִּין בָּעוֹלָם כְּלָל.</p>\n<p>וְאִם תֹּאמַר, הִנֵּה הַמַּלְאָךְ שֶׁהִתְגַּלָּה לְבִלְעָם, הֲרֵי שָׁנִינוּ שָׁלִיחַ שֶׁל רַחֲמִים וְהִתְהַפֵּךְ לְדִין - לֹא! לְעוֹלָם לֹא מִשְׁתַּנֶּה. אֶלָּא שְׁלִיחַ הָרַחֲמִים הָיָה לְהָגֵן עַל יִשְׂרָאֵל וְלִהְיוֹת עֲלֵיהֶם סָנֵגוֹר, וּכְנֶגְדּוֹ הוּא הַדִּין. כָּךְ דְּרָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁמֵּיטִיב לָזֶה, אוֹתוֹ הַחֶסֶד הוּא דִין לָזֶה. כֵּן הַשָּׁלִיחַ הַזֶּה הָיָה שֶׁל רַחֲמִים לְיִשְׂרָאֵל, וּלְבִלְעָם הִתְהַפֵּךְ לְדִין, מִשּׁוּם כָּךְ צַוֵּה יְשׁוּעוֹת יַעֲקֹב. אָמַר דָּוִד, צַוֵּה עַל הָעוֹלָם, כַּאֲשֶׁר יִשָּׁלְחוּ שְׁלוּחִים שֶׁיִּהְיוּ מִצַּד הָרַחֲמִים.</p>\n<p>רַבִּי אַבָּא אָמַר, צַוֵּה יְשׁוּעוֹת יַעֲקֹב, שֶׁהֵם בְּתוֹךְ הַגָּלוּת, וְתִמָּצֵא לָהֶם גְּאֻלָּה בְּתוֹךְ גָּלוּתָם. בּא רְאֵה, הַמְשֻׁבָּח שֶׁל הָאָבוֹת הָיָה יַעֲקֹב, וְאִלְמָלֵא יִצְחָק לֹא בָא יַעֲקֹב לָעוֹלָם. וּמִשּׁוּם כָּךְ, צַוֵּה יְשׁוּעוֹת יַעֲקֹב - זֶה יִצְחָק. שֶׁכֵּיוָן שֶׁנִּצַּל יִצְחָק, הָיוּ יְשׁוּעוֹת יַעֲקֹב.</p>\n<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי שִׁמְעוֹן אָמַר, הִנֵּה שָׁנִינוּ וַיְהִי בִּימֵי, נֶאֱמַר עַל צַעַר. וַיְהִי - אַף עַל גַּב שֶׁלֹּא כָתוּב בִּימֵי, דְּפוּס שֶׁל צַעַר יֵשׁ בּוֹ. וַיְהִי אַחַר הַדְּבָרִים, אַחַר הַדַּרְגָּה הַתַּחְתּוֹנָה שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת. וּמַהוּ הַדְּבָרִים? כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) לֹא אִישׁ דְּבָרִים אָנֹכִי.</p>\n<p>וּמִי הָיָה אַחַר הַדַּרְגָּה הַזּוֹ? וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. שֶׁבָּא יֵצֶר הָרָע לְקַטְרֵג לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כָּאן יֵשׁ לְהִסְתַּכֵּל, וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם? אֶת יִצְחָק הָיָה צָרִיךְ (לכתב), שֶׁהֲרֵי יִצְחָק הָיָה בֶּן שְׁלֹשִׁים וָשֶׁבַע, וַהֲרֵי אָבִיו לֹא הָיָה בַּר עֹנֶשׁ שֶׁלּוֹ, שֶׁאִלְמָלֵא אָמַר יִצְחָק אֵינִי רוֹצֶה - לֹא הָיָה נֶעֱנַשׁ אָבִיו עָלָיו. מָה הַטַּעַם וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וְלֹא כָתוּב נִסָּה אֶת יִצְחָק?</p>\n<p>אֶלָּא אֶת אַבְרָהָם, וַדַּאי שֶׁרָצָה לְהִכָּלֵל עִם דִּין, שֶׁהֲרֵי אַבְרָהָם לֹא הָיָה בּוֹ דִּין כְּלָל מִקֹּדֶם לָכֵן, וְכָאן נִכְלְלוּ מַיִ\"ם עִם אֵ\"שׁ, וְאַבְרָהָם לֹא הָיָה שָׁלֵם עַד עַכְשָׁו, שֶׁהִתְעַטֵּר לַעֲשׂוֹת דִּין וּלְהַתְקִינוֹ בִּמְקוֹמוֹ.</p>\n<p>וְכָל יָמָיו לֹא הָיָה שָׁלֵם עַד עַכְשָׁו שֶׁנִּכְלַל מַיִ\"ם עִם אֵ\"שׁ וְאֵ\"שׁ עִם מַיִ\"ם, וּמִשּׁוּם כָּךְ וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וְלֹא אֶת יִצְחָק, שֶׁהִזְמִין אַבְרָהָם לְהִכָּלֵל עִם דִּין. וּכְשֶׁעָשָׂה אֶת זֶה, נִכְנַס אֵ\"שׁ עִם מַיִ\"ם וְנִשְׁלַם זֶה עִם זֶה. וְזֶה עוֹשֶׂה הַדִּין לְהִכָּלֵל זֶה עִם זֶה. וְאָז יֵצֶר הָרָע בָּא לְקַטְרֵג עַל אַבְרָהָם שֶׁלֹּא הִשְׁתַּלֵּם כָּרָאוּי עַד שֶׁיַּעֲשֶׂה דִין בְּיִצְחָק. שֶׁיֵּצֶר הָרָע הוּא אַחַר הַדְּבָרִים וְהוּא בָּא לְקַטְרֵג.</p>\n<p>וּבֹא וּרְאֵה סוֹד הַדָּבָר. אַף עַל גַּב שֶׁאָמַרְנוּ שֶׁכָּתוּב אַבְרָהָם וְלֹא יִצְחָק, גַּם יִצְחָק נִכְלָל בַּפָּסוּק הַזֶּה סוֹד הַכָּתוּב וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. לֹא כָתוּב נִסָּה לְאַבְרָהָם, אֶלָּא אֶת אַבְרָהָם, אֶת דַּוְקָא, וְזֶה יִצְחָק. שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה בַּגְּבוּרָ\"ה הַתַּחְתּוֹנָה שׁוֹרֶה. כֵּיוָן שֶׁנֶּעֱקַד וְהִזְדַּמֵּן בְּדִין עַל יְדֵי אַבְרָהָם כָּרָאוּי, אָז הִתְעַטֵּר בִּמְקוֹמוֹ יַחַד עִם אַבְרָהָם וְנִכְלְלוּ אֵ\"שׁ עִם מַיִ\"ם וְעָלוּ לְמַעְלָה, וְאָז נִמְצְאָה מַחֲלֹקֶת כָּרָאוּי, מַיִם עִם אֵשׁ.</p>\n<p>מִי (עשה) רָאָה אָב רַחְמָן שֶׁנַּעֲשֶׂה אַכְזָר? אֶלָּא כְּדֵי שֶׁתִּמָּצֵא מַחֲלֹקֶת מַיִם עִם אֵשׁ וּלְהִתְעַטֵּר בִּמְקוֹמָם (כראוי), עַד שֶׁבָּא יַעֲקֹב וְהַכֹּל הִתְתַּקֵּן כָּרָאוּי, וְנַעֲשׂוּ שְׁלֹשָׁה אָבוֹת שְׁלֵמִים וְנִתְקְנוּ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וַיֹּאמֶר קַח נָא אֶת בִּנְךְ. וְכִי אֵיךְ יָכוֹל אַבְרָהָם שֶׁהוּא זָקֵן? אִם תֹּאמַר מִשּׁוּם שֶׁיִּצְחָק לֹא יָצָא מֵרְשׁוּתוֹ כְּלָל - יָפֶה, אֲבָל כְּמוֹ שֶׁנֶּאֱמַר (במדבר כ) קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ, אֶלָּא כְּדֵי לְהַמְשִׁיכָם בִּדְבָרִים וּלְהַנְהִיגָם לִרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף כָּאן קַח בִּדְבָרִים. אֶת בִּנְךְ אֶת יְחִידְךְ אֲשֶׁר אָהַבְתָּ, הֲרֵי פֵּרְשׁוּהָ. וְלֶךְ לְךְ אֶל אֶרֶץ הַמֹּרִיָּה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) אֵלֵךְ לִי אֶל הַר הַמּוֹר, לְתַקֵּן בַּמָּקוֹם שֶׁרָאוּי.</p>"],[9522011249,"<p>בַּיּוֹם הַשְּׁלִישִׁי וַיִּשָּׂ\"א אַבְרָהָ\"ם אֶ\"ת עֵינָיו וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק. בַּיּוֹם הַשְּׁלִישִׁי, הֲרֵי פֵּרְשׁוּהָ. אֶלָּא כֵּיוָן שֶׁאָמַר וַיָּקָם וַיֵּלֶךְ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלֹהִים, מָה הַטַּעַם בַּיּוֹם הַשְּׁלִישִׁי וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק? אֶלָּא מִשּׁוּם שֶׁכָּתוּב כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע, וְזֶהוּ יַעֲקֹב שֶׁיָּצָא מִמֶּנּוּ, וְזֶהוּ בַּיּוֹם הַשְּׁלִישִׁי. וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאה לִי.</p>\n<p>וַיַּרְא אֶת הַמָּקוֹם - זֶהוּ יַעֲקֹב, שֶׁכָּתוּב (בראשית כח) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. הִסְתַּכֵּל אַבְרָהָם בַּיּוֹם הַשְּׁלִישִׁי, שֶׁהוּא הַדַּרְגָּה הַשְּׁלִישִׁית, וְרָאָה אֶת יַעֲקֹב שֶׁעָתִיד לָצֵאת מִמֶּנּוּ. מֵרָחוֹק, כְּמוֹ שֶׁאָמַרְנוּ מֵרָחוֹק וְלֹא לִזְמַן קָרוֹב.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, מַה שֶּׁבַח שֶׁל אַבְרָהָם כְּשֶׁהִסְתַּכֵּל וְרָאָה שֶׁעָתִיד לָצֵאת מִמֶּנּוּ יַעֲקֹב, שֶׁהֲרֵי כְּשֶׁהָלַךְ לַעֲקֹד אֶת יִצְחָק אֵינוֹ שֶׁבַח כָּל כָּךְ שֶׁלּוֹ?</p>\n<p>אָמַר לוֹ, וַדַּאי (והרי) שֶׁרָאָה אֶת יַעֲקֹב, שֶׁהֲרֵי מִקֹּדֶם לָכֵן יָדַע אַבְרָהָם אֶת הַחָכְמָה, וְהִסְתַּכֵּל עַכְשָׁו בַּיּוֹם הַשְּׁלִישִׁי שֶׁהִיא דַרְגָּה שְׁלִישִׁית לַעֲשׂוֹת שְׁלֵמוּת, וְאָז רָאָה אֶת יַעֲקֹב, שֶׁכָּתוּב וַיַּרְא אֶת הַמָּקוֹם. אֲבָל עַכְשָׁו עָמַד לוֹ הַדָּבָר מֵרָחוֹק, מִשּׁוּם שֶׁהָלַךְ לַעֲקֹד אֶת יִצְחָק וְלֹא רָצָה לְהַרְהֵר אַחֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מֵרָחוֹק רָאָה אוֹתוֹ בְּתוֹךְ הָאַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה בִּלְבַדָּהּ, וְלָכֵן רָאָה אוֹתוֹ וְלֹא הִתְגַּלָּה הַכֹּל. שֶׁאִלּוּ הָיְתָה מְצוּיָה הָאַסְפַּקְלַרְיָה הַמְּאִירָה עַל הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, הִתְקַיֵּם עָלֶיהָ אַבְרָהָם כָּרָאוּי, אֲבָל מֵרָחוֹק בִּלְבַדּוֹ הָיָה. מֵרָחוֹק.</p>\n<p>מָה הַטַּעַם הִסְתַּלְּקָה מֵהַדָּבָר הַזֶּה הָאַסְפַּקְלַרְיָה הַמְּאִירָה? מִשּׁוּם שֶׁזּוֹ הָיְתָה דַרְגָּתוֹ שֶׁל יַעֲקֹב, וּמִשּׁוּם שֶׁעֲדַיִן לֹא נוֹלַד יַעֲקֹב, לֹא נִמְצָא כָּאן עַל הַדַּרְגָּה הַזּוֹ. וְעוֹד, כְּדֵי שֶׁיֵּלֵךְ וִיקַבֵּל שָׂכָר. וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק - זֶה יַעֲקֹב, כְּמוֹ שֶׁנִּתְבָּאֵר מֵרָחוֹק, שֶׁלֹּא זָכָה בּוֹ.</p>\n<p>(ראיה בעיניו בעולם הזה, אלא מרחוק, מתוך הדרגה הזו, שהרי כשבא יעקב, אברהם היה מת והסתלק מהעולם, וירא את המקום מרחק, אבל לא בראיה אחרת). וַיָּבֹאוּ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלֹהִים וְגוֹ'. רָמוּז (ראה) כָּאן, שֶׁאַף עַל גַּב שֶׁבָּאוּ לְאוֹתָהּ רְאִיָּה וְרָאָה אֶת יַעֲקֹב, אָמַר אַבְרָהָם, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ בְּגָוֶן אַחֵר שֶׁרָאוּי, מִיָּד וַיִּבֶן שָׁם אַבְרָהָם אֶת הַמִּזְבֵּחַ וְגוֹ'.</p>\n<p>מַה כָּתוּב לְמַעְלָה? וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם אָבִיו וַיֹּאמֶר אָבִי. הֲרֵי פֵּרְשׁוּהָ. אֲבָל מָה הַטַּעַם לֹא הֵשִׁיב לוֹ (דבר) מִיָּד? אֶלָּא מִשּׁוּם שֶׁהֲרֵי הִסְתַּלֵּק מֵרַחֲמִים שֶׁל אָב עַל בֵּן, וְלָכֵן כָּתוּב הִנֶּנִּי בְנִי, הִנֶּנִּי שֶׁהִסְתַּלְּקוּ הָרַחֲמִים וְהִתְהַפֵּךְ לְדִין.</p>\n<p>וַיֹּאמֶר אַבְרָהָם, וְלֹא כָתוּב וַיֹּאמֶר אָבִיו, שֶׁהֲרֵי לֹא עָמַד עָלָיו כְּאָב, אֶלָּא בַּעַל מַחֲלֹקֶת הָיָה עִמּוֹ. אֱלֹהִים יִרְאֶה לּוֹ הַשֶּׂה. הָיָה צָרִיךְ (לכתב) יִרְאֶה לָנוּ, מַה זֶּה יִרְאֶה לּוֹ? אֶלָּא אָמַר לוֹ אֱלֹהִים יִרְאֶה לוֹ לְעַצְמוֹ כְּשֶׁהוּא יִצְטָרֵךְ, אֲבָל עַכְשָׁו בְּנִי, וְלֹא כֶבֶשׂ. מִיָּד וַיֵּלְכוּ שְׁנֵיהֶם יַחְדָּו.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. הֵן אֶרְאֶלָּם - אֵלּוּ מַלְאָכִים עֶלְיוֹנִים, צָעֲקוּ בְּאוֹתָהּ שָׁעָה וְרָצוּ לַעֲמֹד עַל אוֹתוֹ הַדָּבָר, שֶׁכָּתוּב (בראשית טו) וַיּוֹצֵא אֹתוֹ הַחוּצָה, לָכֵן צָעֲקוּ חֻצָה.</p>\n<p>מַלְאֲכֵי שָׁלוֹם - אֵלּוּ אוֹתָם מַלְאָכִים אֲחֵרִים שֶׁהָיוּ עֲתִידִים לָלֶכֶת לִפְנֵי יַעֲקֹב, וּבִשְׁבִיל יַעֲקֹב הִבְטִיחַ לָהֶם שְׁלֵמוּת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שם לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. וְאֵלּוּ נִקְרְאוּ מַלְאֲכֵי שָׁלוֹם, כֻּלָּם בָּכוּ כְּשֶׁרָאוּ אֶת אַבְרָהָם שֶׁעוֹקֵד אֶת יִצְחָק, וְהִזְדַּעְזְעוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְכֻלָּם עַל יִצְחָק.</p>"],[9522011250,"<p>וַיִּקְרָא אֵלָיו מַלְאַךְ ה' וְגוֹ'. מַפְסִיק טַעַם בֵּינֵיהֶם, שֶׁאֵין אַבְרָהָם הָאַחֲרוֹן כָּרִאשׁוֹן. הָאַחֲרוֹן שָׁלֵם, הָרִאשׁוֹן לֹא שָׁלֵם. כְּמוֹ זֶה שְׁמוּאֵל שְׁמוּאֵל - הָאַחֲרוֹן שָׁלֵם, הָרִאשׁוֹן לֹא שָׁלֵם. הָאַחֲרוֹן נָבִיא, הָרִאשׁוֹן לֹא נָבִיא. אֲבָל בְּמֹשֶׁה מֹשֶׁה אֵין הֶפְסֵק טַעַם, מִשּׁוּם שֶׁמִּיּוֹם שֶׁנּוֹלַד לֹא זָזָה מִמֶּנּוּ שְׁכִינָה. אַבְרָהָם אַבְרָהָם. רַבִּי חִיָּיא אָמַר, כְּדֵי לְעוֹרְרוֹ לְרוּחַ אַחֶרֶת, בְּמַעֲשֶׂה אַחֵר, בְּלֵב אַחֵר.</p>\n<p>רַבִּי יְהוּדָה אָמַר, נִבְחַר יִצְחָק וְהִתְעַלָּה בְרָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּרֵיחַ קְטֹרֶת הַבְּשָׂמִים שֶׁמַּקְרִיבִים הַכֹּהֲנִים לְפָנָיו פַּעֲמַיִם בַּיּוֹם וְנִשְׁלָם הַקָּרְבָּן. שֶׁהֲרֵי צַעֲרוֹ שֶׁל אַבְרָהָם הָיָה בְּשָׁעָה שֶׁנֶּאֱמַר לוֹ אַל תִּשְׁלַח יָדְךְ אֶל הַנַּעַר וְאַל תַּעַשׂ לוֹ מְאוּמָה, חָשַׁב שֶׁקָּרְבָּנוֹ לֹא נִשְׁלַם וּלְחִנָּם עָשָׂה וְסִדֵּר הַכֹּל וּבָנָה מִזְבֵּחַ. מִיָּד: וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל אַחַר וְגוֹ'.</p>\n<p>הֲרֵי שָׁנִינוּ, הוּא הָאַיִל שֶׁנִּבְרָא בֵּין הַשְּׁמָשׁוֹת הָיָה, וּבֶן שְׁנָתוֹ הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ז) כֶּבֶשׂ אֶחָד בֶּן שְׁנָתוֹ, וְכָךְ צָרִיךְ. (ואתה אמרת בין השמשות, ועוד, והרי יצחק לא היה בעולם, אלא נפקד וכו') (והרי יצחק לא היה בעולם) וְאַתָּה אוֹמֵר שֶׁנִּבְרָא בֵּין הַשְּׁמָשׁוֹת? אֶלָּא נִפְקַד כֹּחַ שֶׁיְּזַמֵּן אוֹתוֹ הָאַיִל בְּשָׁעָה שֶׁהִצְטָרֵךְ אוֹתוֹ אַבְרָהָם. כְּמוֹ שֶׁכָּל אוֹתָם הַדְּבָרִים שֶׁהָיוּ בֵּין הַשְּׁמָשׁוֹת, הִתְמַנָּה כֹּחַ שֶׁיִּזְדַּמֵּן אוֹתוֹ דָבָר (לזמן ההוא) בְּשָׁעָה שֶׁצָּרִיךְ אוֹתוֹ. כָּךְ גַּם הָאַיִל הַזֶּה שֶׁהֻקְרַב תַּחַת יִצְחָק.</p>"],[9522011251,"<p>פָּתַח וְאָמַר, (ישעיה סג) בְּכָל צָרָתָם לֹא צָר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם וְגוֹ'. בּא רְאֵה, בְּכָל צָרָתָם שֶׁל יִשְׂרָאֵל, כְּשֶׁמִּזְדַּמְּנוֹת לָהֶם צָרוֹת, כָּתוּב לֹא בְּאָלֶ\"ף וְקוֹרְאִים בְּוָא\"ו, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּם בַּצָּרָה. לֹא בְּאָלֶ\"ף מָקוֹם יוֹתֵר עֶלְיוֹן, אַף עַל גַּב שֶׁאֵין בְּאוֹתוֹ מָקוֹם רֹגֶז וְצָרָה, לְשָׁם לְמַעְלָה מַגִּיעָה צָרָתָם שֶׁל יִשְׂרָאֵל. לֹא בְּאָלֶ\"ף, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. כָּתוּב בְּאָלֶ\"ף וְקוֹרְאִים בְּוָא\"ו.</p>\n<p>וּמַלְאַךָ פָּנָיו הוֹשִׁיעָם, וַהֲרֵי הוּא עִמָּם בְּאוֹתָהּ צָרָה, וְאַתָּה אוֹמֵר הוֹשִׁיעָם? אֶלָּא לֹא כָתוּב מוֹשִׁיעָם, אֶלָּא הוֹשִׁיעָם מִקֹּדֶם לָכֵן, שֶׁהוּא עָתִיד בְּאוֹתָהּ צָרָה לִסְבֹּל עִמָּם. בּא רְאֵה, בְּכָל זְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת - שְׁכִינָה עִמָּם בַּגָּלוּת, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב (דברים ל) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחַמְךְ וְגוֹ'.</p>\n<p>דָּבָר אַחֵר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם - זוֹ שְׁכִינָה, שֶׁהִיא עִמָּם בַּגָּלוּת, וְאַתָּה אוֹמֵר שֶׁהוּא הוֹשִׁיעָם? אֶלָּא כָּךְ זֶה בְּוַדַּאי, שֶׁאֵלֶּה הֵם מִשְׁכְּנוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּגָּלוּת. וּמִשּׁוּם שֶׁשְּׁכִינָה עִמָּהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אוֹתָם לְהֵיטִיב לָהֶם וּלְהוֹצִיאָם מֵהַגָּלוּת, שֶׁכָּתוּב (שמות ו) וָאֶזְכֹּר אֶת בְּרִיתִי, בַּהַתְחָלָה. וְאַחַר כָּךְ, וְעַתָּה הִנֵּה צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלַי.</p>\n<p>וְגַם רָאִיתִי - לְרַבּוֹת רְאִיָּה אַחֶרֶת שֶׁהִיא הָרִאשׁוֹנָה שֶׁל הַכֹּל. וְכָתוּב (שם ב) וַיִּזְכֹּר אֱלֹהִים אֶל בְּרִיתוֹ, זוֹ שְׁכִינָה. אֶת אַבְרָהָם? לְאַבְרָהָם הָיָה צָרִיךְ לִכְתֹּב. אֶלָּא אֶת אַבְרָהָם זוֹ הַחֲבֵרוּת וְהַזִּוּוּג שֶׁלָּהּ עִם הָאָבוֹת. אֶת אַבְרָהָם - זֶהוּ מַעֲרָבִית דְּרוֹמִית. אֶת יִצְחָק - זֶהוּ צְפוֹנִית מַעֲרָבִית. וְאֶת יַעֲקֹב - זֶהוּ זִוּוּג אֶחָד, כְּלָל אֶחָד, זִוּוּג שָׁלֵם כָּרָאוּי.</p>\n<p>כְּמוֹ זֶה אֵת הַשָּׁמַיִם - זֶהוּ כְּלָל שֶׁל מִדַּת לַיְלָה בַּיּוֹם. וְאֵת הָאָרֶץ - זוֹ מִדַּת יוֹם בַּלַּיְלָה כְּאֶחָד. אַף כָּאן בְּכֻלָּם אֶת, וּבְיַעֲקֹב וְאֶת, שֶׁיִּהְיֶה הַכֹּל זִוּוּג אֶחָד שֶׁלֹּא נִפְרָדִים זָכָר וּנְקֵבָה לְעוֹלָמִים. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְרִיז בְּכָל הָעוֹלָם וּלְהַשְׁמִיעַ קוֹל שֶׁיֹּאמַר (ישעיה סג) וַיֹּאמֶר אַךְ עַמִּי הֵמָּה בָּנִים לֹא יְשַׁקֵּרוּ וַיְהִי לָהֶם לְמוֹשִׁיעַ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011252,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים. רַבִּי יוֹסֵי פָּתַח וְאָמַר, (יונה א) וַיִּשְׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. כָּאן יֵשׁ לְהִסְתַּכֵּל מָה הַטַּעַם הִרְעִישׁ הַיָּם עַל יוֹנָה וְלֹא הִרְעִישָׁה הָאָרֶץ עָלָיו, כֵּיוָן שֶׁהָיָה הוֹלֵךְ כְּדֵי שֶׁלֹּא תִשְׁרֶה עָלָיו הַשְּׁכִינָה? לָמָּה הַיָּם (העליון) הָיָה אוֹחֵז בּוֹ כְּשֶׁהָיָה הוֹלֵךְ?</p>\n<p>אֶלָּא וַדַּאי הָיָה הַדָּבָר בִּמְקמוֹ. יָם שָׁנִינוּ, הַיָּם דּוֹמֶה לָרָקִיעַ, וְהָרָקִיעַ לְכִסֵּא הַכָּבוֹד, וּמִשּׁוּם כָּךְ הַיָּם אָחַז בּוֹ וְנָטַל אוֹתוֹ (משום שהיה בורח) בָּרַח מִלִּפְנֵי הַיָּם (נ\"א: ומלפני הים בו שרתה יראה במקומו), זָרַק הַיָּם בּוֹ יָד בִּמְקוֹמוֹ (נ\"א תשרה היד במקומה).</p>\n<p>וַיִּשְׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם. לָמַדְנוּ, כְּשֶׁהָיוּ נוֹטְלִים אוֹתוֹ וּמְטַבְּעִים אֶת יְרֵכָיו בַּיָּם - הַיָּם הָיָה שׁוֹכֵךְ. מְרִימִים אוֹתוֹ - וְהַיָּם רוֹעֵשׁ. כָּל מַה שֶּׁמְּטַבְּעִים אוֹתוֹ - כָּךְ הָיָה הַיָּם שׁוֹכֵךְ. עַד שֶׁהוּא אָמַר שָׂאוּנִי וַהֲטִילֻנִי אֶל הַיָּם. מִיָּד וַיִּשִׂאוּ אֶת יוֹנָה וַיְטִלֻהוּ אֶל הַיָּם.</p>\n<p>כֵּיוָן שֶׁנִּזְרַק בַּיָּם, פָּרְחָה מִמֶּנּוּ נִשְׁמָתוֹ, וְעָלְתָה עַד כִּסֵּא הַמֶּלֶךְ וְנִדּוֹנָה לְפָנָיו, וְחָזְרָה לוֹ נִשְׁמָתוֹ, וְנִכְנַס בְּפִי הַדָּג הַהוּא וּמֵת הַדָּג. לְאַחַר מִכֵּן הִתְקַיֵּם אוֹתוֹ הַדָּג, וּפֵרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם עוֹלֶה עַל מִטָּתוֹ בְּכָל לַיְלָה וְלַיְלָה, נִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ וְנִדּוֹנֵית לִפְנֵי בֵּית הַדִּין שֶׁל הַמֶּלֶךְ. אִם זַכַּאי לְהִתְקַיֵּם - חוֹזֶרֶת לָעוֹלָם הַזֶּה.</p>\n<p>וְהַדִּין הוּא בִּשְׁנֵי גְוָנִים, שֶׁהֲרֵי אֵין דָּנִים אֶת הָאִישׁ עַל הָרָעוֹת שֶׁהוּא עָתִיד וּמְזֻמָּן לַעֲשׂוֹת, שֶׁכָּתוּב (בראשית כא) כִּי שָׁמַע אֱלֹהִים וְגוֹ' בַּאֲשֶׁר הוּא שָׁם. וְלֹא תֹאמַר שֶׁדָּנִים אוֹתוֹ עַל הַטּוֹבוֹת שֶׁעָשָׂה לְחוּד, אֶלָּא לְהֵיטִיב לוֹ עַל אוֹתָם טוֹבוֹת שֶׁל עַכְשָׁו, כְּמוֹ שֶׁנִּתְבָּאֵר. וְדָנִים אוֹתוֹ עַל זְכֻיּוֹת שֶׁעָתִיד לַעֲשׂוֹת, וּבִשְׁבִילָם הוּא נִצּוֹל, אַף עַל גַּב שֶׁהוּא כָּעֵת רָשָׁע. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם כָּל הַבְּרִיּוֹת, וְכָל דַּרְכּוֹ שֶׁהוּא עוֹשֶׂה - לְהֵיטִיב לַכֹּל, וְלֹא דָן אֶת הָאָדָם עַל הָרָעוֹת שֶׁהוּא עָתִיד לַעֲשׂוֹת, וּמִשּׁוּם כָּךְ נִדּוֹן הָאָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁהִטִּילוּ אֶת יוֹנָה לַיָּם מַה כָּתוּב? וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. הַיָּם הָעֶלְיוֹן. מַה זֶּה וַיַּעֲמֹד? שֶׁעָמַד בְּקִיּוּמוֹ כָּרָאוּי. הוּא בַּעֲמִידָה כְּשֶׁהָרֹגֶז שׁוֹכֵךְ. בְּשָׁעָה שֶׁהַדִּין שָׁרוּי בָּעוֹלָם, אוֹתוֹ בֵּית הַדִּין הוּא כְּמוֹ אִשָּׁה שֶׁמִּתְעַבֶּרֶת וּמַקְשָׁה לָלֶדֶת, וּכְשֶׁמּוֹלִידָה, שׁוֹכֵךְ הָרֹגֶז. כָּךְ גַּם כְּשֶׁהַדִּין שׁוֹרֶה בָּעוֹלָם, לֹא שׁוֹכֵךְ וְלֹא נָח עַד שֶׁנַּעֲשֶׂה הַדִּין בָּרְשָׁעִים, וְאָז הוּא הַמְּנוּחָה שֶׁלּוֹ, לַעֲמֹד בְּמָקוֹם שָׁלֵם וְלַעֲמֹד בְּקִיּוּמוֹ. זֶהוּ שֶׁכָּתוּב (משלי יא) וּבַאֲבֹד רְשָׁעִים רִנָּה. וְזֶה בֵּאַרְנוּ.</p>\n<p>בַּאֲבֹד רְשָׁעִים רִנָּה. וַהֲרֵי כָּתוּב (יחזקאל יח) הֶחָפֹץ אֶחְפֹּץ מוֹת רָשָׁע? וַהֲרֵי אֵין נַחַת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנַּעֲשֶׂה דִין בָּרְשָׁעִים? ! אֶלָּא כָּאן קֹדֶם שֶׁנִּשְׁלְמָה הַסְּאָה - וְכָאן אַחַר שֶׁנִּשְׁלְמָה הַסְּאָה (יש לו נחת).</p>"],[9522011253,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה. גּוּף הַמִּשְׁנָה, אָנוּ קְרוֹבִים הָיִינוּ, שָׁמַעְנוּ קוֹל מִתְהַפֵּךְ מִמַּעְלָה לְמַטָּה מִתְפַּשֵּׁט בָּעוֹלָם, קוֹל מְשַׁבֵּר הָרִים וּמְשַׁבֵּר סְלָעִים חֲזָקִים, רוּחוֹת חֲזָקוֹת עוֹלוֹת. אָזְנֵינוּ פְתוּחוֹת.</p>\n<p>הָיָה אוֹמֵר בְּמַסָּעָיו, אָקִיץ בְּקוֹץ הַיְשֵׁנִים הַדּוֹמְמִים. שֵׁנָה בְּחוֹרֵיהֶם (בעיניהם), עוֹמְדִים עַל עָמְדָּם. הַמֶּלֶךְ שֶׁמְּדַבֵּר, (ולא עברו, נמצאו) שׁוֹמְרֵי הַשְּׁעָרִים, שִׁלְטוֹן שֶׁל חֲיָלוֹת רַבִּים עוֹמֵד עַל עָמְדּוֹ.</p>\n<p>כֻּלָּם לֹא מַרְגִּישִׁים וְלֹא יוֹדְעִים שֶׁהַסֵּפֶר פָּתוּחַ וּבַשֵּׁם נִכְתָּבִים, וְדוּמָה עוֹמֵד וְנוֹטֵל בְּחֶשְׁבּוֹן, וְשׁוֹכְנֵי עָפָר שָׁבִים לַחוּץ, וְקָרֵב טוב לְהִמָּנוֹת בָּהֶם, אֵינָם חוֹשְׁקִים בְּגִּלְגּוּל וְהִפּוּךְ.</p>\n<p>נוֹפְלִים וְלֹא עוֹמְדִים, נִמְחִים הַחַיָּבִים מִסִּפְרוֹ שֶׁל דּוּמָה, מִי יְבַקֵּשׁ אוֹתָם וּמִי יֵשֵׁב בְּחֶשְׁבּוֹנוֹתֵיהֶם. אוֹי לָהֶם! אוֹי לְחַיֵּיהֶם! אוֹי לָרְגָשׁוֹת שֶׁלָּהֶם (לנפשותם) ! בִּשְׁבִילָם נֶאֱמַר (תהלים סט) יִמָּחוּ מִסֵּפֶר חַיִּים וְגוֹ'.</p>"],[9522011254,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה. מַה שּׁוֹנֶה כָּאן שֶׁכְּתוּבָה מִיתָתָהּ בַּתּוֹרָה מִכָּל נְשׁוֹת הָעוֹלָם שֶׁלֹּא כְתוּבָה כָּךְ מִיתָתָן בַּתּוֹרָה? אָמַר רַבִּי חִיָּיא, וְלֹא!? וְהִנֵּה כָּתוּב (בראשית לה) וַתָּמָת רָחֵל וַתִּקָּבֵר בְּדֶרֶךְ אֶפְרָתָה, וְכָתוּב (במדבר כ) וַתָּמָת שָׁם מִרְיָם וְגוֹ', וְכָתוּב (בראשית לה) וַתָּמָת דְּבוֹרָה מֵינֶקֶת רִבְקָה, וְכָתוּב (בראשית לח) וַתָּמָת בַּת שׁוּעַ אֵשֶׁת יְהוּדָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בְּכֻלָּם לֹא כָתוּב כְּמוֹ שֶׁכָּתוּב בְּשָׂרָה, שֶׁנֶּאֱמַר וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים שְׁנֵי חַיֵּי שָׂרָה. שֶׁהֲרֵי בְּכֻלָּם לֹא נִמְנוּ יָמִים וְשָׁנִים כְּמוֹ לְשָׂרָה, וּבְכֻלָּם לֹא כָתוּב פָּרָשָׁה אַחַת לְבַדָּהּ כְּמוֹ לְשָׂרָה. אֶלָּא סוֹד הוּא, מִשּׁוּם אוֹתָהּ הַדַּרְגָּה שֶׁכָּל הַיָּמִים וְהַשָּׁנִים שֶׁל אָדָם תְּלוּיִים בָּהּ (שזו היא ה\"א האחרונה).</p>\n<p>פָּתַח וְאָמַר, (קהלת ה) וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא מֶלֶךְ לְשָׂדֶה נֶעֱבָד. וְיִתְרוֹן אֶרֶץ בַּכֹּל הִיא וַדַּאי, שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת הָרוּחוֹת וְהַנְּשָׁמוֹת וְתוֹעֶלֶת לָעוֹלָם. מֶלֶךְ לְשָׂדֶה נֶעֱבָד, מִי הַמֶּלֶךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. לְשָׂדֶה נֶעֱבָד, כְּשֶׁהוּא נִתְקָן כָּרָאוּי. וּמֶלֶךְ זֶה הַמֶּלֶךְ הָעֶלְיוֹן שֶׁמִּתְחַבֵּר לַשָּׂדֶה כְּשֶׁהוּא נֶעֱבָד. מִי הַשָּׂדֶה? זֶה הַשָּׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', שֶׁכָּתוּב (בראשית כז) כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. שֶׁכְּשֶׁהוּא (נעשה) נֶעֱבָד וְנִתְקָן בְּכָל מַה שֶּׁצָּרִיךְ לוֹ כָּרָאוּי, אָז הַמֶּלֶךְ הָעֶלְיוֹן מִתְחַבֵּר עִמּוֹ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, מֶלֶךְ לְשָׂדֶה נֶעֱבָד - כַּמָּה גְוָנִים סוֹדוֹת עֶלְיוֹנִים כָּאן. מֶלֶךְ - זוֹ הַשְּׁכִינָה שֶׁאֵין שׁוֹרָה בַּבַּיִת לְהִתַּקֵּן בָּהּ אֶלָּא בִּזְמַן שֶׁנִּשָּׂא אָדָם וּמִזְדַּוֵּג עִם אִשְׁתּוֹ לְהוֹלִיד וְלַעֲשׂוֹת פֵּרוֹת, וְהִיא מוֹצִיאָה נְשָׁמוֹת לְהַשְׁרוֹת בָּהּ, וּמִשּׁוּם כָּךְ לְשָׂדֶה נֶעֱבָד וְלֹא לְאַחֵר.</p>\n<p>דָּבָר אַחֵר, מֶלֶךְ - זוֹ אִשָּׁה יִרְאַת ה', כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) אִשָּׁה יִרְאַת ה' הִיא תִתְהַלָּל. לְשָׂדֶה נֶעֱבָד - זוֹ אִשָּׁה זָרָה, כְּמוֹ שֶׁנֶּאֱמַר (שם ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה. מִשּׁוּם שֶׁיֵּשׁ שָׂדֶה וְיֵשׁ שָׂדֶה. יֵשׁ שָׂדֶה שֶׁכָּל הַבְּרָכוֹת וְהַקְּדֻשּׁוֹת בּוֹ שׁוֹרוֹת, כְּמוֹ שֶׁנֶּאֱמַר כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', וְיֵשׁ שָׂדֶה שֶׁכָּל חֻרְבָּן וְטֻמְאָה וְכִלָּיוֹן וְהֶרֶג וּקְרָבוֹת שְׁרוּיִים בּוֹ, וְהַמֶּלֶךְ הַזֶּה לִפְעָמִים שֶׁהוּא נֶעֱבָד לַשָּׂדֶה הַזּוֹ, שֶׁכָּתוּב (שם ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ' תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגוֹ' וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. וְהַמֶּלֶךְ הַזֶּה מִתְכַּסֶּה אוֹרוֹ וְנֶחְשָׁךְ עַד שֶׁנִּטְהָר וּמִתְחַבֵּר לְמַעְלָה.</p>\n<p>וּמִשּׁוּם כָּךְ הַשָּׂעִיר שֶׁל רֹאשׁ חֹדֶשׁ, מִשּׁוּם שֶׁנִּפְרָד הַשָּׂדֶה הַהוּא מִן הַמֶּלֶךְ הַקָּדוֹשׁ וְלֹא שׁוֹרוֹת בַּשָּׂדֶה הַזּוֹ בְּרָכוֹת מִן הַמֶּלֶךְ הַזֶּה. וּכְשֶׁהוּא נֶעֱבָד לַשָּׂדֶה הַזּוֹ, אָז כָּתוּב (דברים כב) כִּי בַשָּׂדֶה מְצָאָהּ וְגוֹ'. כִּי בַשָּׂדֶה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, בָּאָה חַוָּה לָעוֹלָם וְנִדְבְּקָה בַּנָּחָשׁ הַזֶּה, וְהִטִּיל בָּהּ זֻהֲמָה, וְגָרְמָה מָוֶת לָעוֹלָם וּלְבַעְלָהּ. בָּאָה שָׂרָה וְיָרְדָה וְעָלְתָה וְלֹא נִדְבְּקָה בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יג) וַיַּעַל אַבְרָם מִמִּצְרַיִם הוּא וְאִשְׁתּוֹ וְכָל אֲשֶׁר לוֹ. בָּא נֹחַ לָעוֹלָם, מַה כָּתוּב? (שם ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל וְגוֹ'.</p>\n<p>וּמִשּׁוּם שֶׁאַבְרָהָם וְשָׂרָה לֹא נִדְבְּקוּ בוֹ, מִשּׁוּם כָּךְ זָכְתָה לְחַיִּים עֶלְיוֹנִים לָהּ וּלְבַעְלָהּ וּלְבָנֶיהָ אַחֲרֶיהָ. זֶהוּ שֶׁכָּתוּב (ישעיה נא) הַבִּיטוּ אֶל צוּר חֻצַּבְתֶּם וְאֶל מַקֶּבֶת בּוֹר נֻקַּרְתֶּם. וְעַל כֵּן וַיִּהְיוּ חַיֵּי שָׂרָה, שֶׁזָּכְתָה בָהֶם בְּכֻלָּם. וְלֹא כָתוּב בְּכָל הַנָּשִׁים וַיִּהְיוּ חַיֵּי חַוָּה, וְכֵן בְּכֻלָּם. הִיא נִדְבְּקָה בַּחַיִּים, וְעַל כֵּן שֶׁלָּהּ הָיוּ הַחַיִּים.</p>"],[9522011255,"<p>אַשְׁרֵי מִי שֶׁמַּקְטִין אֶת עַצְמוֹ בָּעוֹלָם. כַּמָּה הוּא גָדוֹל וְעֶלְיוֹן בָּעוֹלָם הַהוּא. וְכָךְ פָּתַח רֹאשׁ הַיְשִׁיבָה: מִי שֶׁהוּא קָטָן - הוּא גָדוֹל. מִי שֶׁהוּא גָדוֹל - הוּא קָטָן. שֶׁכָּתוּב וַיִּהְיוּ חַיֵּי שָׂרָה וְגוֹ'. מֵאָה שֶׁהוּא חֶשְׁבּוֹן גָּדוֹל, כָּתוּב בּוֹ שָׁנָה. קֹטֶן הַשָּׁנִים אֶחָד הִקְטִין אוֹתוֹ. שֶׁבַע שֶׁהוּא חֶשְׁבּוֹן קָטָן, הִגְדִּיל אוֹתוֹ וְרִבָּה אוֹתוֹ, שֶׁכָּתוּב שָׁנִים. בֹּא רְאֵה שֶׁאֵינוֹ מְגַדֵל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְמִי שֶׁמַּקְטִין, וְלֹא מַקְטִין אֶלָּא לַמִּתְגַּדֵּל. אַשְׁרֵי הוּא מִי שֶׁמַּקְטִין אֶת עַצְמוֹ בָּעוֹלָם הַזֶּה, כָּה הוּא גָדוֹל בְּעִלּוּי לְאוֹתוֹ הָעוֹלָם. עַד כָּאן.</p>\n<p>מִי שֶׁפָּסַק יִפָּסֵק. מִי שֶׁקִּצֵּר יִתְקַצֵּר. מִי שֶׁקִּצֵּר יִתְאָרֵךְ. רְצוֹנוֹ לוֹמַר, מִי שֶׁפּוֹסֵק בְּדִבְרֵי תוֹרָה עַל דְּבָרִים בְּטֵלִים - יִפָּסְקוּ חַיָּיו מִן הָעוֹלָם הַזֶּה, וְדִינוֹ קַיָּם בָּעוֹלָם הַהוּא. מִי שֶׁמְּקַצֵּר בְּאָמֵן וְלֹא מַאֲרִיךְ תּוֹךְ מְנוּחָה - יִתְקַצֵּר מֵהַחַיִּים שֶׁל הָעוֹלָם הַזֶּה. מִי שֶׁאוֹמֵר אֶחָד, צָרִיךְ לַחְטֹף הָאָלֶ\"ף וּלְקַצֵּר אֶת הַקְּרִיאָה שֶׁלָּהּ, וְלֹא יִתְעַכֵּב בָּאוֹת הַזּוֹ כְּלָל, וּמִי שֶׁיַּעֲשֶׂה אֶת זֶה יִתְאָרְכוּ יָמָיו. (אלו החדושים שהגידו לרבי שמעון בר יוחאי בישיבה של מעלה,) ע\"כ התוספתא</p>"],[9522011256,"<p>וַיִּהְיוּ חַיֵּי שָׂרָה. אוֹתָם הַחַיִּים כֻּלָּם לְמַעְלָה. מֵאָה שָׁנָה לְמַעְלָה, וְעֶשְׂרִים שָׁנָה לְמַעְלָה, וְשֶׁבַע שָׁנִים לְמַעְלָה, כֻּלָּם הָיוּ כָּרָאוּי. אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה אֶת סוֹד הַדָּבָר, מַה שּׁוֹנֶה בְּכֻלָּם שֶׁאָמַר שָׁנָה שָׁנָה, וּבְאוֹתָם שֶׁבַע אָמַר שָׁנִים, שֶׁכָּתוּב מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה, וְאַחַר כָּךְ שֶׁבַע שָׁנִים?</p>\n<p>אֶלָּא הַכֹּל אֶחָד. מֵאָה שָׁנָה - הַכְּלָל שֶׁל הַכֹּל (נ\"א: הכל כאחד בסוד של מאה ברכות בכל יום, וכן עשרים שנה, שנכלל העליון, הנסתר של כל הנסתרים, ומשום כך כתוב שנה, הסוד של היחוד). הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּכְלָל מִמָּקוֹם עֶלְיוֹן, הַנִּסְתָּר שֶׁל כָּל הַנִּסְתָּרִים בְּמֵאָה, בְּסוֹד שֶׁל מֵאָה בְרָכוֹת שֶׁל כָּל יוֹם, וְכֵן עֶשְׂרִים שָׁנָה. וּמִשּׁוּם כָּךְ כָּתוּב שָׁנָה, סוֹד הַיִּחוּד, שֶׁלֹּא נִפְרָדִים הַמַּחֲשָׁבָה וְהַיּוֹבֵל לְעוֹלָמִים.</p>\n<p>שֶׁבַע הַשָּׁנִים הַלָּלוּ הִתְפָּרְדוּ וְיָצְאוּ מִכְּלַל הַנִּסְתָּר שֶׁלְּמַעְלָה. וְאַף עַל גַּב שֶׁהַכֹּל יִחוּד אֶחָד, אֲבָל נִפְרָדִים בְּדִין וְרַחֲמִים בְּכַמָּה צְדָדִים וּדְרָכִים מַה שֶּׁלֹּא הָיָה כָּךְ לְמַעְלָה. וּמִשּׁוּם כָּךְ כָּתוּב שָׁנָה, סוֹד הַיִּחוּד שֶׁלֹּא נִפְרָד לְעוֹלָמִים. שֶׁבַע הַשָּׁנִים הַלָּלוּ נִפְרָדִים בְּדִין וְרַחֲמִים בְּכַמָּה צְדָדִים וּדְרָכִים מַה שֶּׁאֵין כֵּן לְמַעְלָה. וּמִשּׁוּם כָּךְ בְּשֶׁבַע הַשָּׁנִים הַלָּלוּ כָּתוּב בָּהֶם שָׁנִים וְלֹא שָׁנָה. וְכֻלָּם נִקְרָאִים חַיִּים. וַיִּהְיוּ חַיֵּי שָׂרָה, שֶׁהָיוּ מַמָּשׁ, שֶׁנִּבְרְאוּ וְהִתְקַיְּמוּ לְמַעְלָה.</p>\n<p>אָמַר רַבִּי חִיָּיא, הִנֵּה פֵּרְשׁוּהָ, שֶׁהֲרֵי כַּאֲשֶׁר נֶעֱקַד יִצְחָק, הוּא הָיָה בֶּן שְׁלֹשִׁים וְשֶׁבַע שָׁנִים, וְכֵיוָן שֶׁנֶּעֱקַד, מֵתָה שָׂרָה, שֶׁכָּתוּב וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. מֵאַיִן בָּא? מֵהַר הַמֹּרִיָּה בָּא, מִלַּעֲקֹד אֶת יִצְחָק. וְאוֹתָם שְׁלֹשִׁים וְשֶׁבַע שָׁנִים מִיּוֹם שֶׁנּוֹלַד יִצְחָק וְעַד הַשָּׁעָה שֶׁנֶּעֱקַד, הֵם הָיוּ חַיֵּי שָׂרָה. וַדַּאי כְּחֶשְׁבּוֹן וַיִּהְי\"וּ בְּגִימַטְרִיָּא שְׁלֹשִׁים וְשֶׁבַע שָׁנִים הָיוּ, כְּמוֹ שֶׁנִּתְבָּאֵר, מִשֶּׁנּוֹלַד יִצְחָק וְעַד שֶׁנֶּעֱקַד.</p>"],[9522011257,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (תהלים צח) מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ הַחֲבֵרִים שֶׁהַפָּרוֹת אָמְרוּ אוֹתוֹ, כַּכָּתוּב (שמואל א ו) וַיִּשַּׁרְנָה הַפָּרוֹת בַּדֶּרֶךְ, שֶׁהָיוּ אוֹמְרוֹת שִׁירָה חֲדָשָׁה. וְאֵיזוֹ שִׁירָה הֵן אָמְרוּ? מִזְמוֹר שִׁירוּ לַה' שִׁיר חָדָשׁ כִּי נִפְלָאוֹת עָשָׂה.</p>\n<p>כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁכָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, כֻּלָּם אוֹמְרִים שִׁירָה וְתִשְׁבָּחוֹת לְפָנָיו, בֵּין לְמַעְלָה בֵּין לְמַטָּה. וְאִם תֹּאמַר שֶׁהֵם מֵעַצְמָם (ד\"א היו) אוֹמְרִים אֶת הַשִּׁירָה הַזּוֹ - כָּךְ זֶה וַדַּאי! שֶׁזֶּהוּ סוֹד עֶלְיוֹן. אֲבָל אֵלּוּ, הָאָרוֹן הָיָה עַל גַּבָּן. וְכֵיוָן שֶׁהָאָרוֹן נִשְׁקַל עֲלֵיהֶם וְשָׂמוּהוּ לְמַעְלָה, הֵן שָׁרוּ (נ\"א: לא שכבו) שִׁירָה, שֶׁהֲרֵי כֵּיוָן שֶׁנִּנְטַל מֵהֶן הָאָרוֹן, הָיוּ גוֹעוֹת כְּדֶרֶךְ שְׁאָר הַפָּרוֹת שֶׁל הָעוֹלָם וְלֹא אָמְרוּ שִׁירָה. וַדַּאי שֶׁהָאָרוֹן שֶׁעַל גַּבָּן עָשָׂה אוֹתָן לְזַמֵּר.</p>\n<p>מִזְמוֹר, הֲרֵי בֵּאַרְנוּ, וְנִתְבָּאֵר, וּבַכֹּל כָּתוּב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר, וְכָאן לֹא אָמַר דָּוִד כְּלָל. אֶלָּא מִזְמוֹר, שֶׁעֲתִידָה רוּחַ הַקֹּדֶשׁ לְזַמֵּר אוֹתוֹ בִּזְמַן שֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל מִן הֶעָפָר, וְאָז שִׁירוּ לַה' שִׁיר חָדָשׁ. אָז הוּא חָדָשׁ. שֶׁהֲרֵי שִׁירָה כָּזוֹ לֹא נֶאֶמְרָה מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם.</p>\n<p>אָמַר רַבִּי חִיָּיא, כָּתוּב (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ, וְכָאן שִׁירָה זוֹ הִיא חָדָשׁ, וְהִיא תַּחַת הַשֶּׁמֶשׁ, שֶׁהֲרֵי תַּחַת הַשֶּׁמֶשׁ הִיא, וּמִי הִיא? זוֹ הַלְּבָנָה. וְאָז יֵשׁ חָדָשׁ תַּחַת הַשָּׁמֶשׁ. מָה הַטַּעַם? מִשּׁוּם כִּי נִפְלָאוֹת עָשָׂה. וּמִי הֵם הַנִּפְלָאוֹת? זֶה שֶׁכָּתוּב הוֹשִׁיעָה לּוֹ יְמִינוֹ וּזְרוֹעַ קָדְשׁוֹ. הוֹשִׁיעָה לּוֹ, אֶת מִי? אֶת אוֹתָהּ הַדַּרְגָּה שֶׁאָמְרָה אֶת הַשִּׁירָה הַזּוֹ, מִשּׁוּם שֶׁבָּהֶם נִסְמְכָה בְּיָמִין וּבִשְׂמֹאל. הוֹשִׁיעָה לּוֹ יְמִינוֹ, וַדַּאי לְאוֹתָהּ הַדַּרְגָּה שֶׁל הַמִּזְמוֹר הַזֶּה. מָתַי? בִּזְמַן שֶׁיָּקוּמוּ מֵתֵי עוֹלָם וְיִתְעוֹרְרוּ מִן הֶעָפָר, וְאָז יִהְיֶה חָדָשׁ מַה שֶּׁלֹּא נַעֲשָׂה בָּעוֹלָם הַזֶּה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, בִּזְמַן שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמוֹת בָּעוֹלָם בִּשְׁבִיל יִשְׂרָאֵל, אָז תֵּאָמֵר הַשִּׁירָה (הזו), שֶׁהֲרֵי אַחַר כָּךְ יִתְעוֹרְרוּ מִן הֶעָפָר הַמֵּתִים שֶׁל הָעוֹלָם וְיִתְחַדֵּשׁ הָעוֹלָם בְּקִיּוּם שָׁלֵם, שֶׁלֹּא יִהְיֶה (כבתחלה שהמות שולט בעולם, משום שהנחש) (נ\"א: כרת ומיתה בעולם, ויעבר הנחש מהעולם שהוא גרם) גָּרַם מָוֶת בָּעוֹלָם לַכֹּל, וְנִטְמָא הָעוֹלָם וְנֶחְשְׁכוּ פָנָיו.</p>"],[9522011258,"<p>בֹּא רְאֵה, כָּתוּב (בראשית ג) וְאֵיבָה אָשִׁית בֵּינְךְ וּבֵין הָאִשָּׁה. מַה זֶּה וְאֵיבָה? כַּכָּתוּב (איוב ט) חָלְפוּ עִם אֳנִיּוֹת אֵבֶה. שֶׁהִנֵּה כַּמָּה אֳנִיּוֹת וּסְפִינוֹת מְשׁוֹטְטוֹת בְּתוֹךְ הַיָּם הַגָּדוֹל, וְיֵשׁ אֳנִיּוֹת וּסְפִינוֹת נִפְרָדוֹת זוֹ מִזּוֹ. וְאוֹתָן הָאֳנִיּוֹת שֶׁהַנָּחָשׁ הַזֶּה שָׁט בְּתוֹכָן, נִקְרָאוֹת אֳנִיּוֹת אֵבָה.</p>\n<p>בֵּינְךָ וּבֵין הָאִשָּׁה - זוֹ אִשָּׁה יִרְאַת ה'. וּבֵין זַרְעֲךְ - אֵלּוּ שְׁאָר עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבֵין זַרְעָהּ - אֵלּוּ יִשְׂרָאֵל. הוּא יְשׁוּפְךְ רֹאשׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעָתִיד לְבַעֵר אוֹתוֹ מִן הָעוֹלָם, שֶׁכָּתוּב (ישעיה כד) בִּלַּע הַמָּוֶת לָנֶצַח, וְכָתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ.</p>\n<p>רֹאשׁ - זֶה לֶעָתִיד לָבֹא כְּשֶׁיִּתְעוֹרְרוּ הַמֵּתִים, שֶׁהֲרֵי אָז הָעוֹלָם יִהְיֶה רֹא\"שׁ, שֶׁיִּתְקַיֵּם בָּרֹא\"שׁ, שֶׁהוּא הָעוֹלָם הָעֶלְיוֹן. וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב - זֶה בָּעוֹלָם הַזֶּה, כָּעֵת שֶׁהוּא עָקֵב וְאֵינוֹ בְּקִיּוּם, וְאוֹתוֹ הַנָּחָשׁ נוֹשֵׁךְ אֶת הָעוֹלָם וּמַחְשִׁיךְ פְּנֵי הַבְּרִיּוֹת.</p>\n<p>בֹּא רְאֵה, הַיָּמִים שֶׁל אָדָם נִבְרְאוּ וְעָמְדוּ בְּאוֹתָם הַדְּרָגוֹת הָעֶלְיוֹנוֹת, כֵּיוָן שֶׁהִסְתַּיְּמוּ לְהִתְקַיֵּם בְּאוֹתָן הַדְּרָגוֹת, שֶׁכָּתוּב (תהלים צ) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה וְגוֹ'. מִכָּאן וָהָלְאָה אֵין דַּרְגָּה לְהִתְקַיֵּם, וּמִשּׁוּם כָּךְ וְרָהְבָּ\"ם עָמָל וָאָוֶן, וְהֵם כְּלֹא הָיוּ.</p>\n<p>אֲבָל אוֹתָם הַיָּמִים שֶׁל הַצַּדִּיקִים הָיוּ וְהִתְקַיְּמוּ, כְּמוֹ שֶׁנֶּאֱמַר וַיִּהְיוּ חַיֵּי שָׂרָה, וְכֵן וְאֵלֶּה יְמֵי שְׁנֵי חַיֵּי אַבְרָהָם. וְאִם תֹּאמַר, כָּךְ גַּם כָּתוּב בְּיִשְׁמָעֵאל, שֶׁכָּתוּב (בראשית כה) שְׁנֵי חַיֵּי יִשְׁמָעֵאל? אֶלָּא שֶׁחָזַר בִּתְשׁוּבָה, וְעַל כֵּן קָרָא בְּיָמָיו וַיִּהְיוּ.</p>"],[9522011259,"<p>וַיִּהְיוּ, רַבּוֹתֵינוּ פָּתְחוּ בַּפָּסוּק הַזֶּה (שיר ז) לְכָה דוֹדִי נֵצֵא הַשָּׂדֶה נָלִינָה בַּכְּפָרִים. שָׁנוּ רַבּוֹתֵינוּ, הַיּוֹצֵא לַדֶּרֶךְ יִתְפַּלֵּל שָׁלֹשׁ תְּפִלּוֹת: תְּפִלָּה שֶׁהִיא חוֹבָה שֶׁל יוֹם, וּתְפִלַּת הַדֶּרֶךְ עַל הַדֶּרֶךְ שֶׁהוּא עוֹשֶׂה, וּתְפִלָּה שֶׁיַּחֲזר לְבֵיתוֹ לְשָׁלוֹם. וְיֹאמַר אֶת הַשְּׁלֹשָׁה הָאֵלּוּ, אֲפִלּוּ בְּאֶחָד יָכוֹל לַעֲשׂוֹתוֹ, שֶׁשָּׁנִינוּ, כָּל שְׁאֵלוֹתָיו שֶׁל אָדָם יָכוֹל לִכְלֹל אוֹתָן בְּשׁוֹמֵעַ תְּפִלָּה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל מַעֲשָׂיו שֶׁל אָדָם כְּתוּבִים בְּסֵפֶר, הֵן טוֹב וְהֵן רַע, וְעַל כֻּלָּם עָתִיד לָתֵת אֶת הַדִּין. שֶׁשָּׁנִינוּ, אָמַר רַב יְהוּדָה אָמַר רַב, מַה שֶּׁכָּתוּב (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךְ - אוֹתָם הַדְּבָרִים שֶׁעָשָׂה הַגֹּלֶם, שֶׁאֵינוֹ מַשְׁגִּיחַ בָּעוֹלָם הַבָּא, כֻּלָּם רָאוּ עֵינֶיךְ שֶׁעִיַּנְתָּ בָּהֶם. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ - לִתֵּן עֲלֵיהֶם דִּין וְחֶשְׁבּוֹן לָעוֹלָם הַבָּא. הִלְכָּךְ יַקְדִּים אָדָם תְּפִלָּתוֹ תָּמִיד וְיוֹעִיל לוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אֵין אָדָם עוֹשֶׂה עֲבֵרוֹת אֶלָּא מִי שֶׁהוּא גֹלֶם וְלֹא אָדָם, וְהַיְנוּ אוֹתוֹ שֶׁלֹּא מִסְתַּכֵּל בַּנְּשָׁמָה הַקְּדוֹשָׁה, אֶלָּא כָּל מַעֲשָׂיו כַּבְּהֵמָה הַזּוֹ שֶׁאֵין מַשְׁגַּחַת וְאֵין יוֹדַעַת. אָמַר רַבִּי בּוֹ, וְכִי גֹלֶם נִקְרָא דָוִד שֶׁאָמַר אֶת הַפָּסוּק הַזֶּה? אָמַר לוֹ רַבִּי יִצְחָק, אָדָם הָרִאשׁוֹן אֲמָרוֹ, גָּלְמִי רָאוּ עֵינֶיךְ. קֹדֶם שֶׁזָּרַקְתָּ בִּי נְשָׁמָה, רָאוּ עֵינֶיךְ לַעֲשׂוֹת בִּדְמוּתִי בְּנֵי אָדָם שֶׁיִּדְמוּ לִי. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ, מִי הֵם? יָמִים יֻצָּרוּ, בַּצּוּרָה הַזּוֹ שֶׁלִּי. וְלֹא אֶחָד בָּהֶם, שֶׁלֹּא נִשְׁאָר אֶחָד מֵהֶם.</p>\n<p>אָמַר רַבִּי בּו, לָמָּה? אָמַר לוֹ, בֹּא רְאֵה, כֻּלָּם שֶׁדָּמוּ לוֹ אוֹ בְּרֶמֶז שֶׁלּוֹ, לֹא מֵתוּ בְּמִיתַת נַפְשָׁם, וְכֻלָּם לָקוּ בְּאוֹתוֹ עִנְיָן מַמָּשׁ. בֹּא רְאֵה, אָמַר רַבִּי יְהוּדָה, דְּמוּתוֹ שֶׁל אָדָם הָרִאשׁוֹן וְיָפְיוֹ הָיָה כְּזֹהַר הָרָקִיעַ הָעֶלְיוֹן שֶׁעַל גַּבֵּי שְׁאָר הָרְקִיעִים, וּכְאוֹתוֹ הָאוֹר שֶׁגָּנַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים לָעוֹלָם הַבָּא. וְכָל אוֹתָם שֶׁהָיוּ רְמוּזִים בּוֹ מִדְּמוּתוֹ שֶׁל אָדָם הָרִאשׁוֹן, בּוֹ הֵם לָקוּ וּמֵתוּ.</p>\n<p>שֶׁכָּךָ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - נוֹתֵן עֹשֶׁר לָאָדָם, לָמָּה? לָזוּן אֶת הָעֲנִיִּים וְלַעֲשׂוֹת מִצְווֹתָיו. אֵינוֹ עוֹשֶׂה אֶת זֶה וּמִתְגָּאֶה (ואם נתגלה בו) בָּעֹשֶׁר הַהוּא - בּוֹ יִלְקֶה, שֶׁכָּתוּב (קהלת ה) עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. נוֹתֵן לוֹ בָּנִים, לָמָּה? לְלַמֵּד אוֹתָם דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר מִצְווֹתָיו, כְּמוֹ שֶׁאָמוּר בְּאַבְרָהָם (בראשית יח) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת כָּל בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶרֶךְ ה' לַעֲשׂוֹת צְדָקָה וְגוֹ'. הוּא לֹא עוֹשֶׂה אֶת זֶה וּמִתְגָּאֶה בָהֶם - בָּהֶם הוּא לוֹקֶה, שֶׁכָּתוּב (איוב יח) לֹא נִין לוֹ וְלֹא נֶכֶד בְּעַמּוֹ וְגוֹ'. וְכֵן כְּמוֹ זֶה, כְּשֶׁנּוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מִיפִי טוּב עֶלְיוֹן שֶׁל אָדָם הָרִאשׁוֹן לָהֶם, לָמָּה? כְּדֵי לִשְׁמֹר מִצְווֹתָיו וְלַעֲשׂוֹת רְצוֹנוֹ. לֹא עָשׂוּ כָּךְ אֶלָּא הִתְגָּאוּ בוֹ - בּוֹ לוֹקִים, בַּיֹּפִי הַזֶּה.</p>\n<p>אָמַר רַב יְהוּדָה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אָדָם הָרִאשׁוֹן, הָיָה גֹלֶם טֶרֶם שֶׁזָּרַק בּוֹ נְשָׁמָה, וְקָרָא לְאוֹתוֹ הַמַּלְאָךְ הַמְמֻנֶּה עַל צוּרוֹת בְּנֵי אָדָם, וְאָמַר לוֹ: עַיֵּן וְצֹר בַּדְּמוּת הַזּוֹ שִׁשָּׁה בְּנֵי אָדָם. זֶהוּ שֶׁכָּתוּב (בראשית ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, כְּלוֹמַר שִׁתָּא שֵׁשׁ.</p>\n<p>אָמַר רַבִּי יִצְחָק, מֵאוֹתוֹ עָפָר מַמָּשׁ שֶׁנִּבְרָא אָדָם הָרִאשׁוֹן, לָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת שֵׁשֶׁת אֵלֶּה, וְקָרָא לוֹ שֵׁת שֵׁשׁ. זֶהוּ שֶׁכָּתוּב וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, מֵאוֹתָהּ הָעִסָּה שֶׁנִּבְרָא הַגֹּלֶם שֶׁלּוֹ. וְעַל כָּךְ נֶאֱמַר גָּלְמִי רָאוּ עֵינֶיךְ, וְעִיַּנְתָּ בּוֹ לַעֲשׂוֹת (בו) שֶׁדּוֹמִים לוֹ. וְעַל סִפְרְךְ כֻּלָּם יִכָּתֵבוּ, מִי הֵם? כֻּלָּם שֶׁלֹּא שָׁמְרוּ מַה שֶּׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לָהֶם וְנִטְרְדוּ מִן הָעוֹלָם (ונדונו באותו הדין).</p>\n<p>שָׁנִינוּ שָׁם, אָמַר רַב יְהוּדָה אָמַר רַב, מָצָאנוּ שֶׁשָּׁלֹשׁ מִשְׁמָרוֹת הוּא הַלַּיְלָה, וּלְכָל אֶחָד וְאֶחָד יֵשׁ עִנְיָן לַקָּבָּ\"ה בָּאָדָם, כְּשֶׁיּוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ וְנִשְׁאָר אוֹתוֹ גֹלֶם יָשֵׁן עַל מִטָּתוֹ, וְנִשְׁמָתוֹ עוֹלָה בְּכָל לַיְלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר רַבִּי יִצְחָק, אִם הִיא צַדִּיקָה - שְׂמֵחִים עִמָּהּ, וְאִם לֹא - דּוֹחִים אוֹתָהּ הַחוּצָה. אָמַר רַב יְהוּדָה אָמַר רַב, מַה שֶּׁכָּתוּב (שיר ה) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי.</p>\n<p>אָמַר רַבִּי פִּנְחָס אָמַר רַבִּי יְהוּדָה, הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם - הַנְּשָׁמָה אוֹמֶרֶת לְאוֹתָם הַנְּשָׁמוֹת הַזּוֹכוֹת לְהִכָּנֵס לִירוּשָׁלַיִם שֶׁל מַעְלָה, וְהֵם הַנִּקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם עַל שֶׁזּוֹכוֹת לִכָּנֵס שָׁם, וּלְפִיכָךְ הַנְּשָׁמָה אוֹמֶרֶת לָהֶם הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁ לם, אִם תִּמְצְאוּ אֶת דּוֹדִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַב אָמַר, זֶה זִיו הָאַסְפַּקְלַרְיָה שֶׁל מַעְלָה. מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי, לֵהָנוֹת מֵהַזִּיו שֶׁלּוֹ וּלְהִסְתּוֹפֵף בְּצִלּוֹ. רַב הוּנָא אָמַר, שֶׁחוֹלַת אַהֲבָה אָנִי - אוֹתָהּ הַתְּשׁוּקָה וְהַכִּסּוּף שֶׁכָּסַפְתִּי בָּעוֹלָם עַל הַכֹּל, לְפִיכָךְ אֲנִי חוֹלָה. רַבִּי יְהוּדָה אָמַר, זוֹ אַהֲבָה שֶׁאוֹהֶבֶת הַנְּשָׁמָה לַגּוּף. שֶׁכֵּיוָן שֶׁנִּשְׁלָם קִצּוֹ שֶׁל גּוּף, אוֹתָם הַיָּמִים שֶׁנִּגְזְרוּ עָלָיו, כְּמוֹ שֶׁנֶּאֱמַר וַיִּהְיוּ חַיֵּי שָׂרָה, מַה כָּתוּב? וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וְגוֹ'.</p>\n<p>אָמַר רַב יְהוּדָה אָמַר רַב, מַה כָּתוּב בַּפָּסוּק קֹדֶם זֶה? שֶׁכָּתוּב וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאֶרֶץ כְּנָעַן.</p>\n<p>רַבִּי יִצְחָק אָמַר רַבִּי יוֹחָנָן, בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם וְהִכְנִיס בּוֹ אַרְבָּעָה דְבָרִים הַנֶּחֱלָקִים בַּגּוּף. אָמַר רַבִּי יְהוּדָה, הַמְחֻבָּרִים בַּגּוּף. רַבִּי יִצְחָק אָמַר הַנֶּחֱלָקִים בַּגּוּף, שֶׁהֵם חוֹלְקִים לְהִתְפָּרֵשׁ כָּל אֶחָד לִיסוֹדוֹ כְּשֶׁיּוֹצֵא הָאָדָם מִן הָעוֹלָם הַזֶּה. רַבִּי יְהוּדָה אָמַר, הַמְחֻבָּרִים בַּגּוּף בְּחַיָּיו, מַשְׁמָע מֵהַפָּסוּק שֶׁכָּתוּב וַתָּמָת שָׂרָה - זֶה הַגּוּף. בְּקִרְיַת אַרְבַּע - אֵלּוּ אַרְבָּעָה הַיְסוֹדוֹת. הִיא חֶבְרוֹן - שֶׁהָיוּ מְחֻבָּרִים בְּגוּפוֹ בְּחַיָּיו. בְּאֶרֶץ כְּנָעַן - בָּעוֹלָם הַזֶּה הַבּוֹחֵר אָדָם בִּזְמַן מוּעָט.</p>"],[9522011260,"<p>וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. הַיְנוּ (שכתוב) שֶׁשָּׁנִינוּ, כָּל שִׁבְעַת הַיָּמִים נַפְשׁוֹ שֶׁל אָדָם פּוֹקֶדֶת לְגוּפוֹ וּמִתְאַבֶּלֶת עָלָיו. זֶהוּ שֶׁכָּתוּב (איוב יד) אַךְ בְּשָׂרוֹ עָלָיו יִכְאָב וְנַפְשׁוֹ עָלָיו תֶּאֱבָל. כְּמוֹ זֶה, וַיָּבא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ. וַיָּבא אַבְרָהָם - זוֹ הִיא הַנְּשָׁמָה. לִסְפֹּד לְשָׂרָה - זֶה הַגּוּף.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהַנְּשָׁמָה זוֹכָה וְעוֹלָה לִמְקוֹם מַעֲלָתָהּ, הַגּוּף שׁוֹכֵב בְּשָׁלוֹם וְיָנוּחַ עַל מִשְׁכָּבוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה נז) יָבוֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם הֹלֵךְ נְכֹחוֹ. מַה זֶּה הֹלֵךְ נְכֹחוֹ אָמַר רַבִּי יִצְחק, הַנְּשָׁמָה הֹלֵךְ נְכֹחוֹ לִמְקוֹם הָעֵדֶן הַגָּנוּז לָהּ. מַה מַּשְׁמִיעַ? אָמַר רַבִּי יְהוּדָה, מִזֶּה נִשְׁמָע נְכֹחֹה כָּתוּב בְּהֵ\"א. וּבְשָׁעָה שֶׁאֵינָהּ זוֹכָה, וְהִיא רְאוּיָה לְקַבֵּל עָנְשָׁהּ, הוֹלֶכֶת מְשׁוֹמֶמֶת וּמְבַקֶּרֶת בְּכָל יוֹם אֶת הַגּוּף וְאֶת הַקֶּבֶר.</p>\n<p>אָמַר רַבִּי יוֹסֵי, עֶצֶם הַקּוּלִית (ירך) הַקָּשֶׁה הַזֶּה, כְּשֶׁהוֹלֵךְ בִּסְרִיחוּת לְכָאן וּלְכָאן, הוֹלֵךְ וּמְבַקֵּר אֶת מְקוֹמוֹ שְׁנֵים עָשָׂר חֳדָשִׁים. כָּךְ הַנְּשָׁמָה הַהִיא שֶׁרְאוּיָה לְקַבֵּל עֹנֶשׁ, הוֹלֶכֶת בַּחוּץ בָּעוֹלָם, וּפוֹקֶדֶת אֶת מְקוֹמָהּ שְׁנֵים עָשָׂר חֳדָשִׁים בְּבָתֵּי הַקְּבָרוֹת וּבָעוֹלָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה שֶׁכָּתוּב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וְגוֹ'. אָמַר רַבִּי אַבָּא, וַהֲרֵי שָׁנִינוּ שֶׁכַּאֲשֶׁר הַנְּשָׁמָה הִיא בִּשְׁלֵמוּת עֶלְיוֹנָה, נוֹסֶפֶת לָהּ הֵ\"א, וְנִקְרֵאת אַבְרָהָם בִּשְׁלֵמוּת עֶלְיוֹנָה, וְכָאן אַתָּה אוֹמֵר כַּאֲשֶׁר אֵינוֹ צַדִּיק כָּל כָּךְ, שֶׁכָּתוּב וַיָּקָם אַבְרָהָם. עָשִׂיתָ שֶׁמִּי שֶׁיּוֹשֵׁב בְּכִסֵּא יוֹרֵד לְתוֹךְ קָטָן תַּחְתּוֹן</p>\n<p>אֶלָּא כָּךְ גָּזַרְתִּי - וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ. שֶׁאָמַר רַבִּי בּוֹ אָמַר רַבִּי זְרִיקָא, כְּשֶׁהַנְּשָׁמָה רְאוּיָה לַעֲלוֹת לִמְקוֹם עִדְנָהּ, קֹדֶם מְגִנָּה עַל הַגּוּף הַקָּדוֹשׁ שֶׁיּוֹצֵאת מִשָּׁם, וְאַחַר כָּךְ עוֹלָהּ לִמְקוֹם מַעֲלָתָהּ. זֶהוּ שֶׁכָּתוּב וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ, זֶה הַגּוּף.</p>\n<p>וַיְדַבֵּר אֶל בְּנֵי חֵת - אֵלּוּ שְׁאָר גּוּפוֹת הַצַּדִּיקִים שֶׁהֵם (ד\"א בני) חַתְחַתִּים וְנֶהֱלָמִים בָּעוֹלָם לְמַעַן יִרְאַת קוֹנָם, חִתִּים עַל שֶׁהֵם שׁוֹכְנֵי עָפָר. וְלָמָּה צְרִיכָה אוֹתָם? אָמַר רַבִּי יְהוּדָה, הַכֹּל כְּתוּבִים בְּמִנְיָן, וְעַל (שהיה, ד\"א זה היה אותו) הַגּוּף בְּמִנְיָן עִמָּהֶם. וּמָה אָמַר לָהֶם בְּדֶרֶךְ פִּיּוּס וּבְדֶרֶךְ כָּבוֹד?</p>\n<p>גֵּר וְתוֹשָׁב אָנֹכִי עִמָּכֶם וְגוֹ'. שֶׁהַגּוּף הַזֶּה יִהְיֶה בְמִנְיָן אֶחָד עִמָּכֶם בַּחִבּוּר הַזֶּה. אָמַר רַבִּי, רְאֵה מַה כָּתוּב, וַיַּעֲנוּ בְנֵי חֵת אֶת אַבְרָהָם וְגוֹ'. כְּמוֹ כֵן בְּדֶרֶךְ כָּבוֹד, בְּדֶרֶךְ פִּיּוּס. זֶהוּ שֶׁכָּתוּב שְׁמָעֵנוּ אֲדנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ.</p>"],[9522011261,"<p>מַה זֶה נְשִׂיא אֱלֹהִים אַתָּה? אָמַר רַבִּי פִּנְחָס, קֹדֶם שֶׁיָּצָא הַצַּדִּיק מִן הָעוֹלָם, בַּת קוֹל יוֹצֵאת בְּכָל יוֹם עַל אוֹתָם הַצַּדִּיקִים בְּגַן עֵדֶן: הָכִינוּ מָקוֹם לִפְלוֹנִי שֶׁיָּבא לְכָאן. וְעַל כֵּן הֵם אוֹמְרִים, מֵאֵת אֱלֹהִים מִלְמַעְלָה אַתָּה נָשִׂיא בְּכָל יוֹם בְּתוֹכֵנוּ. בְּמִבְחַר קְבָרֵינוּ, בְּמִבְחַר הַצַּדִּיקִים, בַּחֲבוּרַת הַצַּדִּיקִים הַמֻּבְחָרִים מְנֵה אוֹתוֹ, הַכְנִיסֵהוּ בְּחֶשְׁבּוֹן עִמָּנוּ, וְאִישׁ מִמֶּנּוּ לֹא יִמְנַע אֶת הַמִּנְיָן, כִּי כֻלָּנוּ שְׂמֵחִים בּוֹ וּמַקְדִימִים לוֹ שָׁלוֹם.</p>\n<p>אָמַר רַבִּי יוֹסֵי בֶּן פַּזִּי, בּא רְאֵה, כֵּיוָן שֶׁהַנְּשָׁמָה פּוֹגַעַת בָּהֶם וְתִדּוֹן, לְאַחַר כָּךְ פּוֹגַעַת לְאוֹתוֹ הַמַּלְאָךְ הַמְמֻנֶּה עֲלֵיהֶם. שֶׁשָּׁנִינוּ, מַלְאָךְ הַמְמֻנֶּה עַל בָּתֵּי הַקְּבָרוֹת וְדוּמָה שְׁמוֹ, וְהוּא מַכְרִיז בֵּינֵיהֶם בְּכָל יוֹם עַל הַצַּדִּיקִים הָעֲתִידִים לִכָּנֵס בֵּינֵיהֶם, וּמִיָּד פּוֹגַעַת בּוֹ כְּדֵי לְשַׁכֵּן הַגּוּף בְּהַשְׁקֵט וּבְבִטְחָה וּבִמְנוּחָה וּבַהֲנָאָה (עליונה). זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֶל עֶפְרוֹן.</p>\n<p>אָמַר רַבִּי יֵיסָא, זֶה הַמַּלְאָךְ הַנִּקְרָא דוּמָה. וְלָמָּה נִתְכַּנֶּה שְׁמוֹ עֶפְרוֹן? עַל שֶׁהוּא מְמֻנֶּה עַל שׁוֹכְנֵי עָפָר, וְהֻפְקְדוּ בְיָדוֹ כָּל פִּנְקְסֵי הַצַּדִּיקִים וַחֲבוּרוֹת הַחֲסִידִים הַשּׁוֹכְנִים בֶּעָפָר, וְהוּא עָתִיד לְהוֹצִיאָם בְּחֶשְׁבּוֹן.</p>\n<p>וְלָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, לֶעָתִיד לָבא כְּשֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, יִקְרָא לַמַּלְאָךְ הַמְמֻנֶּה עַל הַקְּבָרוֹת, וְדוּמָה שְׁמוֹ, וְיִתְבַּע מִמֶּנּוּ מִנְיַן כָּל הַמֵּתִים הַצַּדִּיקִים וְהַחֲסִידִים וְאוֹתָם גֵּרֵי הַצֶּדֶק וְשֶׁנֶּהֶרְגוּ עַל שְׁמוֹ, וְהוּא מוֹצִיאָם בְּחֶשְׁבּוֹן כְּמוֹ שֶׁנְּטָלָם בְּחֶשְׁבּוֹן. זֶהוּ שֶׁכָּתוּב (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ' אִישׁ לֹא נֶעְדָּר.</p>\n<p>וְלָמַדְנוּ, אָמַר רַבִּי שְׁמוּאֵל בְּרַבִּי יַעֲקֹב, נַפְשׁוֹת הָרְשָׁעִים נְתוּנוֹת בְּיָדוֹ שֶׁל מַלְאָךְ זֶה שֶׁשְּׁמוֹ דוּמָה לְהַכְנִיסָם בַּגֵּיהִנֹּם וְלָדוּן שָׁם. וְכֵיוָן שֶׁנִּמְסָרוֹת בְּיָדוֹ, שׁוּב אֵינָן חוֹזְרוֹת, עַד שֶׁיִּכָּנְסוּ לַגֵּיהִנֹּם. וְזֶה יִרְאַת דָּוִד שֶׁנִּתְיָרֵא כְּשֶׁעָשָׂה אוֹתוֹ עָוֹן, שֶׁנֶּאֱמַר (תהלים צד) לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. אָמַר רַבִּי יֵיסָא, הַנְּשָׁמָה פּוֹגַעַת לוֹ לְהַכְנִיס אוֹתוֹ גוּף עִם שְׁאָר גּוּפוֹת הַצַּדִּיקִים בְּחֶשְׁבּוֹנָם. זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר אֶל עֶפְרוֹן וְגוֹ'.</p>\n<p>אָמַר רַבִּי תַּנְחוּם, הַמַּלְאָךְ קוֹדֵם וְאוֹמֵר לוֹ: רְאֵה מַה כָּתוּב לְמַעְלָה - וְעֶפְרוֹן יֹשֵׁב בְּתוֹךְ בְּנֵי חֵת. שִׁחֲתוֹ לִשְׁכֹּן בֶּעָפָר, וְהוּא מַקְדִּים וְאוֹמֵר לוֹ לְהַכְנִיס אוֹתוֹ הַגּוּף בְּחֶשְׁבּוֹן הַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב וַיַּעַן עֶפְרוֹן הַחִתִּי אֶת אַבְרָהָם בְּאָזְנֵי בְנֵי חֵת לְכָל בָּאֵי שַׁעַר עִירוֹ לֵאמֹר. מַה זֶּה לְכֹל בָּאֵי שַׁעַר עִירוֹ? רַב נַחְמָן אָמַר, אוֹתָם שֶׁנִּכְנְסוּ בִּכְתַב חֶשְׁבּוֹן פִּנְקָסוֹ. שֶׁאָמַר רַב נַחְמָן, וְכָךְ נִגְזַר (על) חֶשְׁבּוֹן, עַל יַד דּוּמָה נִכְנָסִים לְבָתֵּי הַקְּבָרוֹת, וּבְחֶשְׁבּוֹן הַפֶּתֶק עָתִיד לְהוֹצִיא אוֹתָם, וְהוּא מְמֻנֶּה עַל שׁוֹכְנֵי הֶעָפָר.</p>\n<p>מַה זֶּה הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אַשֶׁר בּוֹ? אָמַר רַבִּי יוֹסֵי, אוֹצָר שֶׁל שַׁלְוָה וּמְנוּחָה רַבָּה. אָמַר רַבִּי שָׁלוֹם בַּר מִנְיוֹמֵי, אֵין לְךְ כָּל צַדִּיק צַדִּיק מֵאוֹתָם הָעוֹסְקִים בַּתּוֹרָה שֶׁאֵין לוֹ מָאתַיִם עוֹלָמוֹת וְכִסּוּפִים בּשְׁבִיל הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שיר ח) וּמָאתַיִם לְנֹטְרִים אֶת פִּרְיוֹ. וּמָאתַיִם עַל שֶׁמּוֹסְרִים עַצְמָם בְּכָל יוֹם כְּאִלּוּ הֶרְגוּ עַל קְדֻשַּׁת שְׁמוֹ, וְנִצְּחוֹ כְּמוֹ הַפָּסוּק הַזֶּה. (וכך אמרו בפסוק הזה) שֶׁכָּתַב וְאָהַבְתָּ אֵת ה' וְגוֹ'. לָמַדְנוּ, כָּל הַמְכַוֵּן אֶת לִבּוֹ בַּפָּסוּק הַזֶּה כְּדֵי לִמְסֹר נַפְשׁוֹ עַל קְדֻשַּׁת שְׁמוֹ, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ הֱרָג בְּכָל יוֹם עָלָיו. זֶהוּ שֶׁכָּתוּב (תהלים מד) כי עליך הרגנו כל היום. אמר רב נחמן, כל המוסר נפשו בפסוק זה, נוחל ארבע מאות עולמות לעולם הבא. אמר רב וסף, והרי שנינו מאתים? אמר רב חמן, מאתים על התורה - ומאתם על שמסר עצמו בכל יום על קדשת שמו.</p>"],[9522011262,"<p>וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע. רַבִּי אַבָּא אָמַר, כְּמוֹ זֶה לֹא הָיוּ בְּכָל נְשׁוֹת הָעוֹלָם, שֶׁהֲרֵי נֶאֱמַר חֶשְׁבּוֹן יָמֶיהָ וּשְׁנוֹתֶיהָ וְקִיּוּמָהּ בָּעוֹלָם וְאוֹתוֹ הַמָּקוֹם שֶׁבּוֹ הִיא נִקְבְּרָה. אֶלָּא לְהַרְאוֹת שֶׁלֹּא הָיְתָה כְּמוֹ שָׂרָה בְּכָל נְשׁוֹת הָעוֹלָם.</p>\n<p>וְאִם תֹּאמַר הִנֵּה מִרְיָם, שֶׁכָּתוּב (במדבר כ) וַתָּמָת שָׁם מִרְיָם וַתִּקָּבֵר שָׁם - זֶה בָּא לְהַרְאוֹת אֶת סִרְחוֹנָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי הַמַּיִם לֹא הָלְכוּ בְּיִשְׂרָאֵל אֶלָּא בִּזְכוּת מִרְיָם. אֲבָל לֹא נֶאֱמַר בְּמִיתָתָהּ כְּמוֹ שֶׁנֶּאֱמַר בְּשָׂרָה.</p>\n<p>רַבִּי יְהוּדָה פָּתַח, (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ הַחֲבֵרִים, אֲבָל יֵשׁ לָנוּ לְהִסְתַּכֵּל בּוֹ, שֶׁאַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה לָדַעַת כָּל הַדְּרָכִים הַנִּסְתָּרוֹת וּלְגַלּוֹת לָהֶם סוֹדוֹת עֶלְיוֹנִים, וַהֲרֵי זֶה נִתְבָּאֵר.</p>\n<p>אַשְׁרֵיךָ אֶרֶץ - זוֹ אֶרֶץ הַחַיִּים, מִשּׁוּם שֶׁהַמֶּלֶךְ שֶׁלָּהּ מַזְמִין לָהּ כָּל הַבְּרָכוֹת שֶׁהִתְבָּרְכָה מֵהָאָבוֹת הָעֶלְיוֹנִים, הַסּוֹד שֶׁל וָא\"ו, שֶׁהוּא עוֹמֵד לְהָרִיק עָלֶיהָ בְּרָכוֹת תָּמִיד, וְהוּא בֶּן חוֹרִים, בֶּן הַיּוֹבֵל שֶׁמּוֹצִיא אֶת הָעֲבָדִים לְחֵרוּת, בֶּן הָעוֹלָם הָעֶלְיוֹן שֶׁמּוֹצִיא תָמִיד אֶת כָּל הַחַיִּים וְכָל הָאוֹר וְכָל שֶׁמֶן מִשְׁחָה, וְהַכֹּל מַשְׁפִּיעַ הַבֵּן הַבְּכוֹר הַזֶּה לָאָרֶץ הַזּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) בְּנִי בְּכֹרִי יִשְׂראֵל, וּמִשּׁוּם כָּךְ אַשְׁרֵי\"ךְ אֶרֶץ.</p>\n<p>וּמַה שֶּׁנֶּאֱמַר אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁהָאָרֶץ הַתַּחְתּוֹנָה הַזּוֹ וְהָעוֹלָם הָעֶלְיוֹן לֹא יוֹנְקִים אֶלָּא מִתּוֹךְ שִׁלְטוֹן (של מעלה) שֶׁל הָעָרְלָה, וְהַכֹּל מֵאוֹתוֹ הַמֶּלֶךְ שֶׁנִּקְרָא נַעַר, כְּמוֹ שֶׁבֵּאֲרוּהָ - אוֹי לְאֶרֶץ שֶׁצְּרִיכָה לִינֹק כָּךְ.</p>\n<p>בֹּא רְאֵה, הַנַּעַר הַזֶּה אֵין לוֹ מֵעַצְמוֹ כְּלוּם, רַק כְּשֶׁנּוֹטֵל בְּרָכוֹת לְעִתִּים יְדוּעִים, וְכָל הַפְּעָמִים שֶׁנִּמְנְעוּ מִמֶּנּוּ, וְנִפְגְּמָה הַלְּבָנָה וְנֶחְשֶׁכֶת, וְהַבְּרָכוֹת נִמְנָעוֹת מִמֶּנּוּ. אוֹי לָעוֹלָם שֶׁצָּרִיךְ לִינֹק בַּשָּׁעָה הַזּוֹ. וְעוֹד, בְּכַמָּה דִינִים נִדּוֹן הָעוֹלָם הַזֶּה טֶרֶם יוֹנֵק מִמֶּנּוּ, שֶׁהַכֹּל מִתְקַיֵּם בְּדִין וְנַעֲשָׂה, וְנִתְבָּאֵר (כך).</p>\n<p>בֹּא רְאֵה, וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע - סוֹד הוּא, מִשּׁוּם שֶׁלֹּא הָיְתָה מִיתָתָהּ עַל יְדֵי אוֹתוֹ הַנָּחָשׁ עֲקַלָּתוֹן, וְלֹא שָׁלַט בָּהּ כְּמוֹ שְׁאָר בְּנֵי הָעוֹלָם שֶׁשּׁוֹלֵט בָּהֶם, וְעַל יָדוֹ מֵתוּ בְּנֵי הָעוֹלָם מִיּוֹם שֶׁגָּרַם לָהֶם אָדָם, פְּרָט לְמֹשֶׁ\"ה וְאַהֲרֹ\"ן וּמִרְיָ\"ם, שֶׁכָּתוּב בָּהֶם עַל פִּי ה'. וּמִשּׁוּם כְּבוֹד הַשְּׁכִינָה לֹא כָתוּב בְּמִרְיָם עַל פִּי ה'.</p>\n<p>אֲבָל בְּשָׂרָה כָּתוּב בְּקִרְיַת אַרְבַּע. הַסּוֹד שֶׁל קִרְיַת אַרְבַּע בְּסוֹד עֶלְיוֹן, וְלֹא עַל יְדֵי אַחֵר. בְּקִרְיַת אַרְבַּע, וְלֹא בְּנָחָשׁ. בְּקִרְיַת אַרְבַּע, הִיא חֶבְרוֹן. שֶׁהִתְחַבֵּר דָּוִד הַמֶּלֶךְ עִם הָאָבוֹת, וְעַל כֵּן לֹא הָיְתָה מִיתָתָהּ בְּיַד אַחֵר אֶלָּא בְּקִרְיַת אַרְבַּע.</p>\n<p>בֹּא רְאֵה, כַּאֲשֶׁר הַיָּמִים שֶׁל אָדָם הִתְקַיְּמוּ בִּדְרָגוֹת עֶלְיוֹנוֹת, מִתְקַיֵּם הָאָדָם בָּעוֹלָם. כֵּיוָן שֶׁלֹּא מִתְקַיֵּם בַּדְּרָגוֹת הָעֶלְיוֹנוֹת, יוֹצְאִים וְיוֹרְדִים לְמַטָּה, עַד שֶׁקְּרֵבִים לַדַּרְגָּה הַזּוֹ שֶׁבָּהּ שׁוֹרָה הַמָּוֶת. וְאָז נוֹטֶלֶת רְשׁוּת לְהוֹצִיא הַנְּשָׁמָה, וְטָסָה הָעוֹלָם בְּפַעַם אַחַת וְנוֹטֶלֶת הַנְּשָׁמָה, וּמְטַמֵּא אֶת הַגּוּף וְנִשְׁאָר טָמֵא. אַשְׁרֵי הַצַּדִּיקִים שֶׁלֹּא נִטְמְאוּ וְלֹא נִשְׁאֲרָה בָהֶם טֻמְאָה.</p>"],[9522011263,"<p>וּבֹא רְאֵה, בְּאֶמְצַע הָרָקִיעַ נִקְשָׁר דֶּרֶךְ אֶחָד מַבְהִיק, וְהוּא נְחַשׁ הָרָקִיעַ, שֶׁכָּל הַכּוֹכָבִים הַדַּקִּים כֻּלָּם קְשׁוּרִים בּוֹ וְעוֹמְדִים בּוֹ תִּלֵּי תִלִּים, וְהֵם מְמֻנִּים (בצד) עַל מַעֲשֵׂי בְּנֵי הָעוֹלָם שֶׁבַּסֵּתֶר.</p>\n<p>כְּדֻגְמַת זֶה כַּמָּה קְבוּצוֹת מַלְאֲכֵי דִּין יוֹצְאוֹת לָעוֹלָם מִזֶּה הַנָּחָשׁ הָעֶלְיוֹן הַקַּדְמוֹן שֶׁהִתְפַּתָּה בּוֹ אָדָם, וְכֻלָּם מְמֻנִּים בְּסֵתֶר מַעֲשֵׂי הָעוֹלָם, וּמִשּׁוּם כָּךְ, בָּא אָדָם לְהִטָּהֵר - מְסַיְּעִים אוֹתוֹ מִלְמַעְלָה, וְהַסִּיּוּעַ שֶׁל רַבּוֹ מַקִּיף אוֹתוֹ וְנִשְׁמָר וְנִקְרָא קָדוֹשׁ.</p>\n<p>בָּא הָאָדָם לְהִטָּמֵא - כַּמָּה חֲבִילוֹת שֶׁל אוֹרוֹת מִזְדַּמְּנִים לוֹ, וְכֻלָּם (סובבים) שׁוֹרִים בּוֹ וּמְסוֹבְבִים אוֹתוֹ וּמְטַמְּאִים אוֹתוֹ, וְנִקְרָא טָמֵא. וְכֻלָּם הוֹלְכִים וּמַכְרִיזִים לְפָנָיו טָמֵא טָמֵא, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יג) וְטָמֵא טָמֵא יִקְרָא. וְכֻלָּם קְשׁוּרִים בְּאוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי וְנִסְתָּרִים בְּכַמָּה מַעֲשִׂים שֶׁל הָעוֹלָם.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מִטְּבֶרְיָא לְלוֹד. אָמַר רַבִּי יִצְחָק, תְּמֵהַנִי עַל אוֹתוֹ בִּלְעָם הָרָשָׁע, שֶׁכָּל מַעֲשֵׂי אוֹתוֹ הָרָשָׁע הָיוּ מִצַּד הַטֻּמְאָה, וְכָאן לָמַדְנוּ סוֹד אֶחָד - שֶׁכָּל מִינֵי נְחָשִׁים שֶׁל הָעוֹלָם, כֻּלָּם קְשׁוּרִים וְיוֹצְאִים מֵאוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי, שֶׁהוּא רוּחַ טֻמְאָה מְזֹהֶמֶת. וּמִשּׁוּם כָּךְ כָּל הַכְּשָׁפִים שֶׁל הָעוֹלָם נִקְרָאִים בַּשֵּׁם הַזֶּה נְחָשִׁים (ועקרבים), וְכֻלָּם יוֹצְאִים מִן הַצַּד הַזֶּה. וּמִי שֶׁנִּמְשָׁךְ לָזֶה, הִנֵּה הוּא נִטְמָא.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁרוֹצֶה לְהִטָּמֵא כְּדֵי לִמְשֹׁךְ עָלָיו אוֹתוֹ הַצַּד שֶׁל רוּחַ טֻמְאָה. שֶׁהֲרֵי שָׁנִינוּ, כְּמוֹ שֶׁמְּעוֹרֵר הָאָדָם - כָּךְ גַּם מוֹשֵׁךְ עָלָיו מִלְמַעְלָה. אִם הוּא מְעוֹרֵר בְּצַד הַקְּדֻשָּׁה - מוֹשֵׁךְ עָלָיו קְדֻשָּׁה מִלְמַעְלָה וּמִתְקַדֵּשׁ. וְאִם הוּא מְעוֹרֵר בְּצַד הַטֻּמְאָה - כָּךְ מוֹשֵׁךְ עָלָיו רוּחַ הַטֻּמְאָה וְנִטְמָא. שֶׁהֲרֵי נֶאֱמַר עַל מַה שֶּׁשָּׁנִינוּ, בָּא אָדָם לְהִטָּמֵא - מְטַמְּאִים אוֹתוֹ.</p>\n<p>מִשּׁוּם כָּךְ אוֹתוֹ בִּלְעָם הָרָשָׁע, כְּדֵי לִמְשֹׁךְ עָלָיו רוּחַ טֻמְאָה מֵאוֹתוֹ הַנָּחָשׁ הָעֶלְיוֹן, הָיָה נִטְמָא בְּכָל לַיְלָה עִם אֲתוֹנוֹ, וְהָיָה עוֹשֶׂה עִמָּהּ מַעֲשֵׂי אִישׁוּת כְּדֵי לְהִטָּמֵא וְלִמְשֹׁךְ עָלָיו רוּחַ טֻמְאָה, וְאָז עָשָׂה כְשָׁפָיו וּמַעֲשָׂיו.</p>\n<p>וְרֵאשִׁית מַעֲשָׂיו הָיָה נוֹטֵל נָחָשׁ מֵאוֹתָם נְחָשִׁים, וְקוֹשֵׁר אוֹתוֹ לְפָנָיו, וְקוֹרֵעַ אֶת רֹאשׁוֹ, וּמוֹצִיא אֶת לְשׁוֹנוֹ, וְנוֹטֵל עֲשָׂבִים יְדוּעִים וְשׂוֹרֵף הַכֹּל, וְעוֹשֶׂה מִמֶּנּוּ קְטֹרֶת אַחַת. אַחַר כָּךְ נוֹטֵל אֶת רֹאשׁ אוֹתוֹ הַנָּחָשׁ וְקוֹרֵעַ אוֹתוֹ לְאַרְבָּעָה צְדָדִים, וְעוֹשֶׂה מִמֶּנּוּ קְטֹרֶת אַחֶרֶת.</p>\n<p>וְעוֹשֶׂה עִגּוּל אֶחָד, וְהָיָה אוֹמֵר דִּבּוּרִים וְעוֹשֶׂה מַעֲשִׂים אֲחֵרִים, עַד שֶׁמָּשַׁךְ עָלָיו רוּחוֹת טְמֵאוֹת וּמוֹדִיעוֹת לוֹ מַה שֶּׁצָּרִיךְ, וְעוֹשֶׂה בָהֶם מַעֲשִׂים כְּפִי מַה שֶּׁהֵם יוֹדְעִים מִצַּד אוֹתוֹ הַנָּחָשׁ שֶׁל הָרָקִיעַ. מִשָּׁם נִמְשַׁךְ בְּמַעֲשָׂיו וּבִכְשָׁפָיו, עַד שֶׁמָּשַׁךְ עָלָיו רוּחַ מֵאוֹתוֹ הַנָּחָשׁ הַקַּדְמוֹנִי.</p>\n<p>וּמִכָּאן הָיָה יוֹדֵעַ יְדִיעוֹת וּכְשָׁפִים וּקְסָמִים. וּמִשּׁוּם כָּךְ כָּתוּב, וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים. נְחָשִׁים וַדַּאי. וְהָעִקָּר וְהַשֹּׁרֶשׁ בַּטֻּמְאָה הוּא כְּמוֹ שֶׁנִּתְבָּאֵר, וְאַחַר כָּךְ רֵאשִׁית הַכֹּל אֵינוֹ אֶלָּא בְּנָחָשׁ.</p>"],[9522011264,"<p>אָמַר רַבִּי יוֹסֵי, לָמָּה כָּל מִינֵי כְשָׁפִים וּקְסָמִים לֹא נִמְצָאִים אֶלָּא בְּנָשִׁים? אָמַר לוֹ, כָּךְ לָמַדְנוּ, מִשֶּׁבָּא נָחָשׁ עַל חַוָּה, הִטִּיל בָּהּ זֻהֲמָא. הִטִּיל בָּהּ וְלֹא בְּבַעְלָהּ. אָמַר, כָּךְ זֶה וַדַּאי! בָּא רַבִּי יוֹסֵי וְנָשַׁק לְרַבִּי יִצְחָק. אָמַר, כַּמָּה פְעָמִים שָׁאַלְתִּי עַל הַדָּבָר הַזֶּה וְלֹא זָכִיתִי בוֹ, אֶלָּא כָּעֵת.</p>\n<p>אָמַר לוֹ, כָּל הַמַּעֲשִׂים הַלָּלוּ וְכָל מַה שֶּׁיָּדַע בִּלְעָם, מֵאֵיזֶה מָקוֹם לָמַד אוֹתָם? אָמַר לוֹ, מֵאָבִיו. אֲבָל בְּאוֹתָם הַרֲרֵי קֶדֶם, שֶׁהִיא אֶרֶץ קֶדֶם, לָמַד כָּל הַכְּשָׁפִים וְכָל מִינֵי קְסָמִים, מִשּׁוּם שֶׁבְּאוֹתָם הֶהָרִים הֵם הַמַּלְאָכִים עֲזָ\"א וַעֲזָאֵ\"ל שֶׁהִפִּיל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הַשָּׁמַיִם, וְהֵם קְשׁוּרִים בְּשַׁלְשְׁלָאוֹת שֶׁל בַּרְזֶל, וּמוֹדִיעִים כְּשָׁפִים לִבְנֵי אָדָם. וּמִשָּׁם הָיָה יוֹדֵעַ בִּלְעָם, כְּמוֹ שֶׁנֶּאֱמַר מִן אֲרָם יַנְחֵנִי בָלָק מֶלֶךְ מוֹאָב מֵהַרֲרֵי קֶדֶם.</p>\n<p>אָמַר לוֹ, וַהֲרֵי כָּתוּב וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו? אָמַר לוֹ, הַצַּד הַתַּחְתּוֹן שֶׁבָּא מֵרוּחַ הַטֻּמְאָה שֶׁלְּמַעְלָה הִיא רוּחַ טֻמְאָה שֶׁשּׁוֹלֶטֶת בַּמִּדְבָּר, כְּשֶׁעָשׂוּ בְּנֵי יִשְׂרָאֵל אֶת הָעֵגֶל כְּדֵי לְהִטָּמֵא עִמּוֹ, שֶׁהוּא תַחְתּוֹן. וּבַכֹּל עָשָׂה אֶת כְּשָׁפָיו, כְּדֵי שֶׁיּוּכַל לַעֲקֹר אֶת יִשְׂרָאֵל, וְלֹא יָכֹל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַה שֶּׁאָמַרְתָּ בָּרִאשׁוֹנָה, שֶׁכַּאֲשֶׁר הַנָּחָשׁ בָּא עַל חַוָּה הִטִּיל בָּהּ זֻהֲמָא - זֶה יָפֶה. אֲבָל הֲרֵי שָׁנִינוּ, שֶׁכַּאֲשֶׁר עָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, פָּסְקָה מֵהֶם הַזֻּהֲמָא. וּכְשֶׁיִּשְׂרָאֵל קִבְּלוּ תוֹרָה, פָּסְקָה מֵהֶם הַזֻּהֲמָא. אֲבָל שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם שֶׁלֹּא קִבְּלוּ הַתּוֹרָה, לֹא פָסְקָה מֵהֶם הַזֻּהֲמָא.</p>\n<p>אָמַר לוֹ, יָפֶה אָמַרְתָּ! אֲבָל בֹּא רְאֵה, הַתּוֹרָה לֹא נִתְּנָה אֶלָּא לַזְּכָרִים, שֶׁכָּתוּב (דברים ד) וְזאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. שֶׁהֲרֵי נָשִׁים פְּטוּרוֹת מִמִּצְווֹת הַתּוֹרָה.</p>\n<p>וְעוֹד, שֶׁכֻּלָּם חָזְרוּ לְזֻהַמְתָּן כְּמוֹ בָּרִאשׁוֹנָה אַחַר שֶׁחָטְאוּ, וּמֵהָאִשָּׁה קָשֶׁה לְהַפְרִיד אֶת הַזֻּהֲמָא יוֹתֵר מֵהַגֶּבֶר, וּמִשּׁוּם כָּךְ נִמְצְאוּ נָשִׁים בִּכְשָׁפִים וּבַזֻּהֲמָא הַזּוֹ יוֹתֵר מֵאֲשֶׁר בַּגְּבָרִים. שֶׁהֲרֵי הַנָּשִׁים בָּאוֹת מִצַּד הַשְּׂמֹאל וּדְבוּקוֹת בַּדִּין הַקָּשֶׁה, וְהַצַּד הַזֶּה נִדְבָּק בָּהֶם יוֹתֵר מִבַּגְּבָרִים, כְּמוֹ שֶׁנִּתְבָּאֵר, מִשּׁוּם שֶׁבָּאוֹת מִצַּד הַדִּין הַקָּשֶׁה, וְהַכֹּל נִדְבָּק וְהוֹלֵךְ אַחַר מִינוֹ.</p>\n<p>בֹּא רְאֵה שֶׁכָּךְ הוּא כְּמוֹ שֶׁאָמַרְתִּי - שֶׁבִּלְעָם הָיָה נִטְמָא בָּרִאשׁוֹנָה כְּדֵי לְהַמְשִׁיךְ עָלָיו רוּחַ שֶׁל טֻמְאָה. כְּמוֹ זֶה הָאִשָּׁה בִּימֵי טֻמְאָתָהּ יֵשׁ לְאָדָם לְהִשָּׁמֵר מִמֶּנָּה, מִשּׁוּם שֶׁנִּדְבֶּקֶת בְּרוּחַ שֶׁל טֻמְאָה, וּבְאוֹתוֹ הַזְּמַן אִם הִיא תַּעֲשֶׂה כְשָׁפִים - יַצְלִיחוּ בְיָדָהּ יוֹתֵר מִבִּזְמַן אַחֵר, שֶׁהֲרֵי רוּחַ טֻמְאָה שׁוֹרָה עִמָּהּ, וְעַל כֵּן לְכָל מַה שֶּׁמִּתְקָרֶבֶת - נִטְמָא, כָּל שֶׁכֵּן מִי שֶׁקָּרֵב אֵלֶיהָ. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה וְאָמַר לָהֶם (ויקרא יח) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ אֲנִי ה'.</p>\n<p>אָמַר לוֹ, מִי שֶׁמִּסְתַּכֵּל בְּצִפְצוּפֵי הָעוֹפוֹת לָמָּה נִקְרָא נָחָשׁ? אָמַר לוֹ, שֶׁהִנֵּה מֵאוֹתוֹ הַצַּד בָּאָה, שֶׁרוּחַ טֻמְאָה שׁוֹרָה עַל הָעוֹף הַהוּא וּמוֹדִיעַ דְּבָרִים בָּעוֹלָם. וְכָל רוּחַ טֻמְאָה דְּבוּקִים בַּנָּחָשׁ וּבָאוֹת לָעוֹלָם, וְאֵין מִי שֶׁיִּנָּצֵל מִמֶּנּוּ בָּעוֹלָם, שֶׁהֲרֵי הוּא נִמְצָא עִם הַכֹּל עַד הַזְּמַן שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מִן הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ'. וְכָתוּב (זכריה ג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ וְגוֹ'.</p>"],[9522011265,"<p>רַבִּי יְהוּדָה אָמַר, אַבְרָהָם יָדַע בְּאוֹתָהּ הַמְּעָרָה סִימָן, וְלִבּוֹ וּרְצוֹנוֹ הָיוּ שָׁם, מִשּׁוּם שֶׁמִּקֹּדֶם לָכֵן נִכְנַס לְשָׁם וְרָאָה אֶת אָדָם וְחַוָּה טְמוּנִים שָׁם. וּמִנַּיִן הָיָה יוֹדֵעַ שֶׁהֵם הָיוּ? אֶלָּא רָאָה דְמוּתוֹ וְהִסְתַּכֵּל, וְנִפְתַּח לוֹ פֶּתַח אֶחָד שֶׁל גַּן עֵדֶן שָׁם, וְאוֹתָהּ דְּמוּת שֶׁל אָדָם הָיְתָה עוֹמֶדֶת אֶצְלוֹ.</p>\n<p>וּבֹא וּרְאֵה, כָּל מִי שֶׁמִּסְתַּכֵּל בִּדְמוּתוֹ שֶׁל אָדָם, אֵינוֹ נִצּוֹל מִמִּיתָה לְעוֹלָמִים, מִשּׁוּם שֶׁהִנֵּה בְּשָׁעָה שֶׁאָדָם מִסְתַּלֵּק מִן הָעוֹלָם, הוּא רוֹאֶה אֶת אָדָם, וּבְאוֹתוֹ הַזְּמַן מֵת. אֲבָל אַבְרָהָם הִסְתַּכֵּל בּוֹ וְרָאָה דְמוּתוֹ וְהִתְקַיֵּם, וְרָאָה הָאוֹר שֶׁמֵּאִיר בַּמְּעָרָה, וְנֵר אֶחָד דּוֹלֵק. אָז הִתְאַוָּה אַבְרָהָם לִמְדוֹרוֹ בַּמָּקוֹם הַהוּא, וְלִבּוֹ וּרְצוֹנוֹ הָיוּ תָמִיד בַּמְּעָרָה.</p>\n<p>בֹּא רְאֵה, כָּעֵת אַבְרָהָם עָשָׂה בְּחָכְמָה בִּזְמַן שֶׁבִּקֵּשׁ קֶבֶר לְשָׂרָה, שֶׁהֲרֵי כְּשֶׁבִּקֵּשׁ, לֹא בִקֵּשׁ אֶת הַמְּעָרָה בְּאוֹתוֹ זְמַן, וְלֹא אָמַר שֶׁרוֹצֶה לְהִפָּרֵד מֵהֶם, אֶלָּא אָמַר, תְּנוּ לִי אֲחֻזַּת קֶבֶר עִמָּכֶם וְאֶקְבְּרָה מֵתִי מִלְּפָנָי. וְאִם תֹּאמַר שֶׁעֶפְרוֹן לֹא הָיָה שָׁם - הוּא הָיָה שָׁם, שֶׁכָּתוּב וְעֶפְרוֹן יֹשֵׁב בְּתוֹךְ בְּנֵי חֵת. וְאַבְרָהָם לֹא אָמַר לוֹ בְּאוֹתָהּ שָׁעָה כְּלוּם.</p>\n<p>אֶלָּא מָה שֶׁאָמַר לָהֶם אָמַר, כְּמוֹ שֶׁכָּתוּב וַיְדַבֵּר אֶל בְּנֵי חֵת וְגוֹ'. וְכִי עוֹלֶה בְּדַעְתְּךְ שֶׁאַבְרָהָם רָצָה לְהִקָּבֵר בֵּינֵיהֶם בֵּין הַטְּמֵאִים, אוֹ שֶׁתְּשׁוּקָתוֹ הָיְתָה עִמָּהֶם? אֶלָּא עָשָׂה בְּחָכְמָה.</p>\n<p>וְלָמַדְנוּ כָּאן דֶּרֶךְ אֶרֶץ בְּמַה שֶּׁעָשָׂה אַבְרָהָם, שֶׁהֲרֵי מִשּׁוּם שֶׁתְּשׁוּקָתוֹ וּרְצוֹנוֹ הָיוּ בַּמְּעָרָה הַהִיא - אַף עַל גַּב שֶׁהָיָה שָׁם, לֹא רָצָה לְבַקֵּשׁ אוֹתוֹ מִיָּד אוֹתוֹ הָרָצוֹן שֶׁהָיָה לוֹ בַּמְּעָרָה, וּבִקֵּשׁ בַּתְּחִלָּה מַה שֶּׁלֹּא צָרִיךְ לְאוֹתָם אֲחֵרִים וְלֹא לְעֶפְרוֹן.</p>\n<p>כֵּיוָן שֶׁאָמְרוּ לוֹ לִפְנֵי עֶפְרוֹן, שְׁמָעֵנוּ אֲדנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ וְגוֹ' - מַה כָּתוּב? וְעֶפְרוֹן יֹשֵׁב בְּתוֹךְ בְּנֵי חֵת. כָּתוּב יָשַׁב. מֵרֵאשִׁית הַדְּבָרִים שֶׁאָמַר אַבְרָהָם שָׁם הָיָה. אָז אָמַר, שְׁמָעוּנִי וּפִגְעוּ לִי בְּעֶפְרוֹן בֶּן צֹחַר, וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגוֹ'. וְאִם תֹּאמַר בִּשְׁבִיל כְּבוֹדִי, יוֹתֵר מִכֶּם אֲנִי עוֹשֶׂה, שֶׁלֹּא רָצִיתִי בָכֶם. בְּתוֹכֲכֶם - כְּדֵי לְהִקָּבֵר בֵּינֵיכֶם, שֶׁרָצִיתִי בָכֶם, כְּדֵי שֶׁלֹּא אֶפָּרֵד מִכֶּם.</p>"],[9522011266,"<p>רַבִּי יוֹסֵי בֶּן רַבִּי יְהוּדָה הָלַךְ לִרְאוֹת אֶת רַבִּי חִיָּיא. אָמַר לוֹ, יֹאמַר מַר אִם שָׁמַע אֶת הַפָּרָשָׁה הַזּוֹ, אֵיךְ אָמְרוּ בַּעֲלֵי הַבָּרַיְתָא שֶׁפֵּרְשׁוּהָ בְּעִנְיַן הַנְּשָׁמָה. אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַבָּא, שֶׁכָּךְ הַתּוֹרָה הִיא בְּלִבָּם כְּמַעְיָן גָּדוֹל שֶׁל מַיִם, שֶׁאַף עַל גַּב שֶׁסּוֹתְמִים אוֹתוֹ - מֵרֹב הַמַּיִם פּוֹתְחִים מַעְיָנוֹת שֶׁנּוֹבְעִים לְכָל עֵבֶר.</p>\n<p>בֹּא תִשְׁמַע, רַבִּי יוֹסֵי, אָהוּב אַתָּה. אֲנִי אֹמַר לְךְ בַּפָּרָשָׁה הַזּוֹ, לְעוֹלָם אֵין גּוּף הָאָדָם נִכְנָס בְּחֶשְׁבּוֹן הַצַּדִּיקִים עַל יַד דּוּמָה, עַד שֶׁתַּרְאֶה הַנְּשָׁמָה פִּנְקָס סִימָן שֶׁנּוֹתְנִים לָהּ הַכְּרוּבִים בְּגַן עֵדֶן. אָמַר רַבִּי יוֹסֵי, אֲנִי שָׁמַעְתִּי שֶׁהִנֵּה הַנְּשָׁמָה, אַחַר שֶׁנִּכְנֶסֶת לְשָׁם, הִיא הוֹלֶכֶת לַעֲלוֹת לִמְקוֹמָהּ לְמַעְלָה, וְלֹא לָרֶדֶת לְמַטָּה. אֲבָל קֹדֶם שֶׁתַּעֲלֶה וְתִכָּנֵס, נַעֲשֵׂית אֶפּוֹטְרוֹפּוֹס הַגּוּף עַל יַד דּוּמָה, וּמַרְאָה לוֹ שֶׁרָאוּי הוּא לְקַבֵּל שָׂכָר אַרְבַּע מֵאוֹת עוֹלָמוֹת.</p>\n<p>אָמַר רַבִּי חִיָּיא, הִנֵּה רַבִּי אֶלְעָזָר אָמַר, שֶׁהֲרֵי דּוּמָה יוֹדֵעַ קֹדֶם, מִשּׁוּם שֶׁמַּכְרִיזִים עָלֶיהָ בְּגַן עֵדֶן. אֲבָל אֲנִי כָּךְ שָׁמַעְתִּי - שֶׁבִּזְמַן שֶׁנּוֹתְנִים לָהּ פִּנְקָס, חוֹזֶרֶת עַל הַגּוּף לְהַכְנִיסוֹ בַּפֶּתֶק שֶׁל הַצַּדִּיקִים עַל יְדֵי דוּמָה. זֶהוּ שֶׁכָּתוּב אַךְ אִם אַתָּה לוּ שְׁמָעֵנִי נָתַתִּי כֶּסֶף הַשָּׂדֶה קַח מִמֶּנִּי. מַה זֶּה כֶּסֶף הַשָּׂדֶה? זֶה הַכִּסּוּף שֶׁל אַרְבַּע מֵאוֹת הָעוֹלָמוֹת שֶׁנּוֹתְנִים לוֹ לִירֻשָּׁה.</p>\n<p>כְּשֶׁרַב יוֹסֵף הָיָה שׁוֹמֵעַ הַפָּרָשָׁה הַזּוֹ מֵרָאשֵׁי הַיְשִׁיבָה, הָיָה אוֹמֵר: מִי שֶׁהוּא עָפָר, מַה הוּא (ריק) זוֹכֶה לָזֶה? מִי יִזְכֶּה וּמִי יָקוּם? זֶהוּ שֶׁכָּתוּב (תהלים כד) מִי יַעֲלֶה בְּהַר ה' וְגוֹ'.</p>\n<p>אָמַר רַבִּי אַבָּא, בּא רְאֵה מַה שֶּׁכָּתוּב, וַיִּשְׁמַע אַבְרָהָם אֶל עֶפְרוֹן וַיִּשְׁקֹל אַבְרָהָם לְעֶפְרֹן אֶת הַכֶּסֶף. זֶהוּ הַכִּסּוּף הַגָּדוֹל שֶׁהֵם עוֹלָמוֹת וְכִסּוּפִים. אַרְבַּע מֵאוֹת שֶׁקֶל כֶּסֶף - אַרְבַּע מֵאוֹת עוֹלָמוֹת וַהֲנָאוֹת וְכִסּוּפִים. עֹבֵר לַסֹּחֵר - רַב נַחְמָן אָמַר, שֶׁיַּעֲבֹר כָּל שַׁעֲרֵי שָׁמַיִם וִירוּשָׁלַיִם שֶׁל מַעְלָה, וְאֵין מוֹחֶה בְיָדוֹ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ. וְנִמְנָה עִם שְׁאָר הַצַּדִּיקִים בַּחֲבוּרָתָם מִפֶּתֶק שֶׁל הַמְמֻנֶּה עַל יְדֵי דוּמָה. אָמַר רַבִּי יִצְחָק, כָּךְ לָמַדְנוּ, כָּל אוֹתָם שֶׁכְּתוּבִים בִּידֵי דוּמָה וּמְמֻנִּים עַל יָדוֹ, יָקוּמוּ לִזְמַן שֶׁעָתִיד לְהַחֲיוֹת שׁוֹכְנֵי עָפָר. אוֹי לָרְשָׁעִים שֶׁאֵינָם כְּתוּבִים עַל יָדוֹ בַּפֶּתֶק, שֶׁיֹּאבְדוּ בַּגֵּיהִנֹּם לְעוֹלָמִים, וְעַל זֶה נֶאֱמַר (דניאל יב) וּבָעֵת הַהִיא יִמָּלֵט עַמְּךְ כָּל הַנִּמְצָא כָּתוּב בַּסֵּפֶר. עד כאן תוספתא</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, בְּשָׁעָה שֶׁנִּכְנַס אַבְרָהָם לַמְּעָרָה, אֵיךְ נִכְנַס? מִשּׁוּם שֶׁהָיָה רָץ אַחַר אוֹתוֹ הָעֵגֶל, שֶׁכָּתוּב וְאֶל הַבָּקָר רָץ אַבְרָהָם וְגוֹ', וְאוֹתוֹ בֶּן בָּקָר בָּרַח עַד אוֹתָהּ הַמְּעָרָה, וְנִכְנַס אַחֲרָיו, וְרָאָה מַה שֶּׁרָאָה.</p>\n<p>עוֹד, מִשּׁוּם שֶׁהוּא הִתְפַּלֵּל כָּל יוֹם וָיוֹם, וְהָיָה יוֹצֵא עַד אוֹתָהּ הַשָּׂדֶה שֶׁהָיְתָה מַעֲלָה רֵיחוֹת עֶלְיוֹנִים, וְרָאָה הָאוֹר שֶׁיּוֹצֵא מִתּוֹךְ הַמְּעָרָה וְהִתְפַּלֵּל שָׁם, וְשָׁם דִּבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ רָצָה אוֹתָהּ, שֶׁתְּשׁוּקָתוֹ הָיְתָה תָמִיד בְּאוֹתוֹ הַמָּקוֹם.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, לָמָּה לֹא רָצָה אוֹתָהּ עַד עַכְשָׁו? כְּדֵי שֶׁלֹּא יַבְחִינוּ בוֹ, הוֹאִיל וְלֹא צָרִיךְ אוֹתָהּ. כָּעֵת שֶׁהִצְטָרֵךְ אוֹתָהּ, אָמַר, הִנֵּה הַשָּׁעָה לְבַקֵּשׁ אוֹתָהּ.</p>\n<p>בֹּא רְאֵה, אִם עֶפְרוֹן הָיָה רוֹאֶה בַּמְּעָרָה מַה שֶּׁרָאָה בָּהּ אַבְרָהָם, לֹא הָיָה מוֹכֵר אוֹתָהּ לְעוֹלָמִים, אֶלָּא וַדַּאי לֹא רָאָה בָּהּ וְלֹא כְלוּם, שֶׁהֲרֵי אֵין הַדָּבָר נִגְלֶה אֶלָּא לִבְעָלָיו, וּמִשּׁוּם כָּךְ לְאַבְרָהָם הִתְגַּלְּתָה וְלֹא לְעֶפְרוֹן. לְאַבְרָהָם הִתְגַּלְּתָה - שֶׁלּוֹ הָיְתָה. לְעֶפְרוֹן לֹא הָיְתָה מִתְגַּלָּה - שֶׁלֹּא הָיָה לוֹ בָּהּ חֵלֶק. וּמִשּׁוּם כָּךְ לֹא הִתְגַּלָּה לְעֶפְרוֹן כְּלוּם, וְלֹא הָיָה רוֹאֶה אֶלָּא חֲשֵׁכָה, וְעַל כֵּן מָכַר אוֹתָהּ.</p>\n<p>וּמַה שֶּׁלֹּא בִקֵּשׁ אַבְרָהָם בָּרִאשׁוֹנָה שֶׁיִּמְכֹּר לוֹ מָכַר, שֶׁהֲרֵי אַבְרָהָם לֹא אָמַר אֶלָּא - וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ וְגוֹ', בְּכֶסֶף מָלֵא יִתְּנֶנָּה לִּי וְגוֹ'. וְהוּא אָמַר, הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ לְךְ נְתַתִּיהָ וְגוֹ'. מִשּׁוּם שֶׁהַכֹּל הָיָה מָאוּס עַל עֶפְרוֹן, שֶׁלֹּא יָדַע מַה הִיא.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁנִּכְנַס אַבְרָהָם בַּתְּחִלָּה לַמְּעָרָה, רָאָה שָׁם אוֹר, וְנִזְרַק לְפָנָיו עָפָר, וְהִתְגַּלּוּ לוֹ שְׁנֵי קְבָרִים. בֵּינְתַיִם עָלָה אָדָם בִּדְמוּתוֹ, וְרָאָה אֶת אַבְרָהָם וְחִיֵּךְ, וּבוֹ (היה) יָדַע אַבְרָהָם שֶׁשָּׁם (היה) הוּא עָתִיד לְהִקָּבֵר.</p>\n<p>אָמַר לוֹ אַבְרָהָם: בְּבַקָּשָׁה מִמְּךְ, הַאִם טִירָה שֶׁאֵינָהּ מְקֹרָה יֵשׁ כָּאן? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, הִטְמִין אוֹתִי כָּאן, וּמֵאוֹתוֹ הַזְּמַן עַד עַכְשָׁו נִטְמַנְתִּי כְּמוֹ דָּג בַּחֲפִירָה עַד שֶׁאַתָּה בָּאתָ לָעוֹלָם. עַכְשָׁו מִכָּאן וְאֵילָךְ הִנֵּה קִיּוּם לִי וְלָעוֹלָם יֵשׁ בִּשְׁבִילְךְ.</p>\n<p>רְאֵה מַה כָּתוּב - וַיָּקָם הַשָּׂדֶה וְהַמְּעָרָה אֲשֶׁר בּוֹ. מַמָּשׁ קִימָה הָיְתָה לָהּ מַה שֶּׁלֹּא הָיְתָה לָהּ עַד עַתָּה. רַבִּי אַבָּא אָמַר, וַיָּקָם הַשָּׂדֶה - וַדַּאי קִימָה מַמָּשׁ, שֶׁקָּם וְהִתְעַלָּה לִפְנֵי אַבְרָהָם, מִשּׁוּם שֶׁעַד עַכְשָׁו לֹא נִרְאָה שָׁם כְּלוּם, וְעַכְשָׁו, מַה שֶּׁהָיָה טָמוּן - קָם וְהִתְעַלָּה, וְאָז קָם הַכֹּל כְּמִשְׁפָּטוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁנִּכְנַס אַבְרָהָם לַמְּעָרָה וְהִכְנִיס לְשָׁם אֶת שָׂרָה, קָמוּ אָדָם וְחַוָּה, וְלֹא קִבְּלוּ לְהִקָּבֵר שָׁם. אָמְרוּ: וּמָה אָנוּ בְּבוּשָׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ הָעוֹלָם מִשּׁוּם אוֹתוֹ הַחֵטְא שֶׁגָּרַמְנוּ, וְכָעֵת תִּתּוֹסֵף לָנוּ בּוּשָׁה אַחֶרֶת - מִפְּנֵי הַמַּעֲשִׂים טוֹבִים שֶׁבָּכֶם?</p>\n<p>אָמַר אַבְרָהָם: הֲרֵינִי מְזֻמָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עֲבוּרְךְ שֶׁלֹּא תִתְבַּיֵּשׁ לְפָנָיו לְעוֹלָמִים. מִיָּד - וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ. מַה זֶּה וְאַחֲרֵי כֵן? אַחַר שֶׁקִּבֵּל עָלָיו אַבְרָהָם אֶת הַדָּבָר הַזֶּה.</p>\n<p>אָדָם נִכְנַס לִמְקוֹמוֹ - חַוָּה לֹא נִכְנְסָה, עַד שֶׁקָּרַב אַבְרָהָם וְהִכְנִיס אוֹתָהּ אֵצֶל אָדָם וְקִבֵּל אוֹתָהּ בִּשְׁבִילוֹ. זֶהוּ שֶׁכָּתוּב וְאַחֲרֵי כֵן קָבַר אַבְרָהָם אֶת שָׂרָה אִשְׁתּוֹ, וְלֹא כָתוּב לְשָׂרָה, אֶלָּא אֶת שָׂרָה, לְרַבּוֹת חַוָּה. וְאָז הִתְיַשְּׁבוּ בִּמְקוֹמָם כָּרָאוּי. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְשָׁנִינוּ בְּאַבְרָהָם. תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ - זֶה אָדָם וְחַוָּה. לֹא כָתוּב אֵלֶּה הַשָּׁמַיִם וְהָאָרֶץ, אֶלָּא תוֹלְדוֹת הַשָּׁמַיִם הָאָרֶץ, וְלֹא תוֹלְדוֹת בֶּן אָדָם. וְהֵם הִתְקַיְּמוּ בִּשְׁבִיל אַבְרָהָם. וּמִנַּיִן לָנוּ שֶׁהִתְקַיְּמוּ בִּשְׁבִיל אַבְרָהָם? שֶׁכָּתוּב וַיָּקָם הַשָּׂדֶה וְהַמְּעָרָה אֲשֶׁר בּוֹ לְאַבְרָהָם. וְעַד שֶׁבָּא אַבְרָהָם לֹא הִתְקַיְּמוּ אָדָם וְחַוָּה בִּמְקוֹמָם בְּאוֹתוֹ הָעוֹלָם.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר, הַמְּעָרָה הַזּוֹ אֵינָהּ כְּפוּלָה, שֶׁהֲרֵי כָּתוּב מְעָרַת הַמַּכְפֵּלָה, וְאַחַר כָּךְ הַכָּתוּב קָרָא לָהּ מְעָרַת שְׂדֵה הַמַּכְפֵּלָה. מַכְפֵּלָה הוּא קָרָא לַשָּׂדֶה.</p>\n<p>אָמַר לוֹ, כָּךְ קוֹרֵא לָהּ - מְעָרַת הַמַּכְפֵּלָה, כְּמוֹ שֶׁנֶּאֱמַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה, אֲבָל וַדַּאי, חַיֶּיךְ, הַמְּעָרָה הִיא מַכְפֵּלָה, וְלֹא הַשָּׂדֶה נִקְרָא מַכְפֵּלָה. אֶלָּא הַשָּׂדֶה וְהַמְּעָרָה נִקְרָאִים עַל שֵׁם מַכְפֵּלָה, שְׂדֵה הַמַּכְפֵּלָה וַדַּאי, וְלֹא הַמְּעָרָה, שֶׁהֲרֵי הַמְּעָרָה הִיא בַּשָּׂדֶה, וְאוֹתוֹ הַשָּׂדֶה עוֹמֵד בְּדָבָר אַחֵר.</p>\n<p>בֹּא רְאֵה, תַּחַת יְרוּשָׁלַיִם נִכְפְּלָה כָּל אֶרֶץ יִשְׂרָאֵל, וְהִיא עוֹמֶדֶת לְמַעְלָה וּלְמַטָּה. כְּמוֹ כֵן יְרוּשָׁלַיִם לְמַעְלָה - יְרוּשָׁלַיִם מַטָּה. אֲחוּזָה לְמַעְלָה וַאֲחוּזָה לְמַטָּה. יְרוּשָׁלַיִם לְמַעְלָה אֲחוּזָה בִּשְׁנֵי צְדָדִים - לְמַעְלָה וּלְמַטָּה (ירושלים למטה אחוזה בשני צדדים למעלה ולמטה), וּמִשּׁוּם כָּךְ הִיא כְּפוּלָה.</p>\n<p>וְעַל כֵּן הַשָּׂדֶה הַזּוֹ מֵאוֹתָהּ מַכְפֵּלָה הִיא שֶׁבּוֹ הִיא שׁוֹרָה. כְּמוֹ כֵן כָּתוּב כְּרֵיחַ הַשָּׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', לְמַעְלָה וּלְמַטָּה, וּמִשּׁוּם כָּךְ שְׂדֵה הַמַּכְפֵּלָה וַדַּאי, וְלֹא שָׂדֶה כָּפוּל.</p>\n<p>עוֹד סוֹד הַדָּבָר - שְׂדֵה הַמַּכְפֵּלָה וַדַּאי. מִי הַמַּכְפֵּלָה? (ה') שֶׁבַּשֵּׁם הַקָּדוֹשׁ שֶׁהִיא מַכְפֵּלָה. הַכֹּל עוֹמֵד יַחַד, וּבִשְׁבִילָהּ אָמַר בְּדֶרֶךְ נִסְתָּר הַ' מַּכְפֵּלָה, שֶׁלֹּא הָיְתָה בַּשֵּׁם הַקָּדוֹשׁ אוֹת אַחֶרֶת מַכְפֵּלָה פְּרָט לָזֶה.</p>\n<p>וְאַף עַל גַּב שֶׁמְּעָרַת הַמַּכְפֵּלָה הָיְתָה וַדַּאי, שֶׁהִיא מְעָרָה בְּתוֹךְ מְעָרָה, אֲבָל עַל שֵׁם אַחֵר נִקְרֵאת מְעָרַת הַמַּכְפֵּלָה, כְּמוֹ שֶׁנֶּאֱמַר. וְאַבְרָהָם יָדַע, וּכְשֶׁאָמַר לִבְנֵי חֵת, כִּסָּה אֶת הַדָּבָר, וְאָמַר וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה, עַל שֵׁם שֶׁהִיא מְעָרָה כְּפוּלָה, וְהַתּוֹרָה לֹא קָרְאָה לָהּ אֶלָּא מְעָרַת שְׂדֵה הַמַּכְפֵּלָה כָּרָאוּי.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הַכֹּל שֶׁיִּמָּצֵא הָעוֹלָם הַזֶּה, כְּמוֹ שֶׁלְּמַעְלָה, וּלְהַדְבִּיק זֶה עִם זֶה שֶׁיִּהְיֶה כְבוֹדוֹ לְמַעְלָה וּלְמַטָּה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011267,"<p>וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. רַבִּי יְהוּדָה פָּתַח, (תהלים סח) אַשְׁרֵי תִבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ. הַפָּסוּק הַזֶּה נִתְבָּאֵר, אֲבָל אַשְׁרֵי הָאִישׁ שֶׁדְּרָכָיו כְּשֵׁרוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא הִתְרַצָּה בּוֹ לְקָרְבוֹ אֵלָיו.</p>\n<p>בֹּא רְאֵה, אַבְרָהָם הִתְקָרֵב אֵלָיו, וּתְשׁוּקָתוֹ הָיְתָה כָּל יוֹם בָּזֶה. וְלֹא הִתְקָרֵב אַבְרָהָם בְּיוֹם אֶחָד אוֹ בְּפַעַם אַחַת, אֶלָּא מַעֲשָׂיו קֵרְבוּהוּ בְּכָל יָמָיו מִדַּרְגָּה לְדַרְגָּה, עַד שֶׁהִתְעַלָּה בְּדַרְגָּתוֹ.</p>\n<p>כְּשֶׁהָיָה זָקֵן וְנִכְנַס לִדְרָגוֹת עֶלְיוֹנוֹת כָּרָאוּי, שֶׁכָּתוּב וְאַבְרָהָם זָקֵן, וְאָז בָּא בַּיָּמִים, בְּאוֹתָם יָמִים עֶלְיוֹנִים, בְּאוֹתָם יָמִים יְדוּעִים בְּסוֹד הָאֱמוּנָה. וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. שֶׁמִּשָּׁם יוֹצְאוֹת כָּל הַבְּרָכוֹת וְכָל טוֹב.</p>\n<p>אַשְׁרֵיהֶם בַּעֲלֵי הַתְּשׁוּבָה, שֶׁהֲרֵי בְּשָׁעָה אַחַת בְּיוֹם אֶחָד (בפעם אחת) בְּרֶגַע אֶחָד קְרֵבִים לַקָּבָּ\"ה, מַה שֶּׁלֹּא הָיָה כָּךְ אֲפִלּוּ לְצַדִּיקִים גְּמוּרִים שֶׁהִתְקָרְבוּ לַקָּבָּ\"ה בְּכַמָּה שָׁנִים. אַבְרָהָם לֹא נִכְנַס בְּאוֹתָם הַיָּמִים הָעֶלְיוֹנִים עַד שֶׁהָיָה זָקֵן, כְּמוֹ שֶׁנֶּאֱמַר. וְכֵן דָּוִד, שֶׁכָּתוּב (מלכים א א) וְהַמֶּלֶךְ דָּוִד זָקֵן בָּא בַּיָּמִים. אֲבָל בַּעַל הַתְּשׁוּבָה מִיָּד נִכְנָס וְנִדְבָּק בַּקָּבָּ\"ה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, שָׁנִינוּ, הַמָּקוֹם שֶׁבַּעֲלֵי הַתְּשׁוּבָה עוֹמְדִים בָּעוֹלָם הַהוּא, אֵין לְצַדִּיקִים גְּמוּרִים רְשׁוּת לַעֲמֹד בּוֹ, מִשּׁוּם שֶׁהֵם קְרוֹבִים לַמֶּלֶךְ יוֹתֵר מִכֻּלָּם, וְהֵם מוֹשְׁכִים עֲלֵיהֶם בִּרְצוֹן הַלֵּב יוֹתֵר וּבְכֹחַ רַב לְהִתְקָרֵב לַמֶּלֶךְ.</p>"],[9522011268,"<p>בֹּא רְאֵה, כַּמָּה מְקוֹמוֹת מְתֻקָּנִים לַקָּבָּ\"ה בָּעוֹלָם הַהוּא, וּבְכֻלָּם בֵּית מוֹשָׁבִים לַצַּדִּיקִים, כָּל אֶחָד וְאֶחָד לְפִי דַרְגָּתוֹ כָּרָאוּי לוֹ.</p>\n<p>כָּתוּב (תהלים סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְקָרֵב אוֹתָם אֵלָיו, שֶׁעוֹלִים אוֹתָם הַנְּשָׁמוֹת מִמַּטָּה לְמַעְלָה וּלְהֵאָחֵז בְּנַחֲלָתָם שֶׁנִּתְקְנָה לָהֶן. יִשְׁכֹּן חֲצֵרֶיךְ - אֵלּוּ הַמְּקוֹמוֹת וְהַדְּרָגוֹת שֶׁבַּחוּץ, וּמִי הֵם? כְּמוֹ שֶׁנֶּאֱמַר (זכריה ג) וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה. וְזוֹהִי דַרְגָּה בֵּין קְדוֹשִׁים עֶלְיוֹנִים.</p>\n<p>וּמִי שֶׁזַּכָּאִים לַדַּרְגָּה הַזּוֹ הֵם שְׁלִיחִים שֶׁל רִבּוֹן הָעוֹלָם, כְּמוֹ אוֹתָם הַמַּלְאָכִים, וְתָמִיד עוֹשִׂים שְׁלִיחוּת בִּרְצוֹן רִבּוֹנָם, מִשּׁוּם שֶׁאֵלּוּ (התקדשו) תָמִיד בִּקְדֻשָּׁה וְלֹא נִטְמְאוּ.</p>\n<p>כְּמוֹ כֵן מִי שֶׁנִּטְמָא בָּעוֹלָם הַזֶּה, הוּא מוֹשֵׁךְ עָלָיו רוּחַ טֻמְאָה, וּכְשֶׁיּוֹצֵאת מִמֶּנּוּ נִשְׁמָתוֹ, מְטַמְּאִים אוֹתוֹ, וּמְדוֹרוֹ בֵּין אוֹתָם הַטְּמֵאִים, וְאֵלּוּ הֵם הַמַּזִּיקִים שֶׁל הָעוֹלָם. כְּמוֹ שֶׁמַּמְשִׁיךְ אָדָם אֶת עַצְמוֹ בָּעוֹלָם הַזֶּה - כָּךְ הוּא מְדוֹרוֹ וְנִמְשָׁךְ בְּאוֹתוֹ הָעוֹלָם (ואותן רוחות הטמאות מטמאות אותו ומכניסות אותו לגיהנם).</p>\n<p>בֹּא רְאֵה, מִי שֶׁמִּתְקַדֵּשׁ וְשׁוֹמֵר אֶת עַצְמוֹ בָּעוֹלָם הַזֶּה שֶׁלֹּא יִטָּמֵא, מְדוֹרוֹ בָּעוֹלָם הַהוּא בֵּין אוֹתָם קְדוֹשִׁים עֶלְיוֹנִים וְעוֹשִׂים תָּמִיד שְׁלִיחוּת, וְאֵלּוּ עוֹמְדִים בֶּחָצֵר, כְּמוֹ שֶׁנֶּאֱמַר (שמות כז) אֵת חֲצַר הַמִּשְׁכָּן.</p>\n<p>וְיֵשׁ אֲחֵרִים שֶׁהֵם בִּפְנִים יוֹתֵר שֶׁאֵינָם בֶּחָצֵר, אֶלָּא בַּבַּיִת, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סה) נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ. אָמַר דָּוִד, נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ. כֵּיוָן שֶׁאָמַר יִשְׁכֹּן חֲצֵרֶיךְ, לָמָּה כָּתוּב נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ? יִשְׂבַּע בְּטוּב בֵּיתֶךְ הָיָה צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁכָּתוּב יִשְׁכֹּן! אֶלָּא הֲרֵי שָׁנִינוּ, אֵין יְשִׁיבָה בָּעֲזָרָה אֶלָּא לְמַלְכֵי דָוִד לְבַדָּם.</p>\n<p>וְיֵשׁ מָקוֹם לַחֲסִידִים עֶלְיוֹנִים שֶׁנִּכְנָסִים לִפְנִים, וּמִי הֵם? כַּכָּתוּב (במדבר ג) וְהַחֹנִים לִפְנֵי הַמִּשְׁכָּן קֵדְמָה לִפְנֵי אֹהֶל מוֹעֵד מִזְרָחָה מֹשֶׁה וְאַהֲרֹן וּבָנָיו וְגוֹ'. וְכַמָּה מְדוֹרִים עַל מְדוֹרִים וְאוֹרוֹת עַל אוֹרוֹת נִפְרָדִים בָּעוֹלָם הַהוּא, וְכָל אֶחָד מִתְבַּיֵּשׁ מֵאוֹר חֲבֵרוֹ. כְּמוֹ שֶׁהַמַּעֲשִׂים נִפְרָדִים בָּעוֹלָם הַזֶּה, כָּךְ גַּם מְקוֹמוֹת וְאוֹרוֹת נִפְרָדִים בָּעוֹלָם הַהוּא.</p>\n<p>וּבֹא וּרְאֵה, הֲרֵי נֶאֱמַר שֶׁאֲפִלּוּ בָּעוֹלָם הַזֶּה, כְּשֶׁאָדָם יָשֵׁן עַל מִטָּתוֹ וְהַנְּשָׁמוֹת צְרִיכוֹת לְשׁוֹטֵט בָּעוֹלָם וְיָצְאוּ מִתּוֹךְ הַגּוּף, אֵין כָּל נְשָׁמָה וּנְשָׁמָה עוֹלָה וּמְשׂוֹטֶטֶת לִרְאוֹת בִּכְבוֹד סֵבֶר פְּנֵי עַתִּיק הַיָּמִים, אֶלָּא כְּמוֹ שֶׁנִּמְשָׁךְ תָּמִיד וּכְפִי הַמַּעֲשִׂים, כָּךְ נִשְׁמָתוֹ עוֹלָה.</p>\n<p>אִם נִטְמָא - הוּא יָשֵׁן וְהַנְּשָׁמָה יוֹצֵאת, וְכָל אוֹתָן רוּחוֹת טְמֵאוֹת לוֹקְחוֹת אוֹתָהּ, וְנִדְבֶּקֶת בָּהֶן בְּאוֹתָן הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁמְּשׁוֹטְטוֹת בָּעוֹלָם, וְהֵם מוֹדִיעוֹת לָהּ דְּבָרִים שֶׁקְּרוֹבִים לָבֹא לָעוֹלָם. וְלִפְעָמִים שֶׁמּוֹדִיעִים לָהּ דְּבָרִים כּוֹזְבִים וְצוֹחֲקִים עָלֶיהָ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְאִם זוֹכֶה אָדָם, כְּשֶׁהוּא יָשֵׁן וְנִשְׁמָתוֹ עוֹלָה, הוֹלֶכֶת וְשָׁטָה וּבוֹקַעַת בֵּין הָרוּחוֹת הַטְּמֵאוֹת הַלָּלוּ, וְכֻלָּם מַכְרִיזִים וְאוֹמְרִים: פַּנּוּ מָקוֹם, פַּנּוּ. זֶה אֵינוֹ מִצִּדֵּנוּ! וְהִיא עוֹלָה בֵּין אוֹתָם הַקְּדוֹשִׁים, וּמוֹדִיעִים לָהּ דָּבָר אֶחָד אֱמֶת.</p>\n<p>וּכְשֶׁיּוֹרֶדֶת, כָּל אוֹתָם מַחֲנוֹת שֶׁל עִרְבּוּב רוֹצִים לְהִתְקָרֵב אֵלֶיהָ לָדַעַת אוֹתוֹ הַדָּבָר, וְהֵם מוֹדִיעִים לָהּ דְּבָרִים אֲחֵרִים. וְהַדִּבּוּר הַהוּא שֶׁנּוֹטֶלֶת בְּתוֹךְ אוֹתָם קְדוֹשִׁים בֵּין אוֹתָם הָאֲחֵרִים הוּא כִּתְבוּאָה בְּתוֹךְ הַתֶּבֶן. וְזֶה (מי) הוּא זוֹכֶה יוֹתֵר בְּעוֹד שֶׁהוּא עוֹמֵד וְהַנְּשָׁמָה עוֹמֶדֶת בָּעוֹלָם הַזֶּה.</p>\n<p>כְּמוֹ כֵן כְּשֶׁיּוֹצְאוֹת הַנְּשָׁמוֹת מֵהַגּוּף מֵהָעוֹלָם הַזֶּה, רוֹצוֹת לַעֲלוֹת, וְכַמָּה שׁוֹמְרֵי הַפֶּתַח וּמַחֲנוֹת מַזִּיקִים נִמְצָאִים. אִם הֵם מִצִּדָּם - כֻּלָּם אוֹחֲזִים בָּהֶם בְּאוֹתָן הַנְּפָשׁוֹת, וּמוֹסְרִים אוֹתָם בְּיַד דוּמָה לְהַכְנִיסָם לַגֵּיהִנֹּם.</p>\n<p>וְאַחַר כָּךְ עוֹלוֹת וְאוֹחֲזִים בָּהֶם, וְהֵם נוֹטְלִים אוֹתָם, וּמַכְרִיזִים בָּהֶם: אֵלּוּ הֵם שֶׁעָבְרוּ עַל מִצְווֹת רִבּוֹנָם. וְכֵן מְשׁוֹטְטוֹת בְּכָל הָעוֹלָם. וְאַחַר כָּךְ מַחֲזִירִים אוֹתָם לַגֵּיהִנֹּם, וְכֵן עַד שְׁנֵים עָשָׂר חֳדָשִׁים. אַחַר שְׁנֵים עָשָׂר חֳדָשִׁים הֵם שׁוֹכְכִים בְּאוֹתוֹ מָקוֹם שֶׁרָאוּי לָהֶם. אוֹתָם הַנְּשָׁמוֹת שֶׁזָּכוּ עוֹלוֹת לְמַעְלָה, כְּמוֹ שֶׁנִּתְבָּאֵר, וְזוֹכוֹת בִּמְקוֹמוֹתֵיהֶם.</p>\n<p>בֹּא רְאֵה, אַשְׁרֵי הַצַּדִּיקִים שֶׁנִּגְנְזוּ לָהֶם כַּמָּה טוֹבוֹת לָעוֹלָם הַהוּא, וְאֵין מָקוֹם פְּנימִי בְּכָל אוֹתָם כְּאוֹתָם שֶׁיּוֹדְעִים אֶת סוֹד רִבּוֹנָם וְיוֹדְעִים לִדְבֹּק בָּהֶם בְּכָל יוֹם. עַל אֵלּוּ כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>\n<p>מַה זֶּה לִמְחַכֵּה לוֹ? כְּמוֹ שֶׁנֶּאֱמַר (איוב לב) חִכָּה אֶת אִיּוֹב בִּדְבָרִים. וְאֵלּוּ הֵם שֶׁדּוֹחֲקִים לְדָבָר שֶׁל חָכְמָה וּמְדַיְּקִים אוֹתָהּ וּמְחַכִּים לָדַעַת אֶת בֵּרוּר הַדָּבָר, וְהֵם מֻכָּרִים לְרִבּוֹנָם. אֵלּוּ הֵם שֶׁרִבּוֹנָם מִשְׁתַּבֵּחַ בָּהֶם בְּכָל יוֹם. אֵלּוּ הֵם שֶׁנִּכְנָסִים בֵּין עֶלְיוֹנִים קְדוֹשִׁים, וְאֵלּוּ נִכְנָסִים בְּכָל הַשְּׁעָרִים שֶׁלְּמַעְלָה, וְאֵין מִי שֶׁיִּמְחֶה בְיָדָם. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, אַבְרָהָם נִכְנַס לָדַעַת וּלְהִדָּבֵק בְּרִבּוֹנוֹ כָּרָאוּי לְאַחַר שֶׁהִקְדִּים אֶת מַעֲשָׂיו שֶׁבָּרִאשׁוֹנָה, וְזָכָה לְאוֹתָם הַיָּמִים הָעֶלְיוֹנִים, וְהִתְבָּרֵךְ מֵהַמָּקוֹם שֶׁכָּל הַבְּרָכוֹת יוֹצְאוֹת מִשָּׁם, שֶׁכָּתוּב וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. מַה זֶּה בַּכֹּל? הַמָּקוֹם שֶׁל הַנָּהָר שֶׁאֵין פּוֹסְקִים מֵימָיו לְעוֹלָמִים.</p>\n<p>אָמַר רַבִּי חִיָּיא, בֹּא רְאֵה שֶׁאַבְרָהָם לֹא רָצָה לְהִתְעָרֵב עִם נְשׁוֹת הָעוֹלָם וּלְהִדָּבֵק בִּשְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁנְּשׁוֹת שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת הֵם מְטַמְּאוֹת אֶת הַגְּבָרִים שֶׁלָּהֶם וּלְאוֹתָם שֶׁנִּדְבָּקִים בָּהֶם. מִשּׁוּם שֶׁכְּשֶׁאַבְרָהָם יָדַע אֶת הַחָכְמָה, יָדַע הָעִקָּר וְהַשֹּׁרֶשׁ, וּמֵאֵיזֶה מָקוֹם יוֹצְאוֹת וּמְשׁוֹטְטוֹת רוּחוֹת טְמֵאוֹת בָּעוֹלָם, וְעַל כֵּן הִשְׁבִּיעַ אֶת עַבְדּוֹ שֶׁלֹּא יִקַּח אִשָּׁה לִבְנוֹ מִשְּׁאָר הָעַמִּים.</p>"],[9522011269,"<p>אַבְרָהָם זָקֵן בָּא בַּיָּמִים וְגוֹ'. מִשְׁנָה: אָמַר רַבִּי אֶלְעָזָר, עַל כָּל פָּנִים כָּךְ הוּא, שֶׁהַמִּשְׁנָה הַזּוֹ יָפָה, שֶׁנַּעֲשֵׂית הַנְּשָׁמָה, הַהוּא שֶׁכָּתוּב בּוֹ (יחזקאל א) והנה אופן אחד בארץ אצל החיות לארבעת פניו, כמו שאמור באותה הבריתא הראשונה.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, יֹאמַר לָנוּ מַר מִאוֹתָהּ הַמִּשְׁנָה. אָמַר לוֹ, כָּךְ הִתְפָּרֵשׁ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים בַּפָּרָשָׁה שֶׁלּוֹ, אֲבָל כָּאן שׁ לָנוּ לוֹמַר. פָּתַח וְאָמַר, (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לאִמָּהּ וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, מַה הִיא שֶׁאָנוּ קוֹרְאִים כָּאן בְּשִׁיר הַשִּׁירִים לְשׁוֹן נְקֵבָה, וְשָׁם בַּתּוֹרָה לְשׁוֹן זָכָר?</p>\n<p>אְלָּא, אָמַר רַבִּי אֶלְעָזָר, כָּאן בַּתּוֹרָה נִקְרָא בִּלְשׁוֹן זָכָר אֵצֶל הַגּוּף, מִפְּנֵי שֶׁהַגּוּף אֵצֶל הַנְּשָׁמָה כְּאִשָּׁה אֵצֶל הַזָּכָר, וְהַנְּשָׁמָה כְּלַפֵּי מַעְלָה כִּנְקֵבָה בִּפְנֵי הַזָּכָר, וְכָל אֶחָד יוֹרֵשׁ מַעֲלָתוֹ.</p>\n<p>שָׁנִינוּ שָׁם, בְּאַרְבַּע פְּעָמִים (בשנה) בְּשָׁעָה בְּכָל יוֹם הָעֵדֶן מְנַטֵּף עַל הַגָּן, וְיוֹצֵא מֵאוֹתָם הַטִּפּוֹת נָהָר גָּדוֹל הַמִּתְחַלֵּק לְאַרְבָּעָה רָאשִׁים, וּשְׁמוֹנֶה וְאַרְבָּעִים טִפּוֹת מְנַטֵּף בְּכָל יוֹם, וּמִשָּׁם שְׂבֵעִים אִילָנֵי הַגָּן. זֶהוּ שֶׁכָּתוּב (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה'. רַבִּי תַּנְחוּם אָמַר, מִכָּאן (שם) מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו. אֵיזוֹ הִיא עֲלִיָּה? זֶהוּ עֵדֶן. וְעֵדֶן בְּאֵיזֶה מָקוֹם הוּא? רַבִּי יְהוּדָה אָמַר, לְמַעְלָה מֵעֲרָבוֹת הוּא. רַבִּי יוֹסֵי אָמַר, בַּעֲרָבוֹת הוּא, שֶׁהֲרֵי שָׁנִינוּ, שָׁם גִּנְזֵי חַיִּים טוֹבִים בְּרָכָה וְשָׁלוֹם וְנִשְׁמָתָן שֶׁל צַדִּיקִים, וְהַגָּנוּז הָעֶלְיוֹן. הוּא עֵדֶן לְמַטָּה מְכֻוָּן כְּנֶגְדּוֹ גַּן בָּאָרֶץ וְנוֹטֵל מִמֶּנּוּ שֶׁפַע בְּכָל יוֹם.</p>\n<p>אָמַר רַבִּי אַבָּהוּ, שְׁמוֹנָה וְאַרְבָּעִים נְבִיאִים עָמְדוּ לָהֶם לְיִשְׂרָאֵל, וְכָל אֶחָד נָטַל בְּחֶלְקוֹ תַּמְצִית טִפָּה אַחַת מֵאוֹתָם טִפּוֹת שֶׁל עֵדֶן, שֶׁהֵם שְׁמוֹנֶה וְאַרְבָּעִים טִפּוֹת. וּמָה אִם כָּל נָבִיא שֶׁנָּטַל טִפָּה אַחַת מֵהֶן הָיְתָה מַעֲלָתוֹ בְּרוּחַ הַקֹּדֶשׁ עַל כָּל הַשְּׁאָר - אָדָם הָרִאשׁוֹן שֶׁהָיָה מְקַבֵּל מִשְּׁמוֹנֶה וְאַרְבָּעִים לֹא כָּל שֶׁכֵּן. מִכָּאן אַתָּה לָמֵד כַּמָּה הָיְתָה חָכְמָתוֹ.</p>\n<p>רַבִּי בָּא אָמַר רַב כַּהֲנָא, וְכִי מֵאַיִן הָיָה לָהֶם לַנְּבִיאִים מֵאוֹתָן הַטִּפּוֹת? אֶלָּא כָּךְ שָׁנִינוּ, בְּכָל טִפָּה וְטִפָּה הַיּוֹצֵאת מֵעֵדֶן, רוּחַ חָכְמָה יוֹצֵאת עִמּוֹ, וְעַל כֵּן נִגְזַר בַּמִּשְׁנָה: יֵשׁ מַיִם שֶׁמְּגַדְּלִים חֲכָמִים, וְיֵשׁ מַיִם שֶׁמְּגַדְּלִים טִפְּשִׁים. וְאוֹתָם הַמַּיִם שֶׁמְּגַדְּלִים חֲכָמִים, אוֹתָם הַמַּיִם הָיוּ מִטִּפּוֹת שֶׁל עֵדֶן.</p>\n<p>שֶׁאָמַר רַבִּי יוֹסֵי, הַמַּיִם שֶׁבָּהֶם טִפּוֹת יוֹשְׁבִים (נ\"א: יתרים) מִכָּל אוֹתָם אַרְבַּעַת הַנְּהָרוֹת הָרִאשׁוֹנִים, הוּא שֶׁכָּתוּב (בראשית ב) שֵׁם הָאֶחָד פִּישׁוֹן. מַה זֶּה שֵׁם הָאֶחָד פִּישׁוֹן? הַמְיֻחָד מִכֻּלָּם פִּישׁוֹן, וְהוּא הַנּוֹפֵל בְּאֶרֶץ מִצְרַיִם, וּלְפִיכָךְ הָיְתָה חָכְמַת (לישראל) מִצְרַיִם יוֹתֵר מִכָּל הָעוֹלָם.</p>\n<p>וּמִשֶּׁנִּגְזְרָה הַגְּזֵרָה שֶׁאָבְדָה חָכְמַת מִצְרַיִם, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם הַטִּפּוֹת וְזָרַק אוֹתָם בְּאוֹתוֹ הַגָּן, בְּאוֹתוֹ הַנָּהָר שֶׁל גַּן עֵדֶן, שֶׁכָּתוּב (שם) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְזֶה הָיָה מוֹלִיד אַרְבָּעָה אֲחֵרִים, וְהָאֶחָד הַמְיֻחָד הַנּוֹלַד מִמֶּנּוּ פִּישׁוֹן הָיָה. מִשֶּׁנִּטְּלוּ אֵלּוּ הַטִּפּוֹת שֶׁלֹּא יָצְאוּ מֵהַגָּן, אָבְדָה הַחָכְמָה מִמִּצְרַיִם.</p>\n<p>וּמֵאוֹתָהּ הָרוּחַ שֶׁהָיְתָה יוֹצֵאת מֵעֵדֶן, תִּמְצוּ (ימצו) כָּל נָבִיא וְנָבִיא, וְהַיְנוּ שֶׁכָּתוּב מִתְהַלֵּךְ בַּגַּן לְרוּחַ הַיּוֹם. וְגָנוּז זֶה בְּגַן עֵדֶן לֶעָתִיד לָבֹא, וְזֶה הוּא הַנָּהָר שֶׁרָאָה יְחֶזְקֵאל בִּנְבוּאָתוֹ, וְעַל כֵּן אָמַר הַכָּתוּב (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה' וְגוֹ'. שֶׁאוֹתָם מַיִם תָּמִיד מְגַדְּלִים הַיְדִיעָה בָּעוֹלָם.</p>"]]});
